SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for t_blog_article
-- ----------------------------
DROP TABLE IF EXISTS `t_blog_article`;
CREATE TABLE `t_blog_article`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `classify_id` bigint NULL DEFAULT NULL COMMENT '分类ID',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标题',
  `title_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标题图',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `author` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '作者',
  `ori_flag` tinyint(1) NULL DEFAULT 1 COMMENT '是否原创：1-是，0-否',
  `sort` int NULL DEFAULT 0 COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '发布状态：1-已发布，0-未发布',
  `publish_time` datetime(0) NULL DEFAULT NULL COMMENT '发布时间',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '文章类型:0原文，1外链',
  `link_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '外链地址',
  `read_num` int NULL DEFAULT 0 COMMENT '阅读量',
  `like_num` int NULL DEFAULT 0 COMMENT '点赞量',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '说明',
  `deleted` tinyint(1) NOT NULL DEFAULT 0,
  `create_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 38 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '博客文章' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of t_blog_article
-- ----------------------------
INSERT INTO `t_blog_article` VALUES (3, 4, 'mac 安装node.js', NULL, '<ul><li><a href=\"https://blog.csdn.net/m0_67402341/article/details/126112558#mac_nodejs_2\" target=\"_self\">mac 安装node.js</a></li><ul><li><a href=\"https://blog.csdn.net/m0_67402341/article/details/126112558#_3\" target=\"_self\">第一步：官网下载</a></li><li><a href=\"https://blog.csdn.net/m0_67402341/article/details/126112558#_9\" target=\"_self\">第二步：安装</a></li><li><a href=\"https://blog.csdn.net/m0_67402341/article/details/126112558#_13\" target=\"_self\">第三步：验证</a></li><li><a href=\"https://blog.csdn.net/m0_67402341/article/details/126112558#_19\" target=\"_self\">第四步：环境配置</a></li></ul></ul><p>mac 安装node.js<br>第一步：官网下载<br>访问nodejs官网，链接: https://nodejs.org/en/，选择红色选框内的点击安装。<br>LTS是稳定版。<br>Current是最新版本，最新的功能特性都在这里面。<br><br><br>第二步：安装<br>点击 在 Finder 中显示，双击刚下载的文件，按步骤默认安装就行。<br><br><br>第三步：验证<br>安装完成后，打开终端，<br>输入 npm -v 和 node -v两个命令,<br>如下图出现版本信息，说明安装成功<br><br><br>第四步：环境配置<br>以上验证结束后，就可以进行环境配置了<br>打开Mac 终端，配置全局环境变量<br>键盘输入【vim .bash_profile】进入编辑状态<br>打开之后添加一行代码：PATH=$PATH:/usr/local/bin/<br>点击【esc】退出编辑状态，此时无法对内容进行修改<br>键盘输入【:wq!】强制保存并退出vim，回到终端的界面<br>重新打开终端，输入node，就会进入node环境<br><br><br>control+c 按两次退出node环境<br><br>到此，mac安装node.js就成功了。</p>', 'yeee', 1, 0, 1, '2021-07-14 04:55:29', 0, NULL, 1248, 1, NULL, 0, NULL, '2021-07-14 04:55:29', 'admin', '2023-07-12 09:05:06');
INSERT INTO `t_blog_article` VALUES (4, 3, 'Java编程-高并发情况下接口性能优化实践-提升吞吐量TPS', NULL, '<p>&nbsp;&nbsp;&nbsp;&nbsp;记得前段时间工作中接到一个任务是优化一个下单接口的性能提高接口的吞吐量TPS，前期通过arthas工具跟踪接口的具体方法调用链路及耗时，发现了影响此接口的性能瓶颈主要是加锁的方式，后来变更了锁的方式后性能大大提升。</p><p>&nbsp;&nbsp;&nbsp;&nbsp;程序的大致逻辑是，1.判断余额是否足够&gt;2.保存订单信息&gt;3.扣减钱包余额&gt;4.记录钱包流水；现在我将优化前及优化后的代码分别通过jmeter设置100个线程1s内请求这个接口通过实验观察效果，代码的变更及压测结果大家可以往下看<br></p><h3>优化前：采用悲观锁</h3><blockquote><p>该方案是将整个事务方法加锁，可以保证下单时接口成功的响应，即使余额不足也会友好的返回余额不足的提示，但是不足的是客户端用户等待的时间较长；此种方案如果是用在商品秒杀销量优先场景下也不是很合适。</p></blockquote><h3><em>&gt;代码</em></h3><div><img src=\"https://img-blog.csdnimg.cn/img_convert/28caaecdbbfce481e64c2d20915228a6.png#pic_center\" style=\"max-width:100%;\"><img src=\"https://img-blog.csdnimg.cn/img_convert/d9b2895f933e096e63eded737cbdd7d6.png#pic_center\" style=\"max-width: 100%;\"></div><h3>&gt;压测结果（tps 8.4左右）<br></h3><p><img src=\"https://img-blog.csdnimg.cn/img_convert/6a627ab9001df2d4c403241618a126ac.png#pic_center\" style=\"max-width:100%;\"><br></p><p><img0.08859649122807017\" src=\"https://mmbiz.qpic.cn/mmbiz_png/cSKvw8A2EM9ibfLtkODW8lRT5ibktLiaeBpgT56PGXuaExzVsXILmRDGpzXB09b20v5bsBjicrm9CLuBEyDqQ0MF2A/640?wx_fmt=png\"></img0.08859649122807017\"></p><p></p><h3>优化后：采用乐观锁</h3><blockquote><p>这种方式不会显示的给整个方法上锁，依赖的是通过sql的条件判断达到数据同步防止超卖情况发生，此种方式实际就是乐观锁的一种实现，经测试程序的吞吐量提升了很多，但是不足的是并发高的情况下扣减余额时仅仅通过数据库返回的更新结果不能准确判断是余额不足发生更新异常。</p></blockquote><p><img0.14719626168224298\" src=\"https://mmbiz.qpic.cn/mmbiz_png/cSKvw8A2EM9ibfLtkODW8lRT5ibktLiaeBpcpLhke9PrJJoOdW6uUMbwTBw1zVogtzfnbvIdmc3p0zfAKVuoicf28A/640?wx_fmt=png\"></img0.14719626168224298\"></p><p><img0.5814111261872456\" src=\"https://mmbiz.qpic.cn/mmbiz_png/cSKvw8A2EM9ibfLtkODW8lRT5ibktLiaeBpSrkL1AR2JGuhnKIckPsG8bXnxPWnVPW0pycSG50b1csJQVxEHzIaYQ/640?wx_fmt=png\"></img0.5814111261872456\"></p><p><img0.24285714285714285\" src=\"https://mmbiz.qpic.cn/mmbiz_png/cSKvw8A2EM9ibfLtkODW8lRT5ibktLiaeBpUicicb4v19iagFuy8cMDfNuibJw6HJF7UCF38cJZsuibJoZCpVn6tjh3uSw/640?wx_fmt=png\"></img0.24285714285714285\"></p><h3><img src=\"https://img-blog.csdnimg.cn/img_convert/1cc7d811f9617605e930fb86a01b0e3d.png#pic_center\" style=\"max-width:100%;\"><img src=\"https://img-blog.csdnimg.cn/img_convert/37f8455edfa5573db3de7ca72e0409a9.png#pic_center\" style=\"font-size: 14px; max-width: 100%;\"></h3><h3>&gt;压测结果（tps 30左右）<br></h3><p><img src=\"https://img-blog.csdnimg.cn/img_convert/77b27d4f80bec8da3f447e83d63e20ce.png#pic_center\" style=\"max-width:100%;\"><br></p><p><img0.08604038630377524\" src=\"https://mmbiz.qpic.cn/mmbiz_png/cSKvw8A2EM9ibfLtkODW8lRT5ibktLiaeBpT5JjCZmP9XqH37WNBNWJsrSXRtF1hicm1PYNvq2GzDticWrSJ6QXY4Xg/640?wx_fmt=png\"></img0.08604038630377524\"></p><h3>总结</h3><p>通常影响接口的吞吐量有可能就是锁的粒度的大小，在保证数据同步性的同时我们要根据具体场景具体分析评估后采用合适的锁。</p><p><br></p>', 'yeee', 1, 0, 1, '2021-08-28 12:53:00', 0, NULL, 1085, 0, NULL, 0, NULL, '2021-08-28 12:53:00', 'admin', '2023-07-18 09:32:15');
INSERT INTO `t_blog_article` VALUES (5, 4, '基于java配置nginx获取真实IP代码实例', NULL, '<p>1、java代码<br></p><table border=\"0\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tbody><tr><th style=\"text-align: left;\"><span style=\"font-weight: normal;\">/** 获取客户端IP */</span><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;</code><code>public</code> <code>static</code> <code>final</code> <code>String getClientIp(HttpServletRequest request) {</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>String ip = request.getHeader(</code><code>\"X-Forwarded-For\"</code><code>);</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>if</code> <code>(StringUtils.isBlank(ip) || </code><code>\"unknown\"</code><code>.equalsIgnoreCase(ip)|| </code><code>\"127.0.0.1\"</code><code>.equalsIgnoreCase(ip)) {</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code><code>ip = request.getHeader(</code><code>\"Proxy-Client-IP\"</code><code>);</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>}</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>if</code> <code>(StringUtils.isBlank(ip) || </code><code>\"unknown\"</code><code>.equalsIgnoreCase(ip)|| </code><code>\"127.0.0.1\"</code><code>.equalsIgnoreCase(ip)) {</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code><code>ip = request.getHeader(</code><code>\"WL-Proxy-Client-IP\"</code><code>);</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>}</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>if</code> <code>(StringUtils.isBlank(ip) || </code><code>\"unknown\"</code><code>.equalsIgnoreCase(ip)|| </code><code>\"127.0.0.1\"</code><code>.equalsIgnoreCase(ip)) {</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code><code>ip = request.getHeader(</code><code>\"X-Real-IP\"</code><code>);</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>}</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>if</code> <code>(StringUtils.isBlank(ip) || </code><code>\"unknown\"</code><code>.equalsIgnoreCase(ip)|| </code><code>\"127.0.0.1\"</code><code>.equalsIgnoreCase(ip)) {</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code><code>ip = request.getRemoteAddr();</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>}</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>if</code> <code>(StringUtils.isBlank(ip) ||</code><code>\"127.0.0.1\"</code><code>.equals(ip)|| ip.indexOf(</code><code>\":\"</code><code>) &gt; -</code><code>1</code><code>) {</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code><code>try</code> <code>{</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code><code>ip = InetAddress.getLocalHost().getHostAddress();</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code><code>} </code><code>catch</code> <code>(UnknownHostException e) {</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code><code>ip = </code><code>null</code><code>;</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code><code>}</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>}</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>// 对于通过多个代理的情况，第一个IP为客户端真实IP,多个IP按照\',\'分割</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>if</code> <code>(ip != </code><code>null</code> <code>&amp;&amp; ip.length() &gt; </code><code>15</code><code>) {</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code><code>if</code> <code>(ip.indexOf(</code><code>\",\"</code><code>) &gt; </code><code>0</code><code>) {</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code><code>ip = ip.substring(</code><code>0</code><code>, ip.indexOf(</code><code>\",\"</code><code>));</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code><code>}</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>}</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>return</code> <code>ip;</code></span></div><span style=\"font-weight: normal;\"><code style=\"font-size: 14px;\">&nbsp;&nbsp;</code><code style=\"font-size: 14px;\">}</code><br></span></th></tr></tbody></table><p><br>2、nginx需要进行相应修改,重点 proxy_set_header<br></p><table border=\"0\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\"><tbody><tr><th style=\"text-align: left;\"><span style=\"font-weight: normal;\"></span>&nbsp;<span style=\"font-weight: normal;\">server {</span><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>listen&nbsp; xxxx;</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>server_name 127.0.0.1;</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code># 静态页面目录</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>root&nbsp;&nbsp; xxxxxxxxxx;</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code># 默认首页</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>index&nbsp;&nbsp; login.html;</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>proxy_set_header Host $http_host;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>proxy_set_header X-Real-IP $remote_addr;</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>proxy_set_header REMOTE-HOST $remote_addr;</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;</code></span></div><div><span style=\"font-weight: normal;\">&nbsp;</span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>add_header Access-Control-Allow-Origin *;</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>add_header Access-Control-Allow-Methods </code><code>\'GET,POST\'</code><code>;</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>add_header Access-Control-Allow-Headers </code><code>\'DNT,X-Mx-ReqToken,Keep-Alive,User-Agent,X-Requested-With,If-Modified-Since,Cache-Control,Content-Type,Authorization\'</code><code>;</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>#proxy_cookie_path /* /*;</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>client_max_body_size&nbsp; 100m;</code></span></div><div><span style=\"font-weight: normal;\">&nbsp;</span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>location / {</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code><code>proxy_set_header Host $http_host;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code><code>proxy_set_header X-Real-IP $remote_addr;</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code><code>proxy_set_header REMOTE-HOST $remote_addr;</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code><code>proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code>&nbsp;</span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code><code>proxy_set_header Upgrade $http_upgrade;</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code><code>proxy_set_header Connection </code><code>\"upgrade\"</code><code>;</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code><code>add_header Access-Control-Allow-Origin *;</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code><code>add_header Access-Control-Allow-Headers </code><code>\'DNT,X-Mx-ReqToken,Keep-Alive,User-Agent,X-Requested-With,If-Modified-Since,Cache-Control,Content-Type,Authorization\'</code><code>;</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code><code>add_header Access-Control-Allow-Methods GET,POST,OPTIONS;</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</code><code>......</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;&nbsp;&nbsp;</code><code>}</code></span></div><div><span style=\"font-weight: normal;\"><code>&nbsp;&nbsp;</code><code>}</code></span></div></th></tr></tbody></table>', 'yeee', 1, 0, 1, '2021-07-17 15:17:51', 0, NULL, 1105, 36, NULL, 0, NULL, '2021-07-17 15:17:51', 'admin', '2023-07-18 09:33:15');
INSERT INTO `t_blog_article` VALUES (7, 1, 'CrowdFunding（众筹系统）', NULL, '<pre><span id=\"LC1\">    此系统是作者本人在上学期间使用java + servlet + jsp 基础语言开发，没有使用任何现在主流框架，如ssm，maven，很适合新手学习。</span>\n<span id=\"LC2\">此外数据源使用了c3p0连接池，同时系统支持mysql-8，并且兼容mysql5.7</span></pre><pre><span style=\"background-color: rgb(249, 150, 59);\"><span style=\"font-weight: bold;\"><a href=\"https://gitee.com/quhailong/CrowdFunding.git\" target=\"_blank\" style=\"\">码云：</a>https://gitee.com/quhailong/CrowdFunding.git</span><br></span></pre><p><span style=\"background-color: rgb(249, 150, 59);\"><a href=\"https://github.com/quhailong1995/CrowdFunding.git\" target=\"_blank\" style=\"\">GitHub：</a>https://github.com/quhailong1995/CrowdFunding.git</span></p><pre><h2>一、使用</h2><p>1.复制git地址拉取项目然后进行构建</p><p>2.所需依赖jar包位置：/WebContent/WEB-INF/lib</p><p>3.web服务器：Tomcat，</p><p>4.创建数据库名称，运行sql文件，sql文件位置：/sql</p><p>此外项目有问题欢迎提出 ，安装运行过程中遇到问题可以联系我的 QQ ： 1324459373，qq 群：69405215</p><h2><a id=\"二项目概述\" href=\"https://gitee.com/quhailong/CrowdFunding#%E4%BA%8C%E9%A1%B9%E7%9B%AE%E6%A6%82%E8%BF%B0\"></a>二、项目概述</h2><p>基础流程介绍（发布项目--审核--用户支持购买项目服务）</p><p>后台项目审核页面地址 ${根页面url}/admin ; 管理员账号：admin，密码：123456</p><h3><a id=\"一注册登陆后发起项目\" href=\"https://gitee.com/quhailong/CrowdFunding#%E4%B8%80%E6%B3%A8%E5%86%8C%E7%99%BB%E9%99%86%E5%90%8E%E5%8F%91%E8%B5%B7%E9%A1%B9%E7%9B%AE\"></a>一、注册登陆后发起项目</h3><h4><a id=\"1基础信息\" href=\"https://gitee.com/quhailong/CrowdFunding#1%E5%9F%BA%E7%A1%80%E4%BF%A1%E6%81%AF\"></a>1.基础信息</h4><p><img src=\"https://oos.yeee.vip/1.%E5%8F%91%E8%B5%B7%E9%A1%B9%E7%9B%AE-%E5%9F%BA%E7%A1%80%E4%BF%A1%E6%81%AF.png\" alt=\"image\"></p><h4><a id=\"2项目信息\" href=\"https://gitee.com/quhailong/CrowdFunding#2%E9%A1%B9%E7%9B%AE%E4%BF%A1%E6%81%AF\"></a>2.项目信息</h4><p><img src=\"https://oos.yeee.vip/2.%E5%8F%91%E8%B5%B7%E9%A1%B9%E7%9B%AE-%E9%A1%B9%E7%9B%AE%E4%BF%A1%E6%81%AF.png\" alt=\"image\"></p><h4><a id=\"3项目详情\" href=\"https://gitee.com/quhailong/CrowdFunding#3%E9%A1%B9%E7%9B%AE%E8%AF%A6%E6%83%85\"></a>3.项目详情</h4><p><img src=\"https://oos.yeee.vip/3.%E5%8F%91%E8%B5%B7%E9%A1%B9%E7%9B%AE-%E9%A1%B9%E7%9B%AE%E8%AF%A6%E6%83%85.png\" alt=\"image\"></p><h4><a id=\"4回报设置\" href=\"https://gitee.com/quhailong/CrowdFunding#4%E5%9B%9E%E6%8A%A5%E8%AE%BE%E7%BD%AE\"></a>4.回报设置</h4><p><img src=\"https://oos.yeee.vip/4.%E5%8F%91%E8%B5%B7%E9%A1%B9%E7%9B%AE-%E5%9B%9E%E6%8A%A5%E8%AE%BE%E7%BD%AE.png\" alt=\"image\"></p><h4><a id=\"5编辑预览\" href=\"https://gitee.com/quhailong/CrowdFunding#5%E7%BC%96%E8%BE%91%E9%A2%84%E8%A7%88\"></a>5.编辑预览</h4><p><img src=\"https://oos.yeee.vip/5.%E5%8F%91%E8%B5%B7%E9%A1%B9%E7%9B%AE-%E7%BC%96%E8%BE%91%E9%A2%84%E8%A7%88.png\" alt=\"image\"></p><h3><a id=\"二前台页面\" href=\"https://gitee.com/quhailong/CrowdFunding#%E4%BA%8C%E5%89%8D%E5%8F%B0%E9%A1%B5%E9%9D%A2\"></a>二、前台页面</h3><h4><a id=\"1项目详情\" href=\"https://gitee.com/quhailong/CrowdFunding#1%E9%A1%B9%E7%9B%AE%E8%AF%A6%E6%83%85\"></a>1.项目详情</h4><p><img src=\"https://oos.yeee.vip/13.%E6%B5%8B%E8%AF%95%E9%A1%B9%E7%9B%AE%20-%E8%AF%A6%E6%83%85%E9%A1%B5.png\" alt=\"image\"></p><h3><a id=\"三个人中心\" href=\"https://gitee.com/quhailong/CrowdFunding#%E4%B8%89%E4%B8%AA%E4%BA%BA%E4%B8%AD%E5%BF%83\"></a>三、个人中心</h3><h4><a id=\"1我的发起\" href=\"https://gitee.com/quhailong/CrowdFunding#1%E6%88%91%E7%9A%84%E5%8F%91%E8%B5%B7\"></a>1.我的发起</h4><p><img src=\"https://oos.yeee.vip/6.%E4%B8%AA%E4%BA%BA%E4%BF%A1%E6%81%AF-%E6%88%91%E7%9A%84%E5%8F%91%E8%B5%B7.png\" alt=\"image\"></p><h4><a id=\"2我的订单\" href=\"https://gitee.com/quhailong/CrowdFunding#2%E6%88%91%E7%9A%84%E8%AE%A2%E5%8D%95\"></a>2.我的订单</h4><p><img src=\"https://oos.yeee.vip/14.%E4%B8%AA%E4%BA%BA%E4%BF%A1%E6%81%AF-%E6%88%91%E7%9A%84%E8%AE%A2%E5%8D%95.png\" alt=\"image\"></p><h4><a id=\"3更新项目动态\" href=\"https://gitee.com/quhailong/CrowdFunding#3%E6%9B%B4%E6%96%B0%E9%A1%B9%E7%9B%AE%E5%8A%A8%E6%80%81\"></a>3.更新项目动态</h4><p><img src=\"https://oos.yeee.vip/11.%E5%8F%91%E8%B5%B7%E8%80%85%E6%9B%B4%E6%96%B0%E9%A1%B9%E7%9B%AE%E5%8A%A8%E6%80%81.png\" alt=\"image\"></p><h4><a id=\"3更新后页面\" href=\"https://gitee.com/quhailong/CrowdFunding#3%E6%9B%B4%E6%96%B0%E5%90%8E%E9%A1%B5%E9%9D%A2\"></a>3.更新后页面</h4><p><img src=\"https://oos.yeee.vip/12.%E6%9B%B4%E6%96%B0%E8%BF%9B%E5%B1%95%E5%90%8E.png\" alt=\"image\"></p><h3><a id=\"四平台后台管理\" href=\"https://gitee.com/quhailong/CrowdFunding#%E5%9B%9B%E5%B9%B3%E5%8F%B0%E5%90%8E%E5%8F%B0%E7%AE%A1%E7%90%86\"></a>四、平台后台管理</h3><h4><a id=\"1管理员登录\" href=\"https://gitee.com/quhailong/CrowdFunding#1%E7%AE%A1%E7%90%86%E5%91%98%E7%99%BB%E5%BD%95\"></a>1.管理员登录</h4><p><img src=\"https://oos.yeee.vip/7.%E7%AE%A1%E7%90%86%E5%91%98%E7%99%BB%E9%99%86%E9%A1%B5%E9%9D%A2.png\" alt=\"image\"></p><h4><a id=\"2待审核项目\" href=\"https://gitee.com/quhailong/CrowdFunding#2%E5%BE%85%E5%AE%A1%E6%A0%B8%E9%A1%B9%E7%9B%AE\"></a>2.待审核项目</h4><p><img src=\"https://oos.yeee.vip/8.%E5%90%8E%E5%8F%B0%E7%AE%A1%E7%90%86%E4%B8%AD%E5%BF%83-%E5%BE%85%E5%AE%A1%E6%A0%B8%E9%A1%B9%E7%9B%AE.png\" alt=\"image\"></p><h4><a id=\"3项目审核页面\" href=\"https://gitee.com/quhailong/CrowdFunding#3%E9%A1%B9%E7%9B%AE%E5%AE%A1%E6%A0%B8%E9%A1%B5%E9%9D%A2\"></a>3.项目审核页面</h4><p><img src=\"https://oos.yeee.vip/9.%E9%A1%B9%E7%9B%AE%E5%AE%A1%E6%A0%B8%E9%A1%B5%E9%9D%A2.png\" alt=\"image\"></p><h4><a id=\"4通过审核\" href=\"https://gitee.com/quhailong/CrowdFunding#4%E9%80%9A%E8%BF%87%E5%AE%A1%E6%A0%B8\"></a>4.通过审核</h4><p><img src=\"https://oos.yeee.vip/10.%E9%80%9A%E8%BF%87%E5%AE%A1%E6%A0%B8.png\" alt=\"image\"></p>\n\n</pre>', 'yeee', 1, 0, 1, '2021-07-18 07:33:54', 0, NULL, 1074, 3, '    此系统是作者本人在上学期间使用java + servlet + jsp 基础语言开发，没有使用任何现在主流框架，如ssm，maven，很适合新手学习。 此外数据源使用了c3p0连接池，同时系统支持mysql-8，并且兼容mysql5.7', 0, NULL, '2021-07-18 07:33:54', 'admin', '2023-07-18 09:33:01');
INSERT INTO `t_blog_article` VALUES (12, 1, 'spring-cloud-gateway', NULL, '<p><a href=\"https://mp.weixin.qq.com/s?__biz=MjM5NjU5OTA1Mg==&amp;mid=2449736126&amp;idx=1&amp;sn=db44688d3607cd58f565adce9e660765&amp;chksm=b11665dd8661eccbcbff32b58e45c4223f20aefd9753dfd1aa4b8073cf997c81c11405aeb610&amp;token=1106047369&amp;lang=zh_CN#rd\" target=\"_blank\">spring-cloud-gateway</a><br></p>', 'yeee', 1, 0, 1, '2021-11-19 01:41:28', 0, NULL, 1072, 0, NULL, 0, NULL, '2021-11-19 01:41:28', 'admin', '2023-07-18 09:31:45');
INSERT INTO `t_blog_article` VALUES (14, 1, 'Spring-Web-MVC', NULL, '<p><a href=\"https://mp.weixin.qq.com/s?__biz=MjM5NjU5OTA1Mg==&amp;mid=2449736119&amp;idx=1&amp;sn=0eb4cc34f63a58ccb78ff0274a7f460c&amp;chksm=b11665d48661ecc2e7eb8d876a6cb4c634afe84fb4af2235564a3eee174312a0fb038c025454&amp;token=1106047369&amp;lang=zh_CN#rd\" target=\"_blank\">Spring-Web-MVC</a><br></p>', 'yeee', 1, 0, 1, '2021-11-19 01:38:23', 0, NULL, 1051, 0, NULL, 0, NULL, '2021-11-19 01:38:23', 'admin', '2023-07-18 09:31:56');
INSERT INTO `t_blog_article` VALUES (15, 1, '开源框架：JavaWeb通用脚手架', 'https://cdn.zhuanzhi.ai/images/wx/c3530149bb2ed549c821d0729cd2d229', '<p><a href=\"https://gitee.com/quhailong/java-integrate\" target=\"_blank\">JAVA脚手架</a><br> <a href=\"https://gitee.com/yeeevip/yeee-memo\" target=\"_blank\">https://gitee.com/yeeevip/yeee-memo</a> </p><h2 style=\"text-align: start;\">框架说明</h2><ul><li style=\"text-align: start;\">经过多年实战经验中积累的一套基于<strong>SpringBoot</strong>的<strong>JavaWeb通用脚手架</strong></li><li style=\"text-align: start;\">核心设计思想是将web应用开发中的通用功能<strong>抽象组件化</strong>，从而达到<strong>轻量级</strong>、<strong>可拓展</strong></li></ul><h2 style=\"text-align: start;\">模块说明</h2><ul><li style=\"text-align: start;\">通用模块<strong>memo-parent</strong>，按功能抽取出来封装为<strong>starter</strong></li></ul><pre style=\"text-align: start;\"><code class=\"language-lua\">├memo-parent\n├\n├── memo-dependencies --------------------------- Maven依赖版本统一管理\n├\n├── memo-base ----------------------------------- 基础抽象模块\n    ├── base-config\n    ├── base-jdbc\n        ├── base-mybatis  \n        ├── base-mybatis-plus ------------------- 包含Mp基础依赖、分页插件、字段填充\n        └── base-tk-mapper\n    ├── base-model ------------------------------ 基础模型，包含公共的VO、异常类、注解类\n    ├── base-redis -- \n    ├── base-security-oauth2 -------------------- 认证授权基础，公共配置、依赖、常亮等\n    ├── base-swagger ---------------------------- 基于knife4j的swagger文档框架，只需要引入依赖添加配置即可使用\n    ├── base-util ------------------------------- 工具类，如hutool、json工具、guava等\n    ├── base-web -------------------------------- 基础web模块，引入web项目必须的springboot-web-starter、校验、监控等\n├    \n└── memo-common --------------------------------- 在memo-base的基础上封装的*通用模块*\n    ├── common-auth \n        ├── common-app-auth-client -------------- C端应用鉴权客户端\n        ├── common-app-auth-server -------------- C端应用鉴权服务端\n        ├── common-platform-auth-client --------- 管理端应用鉴权客户端\n        └── common-platform-auth-server --------- 管理端应用鉴权客户端\n    ├── common-dingtalk ------------------------- 钉钉开发接口通用功能，如聊天机器人通知等 \n    ├── common-domain\n    ├── common-httpclient\n        └── common-httpclient-okhttp ------------ okhttp3通用封装\n    ├── common-oss ------------------------------ 基于策略模式的通用oss工具组件封装，如ali、七牛云等\n    ├── common-springcloud \n        ├── common-springcloud-dependencies ----- Springcloud项目公共依赖，如服务配置、服务注册、负载均衡、限流熔断等\n        ├── common-springcloud-gray ------------- springcloud服务灰度发布组件\n            ├── common-springcloud-gray-common \n            ├── common-springcloud-gray-gateway - springcloud-gateway灰度发布依赖\n            └── common-springcloud-gray-inner --- springcloud内部服务灰度发布依赖\n        └── common-springcloud-openfeign\n    ├── common-sso ------------------------------ 单点登录\n        ├── common-sso-inner-app \n        └── common-sso-third-app\n    ├── common-web ------------------------------ 通用web模块，在base-web基础上加入jdbc、swagger等，较完整的web-starter\n    ├── common-websocket ------------------------ websocket \n    ├── common-websse --------------------------- websse\n    ├── common-wxsdk\n        ├── common-wx-ma ------------------------ 通用微信小程序组件\n        └── common-wx-mp ------------------------ 通用微信公众号组件\n    └── mybatis-encrypt-plugin ------------------ 借鉴其他开源封装的基于mybatis的数据库字段脱敏组件\n</code></pre><ul><li style=\"text-align: start;\">基于memo-parent的一些<strong>demo</strong></li></ul><pre style=\"text-align: start;\"><code class=\"language-lua\">├ \n├learn-example ---------------------------------- 临时学习测试\n├\n├solution-problem ------------------------------- 解决方案\n    ├── distribute-lock ------------------------- 分布式锁的不同实现方案\n    ├── jetcache -------------------------------- 分布式二级缓存\n    ├── netty\n    ├── sub-database-table ---------------------- 分表分表\n    ├── tokenizing ------------------------------ 分词\n    ├── webservice-example \n    └── websocket-example\n├ \n├middle-ware ------------------------------------ 中间件使用\n    ├── canal\n    ├── elasticsearch --------------------------- 搜索\n    ├── flink ----------------------------------- 大数据实时计算\n    ├── mongodb --------------------------------- 高性能、海量分布式存储\n    └── MQ -------------------------------------- 消息队列\n├ \n├spring-cloud ----------------------------------- springcloud的一些demo\n    ├── auth-sso -------------------------------- 身份认证、资源授权\n    ├── config ---------------------------------- 配置中心\n    ├── gateway --------------------------------- springcloud-gateway网关\n    ├── protect --------------------------------- 服务限流、降级熔断保护\n    ├── register -------------------------------- 注册中心\n    ├── rpc ------------------------------------- RPC远程服务调用\n    └── transaction ----------------------------- 分布式事务\n├ \n├third-sdk -------------------------------------- 三方SDK\n    ├── aliyun-sdk\n    ├── blockchain ------------------------------ 区块链\n    ├── third-pay ------------------------------- 基于策略模式封装统一支付DEMo，包含微信、支付宝各种支付方式的统一处理\n    └── weixin-sdk\n</code></pre><h2 style=\"text-align: start;\">快速开始</h2><blockquote style=\"text-align: start;\">基于memo-parent框架，如何快速搭建一个基于spring-security+oauth2的认证服/资源务器？</blockquote><ol><li style=\"text-align: start;\">下载yeee-memo工程，打包构建JavaWeb通用脚手架<strong>memo-parent</strong></li></ol><pre style=\"text-align: start;\"><code>git clone https://github.com/yeeevip/yeee-memo.git\n\ncd memo-parent &amp;&amp; mvn clean install\n</code></pre><ol><li style=\"text-align: start;\">使用IDEA新建maven工程web-auth-server，pom文件引入<strong>common-auth</strong>通用依赖</li></ol><pre style=\"text-align: start;\"><code class=\"language-xml\">&lt;?xml version=\"1.0\" encoding=\"UTF-8\"?&gt;\n&lt;project xmlns=\"http://maven.apache.org/POM/4.0.0\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xsi:schemaLocation=\"http://maven.apache.org/POM/4.0.0 http://maven.apache.org/xsd/maven-4.0.0.xsd\"&gt;\n    &lt;modelVersion&gt;4.0.0&lt;/modelVersion&gt;\n\n    &lt;parent&gt;\n        &lt;artifactId&gt;memo-parent&lt;/artifactId&gt;\n        &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\n        &lt;version&gt;3.2.2-SNAPSHOT&lt;/version&gt;\n        &lt;relativePath/&gt;\n    &lt;/parent&gt;\n\n    &lt;artifactId&gt;api-auth-server&lt;/artifactId&gt;\n\n    &lt;dependencies&gt;\n        &lt;dependency&gt;\n            &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\n            &lt;artifactId&gt;common-web&lt;/artifactId&gt;\n        &lt;/dependency&gt;\n        &lt;dependency&gt;\n            &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\n            &lt;artifactId&gt;common-springcloud-dependencies&lt;/artifactId&gt;\n        &lt;/dependency&gt;\n        &lt;dependency&gt;\n            &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\n            &lt;artifactId&gt;common-app-auth-server&lt;/artifactId&gt;\n        &lt;/dependency&gt;\n        &lt;dependency&gt;\n            &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\n            &lt;artifactId&gt;common-app-auth-client&lt;/artifactId&gt;\n        &lt;/dependency&gt;\n    &lt;/dependencies&gt;\n\n&lt;/project&gt;\n</code></pre><ol><li style=\"text-align: start;\">继承AbstractCustomUserDetailsService重写getSystemUserByUsername方法和自己系统用户关联起来</li></ol><pre style=\"text-align: start;\"><code class=\"language-java\">public class UserAuthService extends AbstractCustomUserDetailsService {\n    \n    @Override\n    public AuthUser getSystemUserByUsername(String username) {\n        SysUser sysUser = sysUserMapper.selectOne(username);\n        if (sysUser == null) {\n            throw new BizException(MessageConstant.USER_NOT_EXIST);\n        }\n        ...\n        SystemUserBo userBo = new SystemUserBo();\n        ...\n        return userBo;\n    }\n\n    @Override\n    public AuthUser getFrontUserByUsername(String username) {\n        return null;\n    }\n}\n</code></pre><ol><li style=\"text-align: start;\">在application.yml中添加以下配置</li></ol><pre style=\"text-align: start;\"><code>security:\n  oauth2:\n    resource:\n      token-info-uri: http://cloud-web-auth-server/auth-server/oauth/check_token\n    client:\n      client-id: ${spring.application.name}\n      client-secret: 123456\n      #      grant-type: password\n      access-token-uri: http://cloud-web-auth-server/auth-server/oauth/token\nyeee:\n  auth:\n    resource:\n      # 设置排除鉴权的URL\n      exclude:\n        - \"/system/register\"\n        - \"/system/login\"\n        - \"/anonymous/limit/api\"\n</code></pre><ol><li style=\"text-align: start;\">最后一个web认证服务器就搭建好了</li></ol><ul><li style=\"text-align: start;\">完整代码请参考：<a href=\"https://gitee.com/yeeevip/yeee-memo/tree/master/spring-cloud/auth-sso/web-auth-server\" target=\"\">web-auth-server</a></li></ul><h2 style=\"text-align: start;\">应用案例</h2><table style=\"width: auto; text-align: start;\"><tbody><tr><th colspan=\"1\" rowspan=\"1\" width=\"auto\">项目名称</th><th colspan=\"1\" rowspan=\"1\" width=\"auto\">描述</th><th colspan=\"1\" rowspan=\"1\" width=\"auto\">仓库地址</th></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\">yeee-blog</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\">轻量级博客系统</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\"><a href=\"https://gitee.com/yeeevip/yeee-blog.git\" target=\"\">仓库</a></td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\">yeee-chatgpt</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\">GPT微信小程序</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\"><a href=\"https://gitee.com/yeeevip/yeee-chatgpt.git\" target=\"\">仓库</a></td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\">yeee-crowdfunding</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\">毕业设计-众筹平台</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\"><a href=\"https://gitee.com/yeeevip/yeee-crowdfunding.git\" target=\"\">仓库</a></td></tr></tbody></table><h2 style=\"text-align: start;\">其他说明</h2><ol><li style=\"text-align: start;\">欢迎提交 PR，注意对应提交对应 dev 分支</li><li style=\"text-align: start;\">欢迎提交 [issue](https://github.com/yeeevip/yeee-memo/issues)，请写清楚遇到问题的原因、开发环境、复显步骤。</li></ol><h2 style=\"text-align: start;\">技术交流群</h2><ul><li style=\"text-align: start;\">QQ技术交流裙：96305921</li><li style=\"text-align: start;\">作者QQ：1324459373</li></ul><table style=\"width: auto; text-align: start;\"><tbody><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\"></td></tr></tbody></table><ul><li style=\"text-align: start;\"></li></ul><p><br></p>', '一页', 1, 0, 1, '2022-11-25 09:08:07', 1, 'https://gitee.com/yeeevip/yeee-memo.git', 1260, 0, '集成的基于SpringBoot/SpringCloud的轻量级可扩展JavaWeb通用脚手架，你只需引入对应封装好的Starter便可开始你的项目。封装了数据库操作、认证授权、单点登录、文档操作、工作流、统一支付、WebSocket/Sse、分词敏感词过滤、钉钉通知、微信SDK等各种开箱即用的Starter。还有中间件（如Es、Mq、Flink等）、各场景下应用解决方案的代码示例。', 0, NULL, '2022-11-25 09:08:07', 'admin', '2024-02-27 14:00:09');
INSERT INTO `t_blog_article` VALUES (16, 4, 'IDEA2022.3永久激活破解 Mac/Win最新激活 2023亲测可用！', NULL, '<blockquote><p>申明：本教程 IntelliJ IDEA 破解补丁、激活码均收集于网络，请勿商用，仅供个人学习使用，如有侵权，请联系作者删除。若条件允许，希望大家购买正版 ！</p></blockquote><blockquote><span style=\"font-weight: normal;\"></span>如果你的idea的版本是2022.3.x，本文为大家带来的激活破解方式。<br>此激活工具，向下兼容，即 2022.3 之前的版本，也都可以使用此方式激活。</blockquote><h2 id=\"1-下载工具包\">1 下载工具包</h2><p>工具包已放在百度云盘，请关注公众号&nbsp;<strong>一页一</strong>&nbsp;，在后台回复 【<strong>2022.3</strong>】 获取激活工具包。<img src=\"https://oos.yeee.vip/wxwp/qrcode_for_gh_472a7acc3579_258.jpg\" style=\"max-width: 100%;\"></p><blockquote><p>重要说明：</p><p>1、工具下载后，放到本地合适的位置，工具的存放路径不要含有汉字和空格，否则会造成激活失败</p><p>2、工具下载后，是zip压缩格式，一定要先解压，不然在后续激活时，会报错，提示找不到jar文件，“ja-netfilter.jar not found”。如果提示无法解压，请先安装zip解压工具。</p></blockquote><p>激活工具包解压后，目录文件如下：</p><p><img src=\"https://oos.yeee.vip/blog/%E6%88%AA%E5%B1%8F2023-06-10%2014.35.22.png\" style=\"max-width:100%;\"><br></p><h2 id=\"2-软件激活\">2 软件激活<button title=\"显示目录导航\" aria-expanded=\"false\"></button></h2><h3 id=\"21-一键配置\">2.1 一键配置</h3><p>执行 scripts 目录下的脚本文件，根据自己的计算机操作系统选择，Mac/Linux 执行&nbsp;<codecourier new\',=\"\" monospace&quot;;=\"\" margin:=\"\" 0px=\"\" 3px;=\"\" padding:=\"\" 0.065em=\"\" 0.4em;=\"\" border:=\"\" 0px;=\"\" font-size:=\"\" 0.87em;=\"\" vertical-align:=\"\" middle;=\"\" box-sizing:=\"\" border-box;=\"\" line-height:=\"\" 1.8;=\"\" display:=\"\" inline;=\"\" overflow-x:=\"\" auto;=\"\" border-radius:=\"\" 2px;=\"\" background-color:=\"\" var(--color-basic-200);=\"\" color:=\"\" rgb(216,=\"\" 59,=\"\" 100);=\"\" word-break:=\"\" break-word;\"=\"\"><span style=\"color: rgb(249, 150, 59);\">install.sh</span>&nbsp;，Windows 直接双击&nbsp;<codecourier new\',=\"\" monospace&quot;;=\"\" margin:=\"\" 0px=\"\" 3px;=\"\" padding:=\"\" 0.065em=\"\" 0.4em;=\"\" border:=\"\" 0px;=\"\" font-size:=\"\" 0.87em;=\"\" vertical-align:=\"\" middle;=\"\" box-sizing:=\"\" border-box;=\"\" line-height:=\"\" 1.8;=\"\" display:=\"\" inline;=\"\" overflow-x:=\"\" auto;=\"\" border-radius:=\"\" 2px;=\"\" background-color:=\"\" var(--color-basic-200);=\"\" color:=\"\" rgb(216,=\"\" 59,=\"\" 100);=\"\" word-break:=\"\" break-word;\"=\"\">i<span style=\"color: rgb(249, 150, 59);\">nstall-all-users.vbs</span>&nbsp;或者&nbsp;<codecourier new\',=\"\" monospace&quot;;=\"\" margin:=\"\" 0px=\"\" 3px;=\"\" padding:=\"\" 0.065em=\"\" 0.4em;=\"\" border:=\"\" 0px;=\"\" font-size:=\"\" 0.87em;=\"\" vertical-align:=\"\" middle;=\"\" box-sizing:=\"\" border-box;=\"\" line-height:=\"\" 1.8;=\"\" display:=\"\" inline;=\"\" overflow-x:=\"\" auto;=\"\" border-radius:=\"\" 2px;=\"\" background-color:=\"\" var(--color-basic-200);=\"\" color:=\"\" rgb(216,=\"\" 59,=\"\" 100);=\"\" word-break:=\"\" break-word;\"=\"\"><span style=\"color: rgb(249, 150, 59);\">install-current-user.vbs</span>&nbsp;脚本。这个脚本会向添加一些环境变量。Windows 系统&nbsp;<codecourier new\',=\"\" monospace&quot;;=\"\" margin:=\"\" 0px=\"\" 3px;=\"\" padding:=\"\" 0.065em=\"\" 0.4em;=\"\" border:=\"\" 0px;=\"\" font-size:=\"\" 0.87em;=\"\" vertical-align:=\"\" middle;=\"\" box-sizing:=\"\" border-box;=\"\" line-height:=\"\" 1.8;=\"\" display:=\"\" inline;=\"\" overflow-x:=\"\" auto;=\"\" border-radius:=\"\" 2px;=\"\" background-color:=\"\" var(--color-basic-200);=\"\" color:=\"\" rgb(216,=\"\" 59,=\"\" 100);=\"\" word-break:=\"\" break-word;\"=\"\">install-all-users.vbs&nbsp;和&nbsp;<codecourier new\',=\"\" monospace&quot;;=\"\" margin:=\"\" 0px=\"\" 3px;=\"\" padding:=\"\" 0.065em=\"\" 0.4em;=\"\" border:=\"\" 0px;=\"\" font-size:=\"\" 0.87em;=\"\" vertical-align:=\"\" middle;=\"\" box-sizing:=\"\" border-box;=\"\" line-height:=\"\" 1.8;=\"\" display:=\"\" inline;=\"\" overflow-x:=\"\" auto;=\"\" border-radius:=\"\" 2px;=\"\" background-color:=\"\" var(--color-basic-200);=\"\" color:=\"\" rgb(216,=\"\" 59,=\"\" 100);=\"\" word-break:=\"\" break-word;\"=\"\">install-current-user.vbs&nbsp;的区别在于环境变量是为系统还是当前用户添加环境变量。</codecourier></codecourier></codecourier></codecourier></codecourier></p><p>我这里是 Macos 执行如下</p><p><img src=\"https://oos.yeee.vip/blog/%E6%88%AA%E5%B1%8F2023-06-10%2014.41.31.png\" style=\"max-width:100%;\"><br></p><p>看到执行结果&nbsp;<strong>Done</strong>&nbsp;，表示执行成功。</p><blockquote><p>说明：</p><ol><li><p>因为脚本会修改环境变量，所以在 Windows 系统可能会被安全软件拦截，大家允许执行即可。</p></li><li><p>激活完成后，不要随便移动工具，更不要删除工具，否则会造成激活失效，甚至无法启动IDE。如果确实需要更换工具路径，路径更换完后，可以先执行对应的卸载脚本 uninstall，然后在重新按上面的步骤，执行安装脚本。</p></li><li><p>在之前的版本中，激活方式都是先打开试用，再在 vmoptions 配置一个 agent，从最近的版本开始，IDEA要求登录账号才可以试用，不打开时也无法修改 vmoptions 了，所以这个版本的激活工具才会提供一个一键安装脚本，本质上这个过程还是在配置 vmoptions</p></li></ol></blockquote><h3 id=\"22-使用激活码\">2.2 使用激活码</h3><p>之前的版本中，有使用服务器激活的方式。由于服务器激活，非常不稳定，此文不再推荐服务器激活的方式，但也仍旧给出，请自行选择：</p><p><span style=\"color: rgb(249, 150, 59); text-decoration-line: underline;\">最新激活码：2023.06.10亲测有效！！！</span></p><pre><code>6G5NXCPJZB---</code></pre><p><br></p><blockquote><p>最新激活码：<a href=\"https://aijihuo.cn/jetbrains-activation-codes.html\" target=\"_blank\" rel=\"noopener\">JETBRAINS激活码</a></p></blockquote><p>启动IntelliJ IDEA2022.3，输入激活码</p><p><img src=\"https://oos.yeee.vip/blog/%E6%88%AA%E5%B1%8F2023-06-10%2015.10.26.png\" style=\"max-width:100%;\"><br></p><p>点击 Activate 按钮之后，激活成功！<br></p><p><img src=\"https://oos.yeee.vip/blog/%E6%88%AA%E5%B1%8F2023-06-10%2015.02.06.png\" style=\"max-width:100%;\"><br></p><p>激活完成，Enjoy it ~<br></p><p><br></p><h2 id=\"3-常见问题\">3 常见问题</h2><p><font color=\"red\"><em>问题 1：这个激活工具，能用来激活之前版本的IDEA吗，比如2022.1 或 2022.2 ?</em></font></p><p>答：可以，但没必要。有什么理由不使用最新版的IDEA呢？</p><p><font color=\"red\"><em>问题 2：激活之后，下载的工具包可以删除吗？</em></font></p><p>答：工具压缩包可以删除，但解压出来之后，放在特定位置的文件目录，不能移动。若真想要移动，请先执行 script 目录中的 uninstall 脚本，移动之后再重新 install 配置。</p><p><font color=\"red\"><em>问题 3：提示激活码无效怎么办？</em></font></p><p>答：1、断开网络试试；</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2、终端输入<span style=\"color: rgb(194, 79, 74);\">echo $IDEA_VM_OPTIONS</span>命令，如果没有内容输出，说明配置未生效，电脑重启试试。</p><p>&nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;3、若还是不行，请评论区留言，或添加作者微信交流。</p><p><img src=\"https://oos.yeee.vip/wxwp/qrcode_for_gh_472a7acc3579_258.jpg\"><br></p>\n\n\n\n\n\n<div id=\"cnblogs_post_body\"><h2 id=\"4-最后\">4 最后</h2><p>本教程以 Jetbrains 官网版本 IntelliJ IDEA 2022.3.2 作为测试演示，本教程中涉及的所有内容，仅供学习参考，请勿用于一切商业用途！</p><blockquote><p>本文由公众号【一页一】撰写，欢迎关注，一起学习进步，期待你的关注！<br>谢谢你的阅读，希望此文对您有所助益！</p></blockquote></div><div></div><div id=\"post-signature\"><p>本文作者：一页、yeee</p><p>本文链接：https://www.yeee.vip/detail.html?id=10015</p><p>版权声明：本作品采用知识共享署名-非商业性使用-禁止演绎</p></div><h2 id=\"4-最后\"><svg aria-hidden=\"true\"><use xlink:href=\"#ac-food-chips\"></use></svg></h2><h2 id=\"1-下载工具包\"><svg aria-hidden=\"true\"><use xlink:href=\"#ac-food-eggyolkcake\"></use></svg></h2>', 'yeee', 1, 0, 1, NULL, 0, NULL, 1020, 0, '2023.06.10亲测可用！', 0, NULL, NULL, 'admin', '2023-07-12 09:04:58');
INSERT INTO `t_blog_article` VALUES (17, 3, '大厂是怎么用ThreadLocal？ThreadLocal核心原理分析', NULL, '<h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">介绍</span> </h2><p><span style=\"color: black;\"><strong>ThreadLocal</strong></span>是Java中的一个线程本地变量类。它可以让每个线程都有自己独立的变量副本，而不会相互影响。</p><ul><li>在多线程编程中，线程共享同一个变量可能会带来并发访问的问题。使用ThreadLocal可以解决这个问题，使得每个线程都能够拥有自己独立的变量，实现线程隔离。</li><li>同时可以利用ThreadLocal跨方法传递变量，可以减少代码的入侵更改，在项目公共组件设计架构中也是一个不错的选择。</li></ul><p><span style=\"color: black;\"><strong>ThreadLocal</strong></span>的使用很简单，其中主要有三个方法</p><ul><li>set(obj) ：设置需要存储的值</li><li>get() ：获取值</li><li>remove() ：移除值，此操作很有必要，否则会造成内存泄漏</li></ul><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">源码解读</span> </h2><p>对于<span style=\"color: black;\"><strong>ThreadLocal</strong></span>的使用想必大家都了解，但是究竟是怎么设置值、为什么在当前线程中可以获取到设置的值，它是怎么存储的，为什么使用时大家都说会有内存泄漏的隐患呢？<br>接下来可以带着这些疑惑来来从源码角度分析。</p><h3>核心源码</h3><ul><li>Thread类</li></ul><blockquote>Thread类中维护ThreadLocal.ThreadLocalMap属性，用于存储多个当前线程独有的本地变量值； ThreadLocalMap属性的初始化是在调用ThreadLocal的set(val)方法中完成的 ThreadLocalMap属性获取存储于的变量值是在调用ThreadLocal的get()方法中执行的</blockquote><pre><code class=\"language-java\">public class Thread implements Runnable {\n    ThreadLocal.ThreadLocalMap threadLocals = null;\n}</code></pre><ul><li>ThreadLocal类</li></ul><blockquote>严格来讲，ThreadLocal类更像是一个工具类，使用它的set(val)方法可以给当前线程设置值，get()获取值，remove()来清除值</blockquote><pre><code class=\"language-java\">public class ThreadLocal&lt;T&gt; {\n\n    // 用于给线程创建ThreadLocalMap对象\n    protected void createMap(Thread t, T firstValue) {\n        t.threadLocals = new ThreadLocalMap(this, firstValue);\n    }\n\n    public void set(T value) {\n        // 获取当前线程\n        Thread t = Thread.currentThread();\n        // 从当前线程中拿到ThreadLocalMap对象\n        ThreadLocalMap map = getMap(t);\n        if (map != null) {\n            // 直接设置值\n            map.set(this, value);\n        } else {\n            // 创建ThreadLocalMap对象并设置值\n            createMap(t, value);\n        }\n    }\n\n    public T get() {\n        Thread t = Thread.currentThread();\n        ThreadLocalMap map = getMap(t);\n        ...\n        return result;\n    }\n    \n    // ThreadLocalMap是由继承自WeakReference的Entry类型的数组来存储设置本地变量值的，Entry的k就是我们新建的ThreadLocal对象，值为需要存储的值\n    static class ThreadLocalMap {\n        private Entry[] table;\n        static class Entry extends WeakReference&lt;ThreadLocal&lt;?&gt;&gt; {\n            Object value;\n            Entry(ThreadLocal&lt;?&gt; k, Object v) {\n                super(k);\n                value = v;\n            }\n        }\n        ...\n    }\n}</code></pre><h3>ThreadLocal.get()的执行过程</h3><ol><li>Thread t = Thread.currentThread(); // 获取当前线程</li><li>ThreadLocalMap map = getMap(t); // 从当前线程中获取ThreadLocalMap</li><li>ThreadLocalMap.Entry e = map.getEntry(this); // 根据当前(ThreadLocal)this作为key获取ThreadLocalMap.Entry</li><li>T result = (T)e.value;// 从Entry中取出存储的value值</li></ol><h3>使用ThreadLocal为什么会有内存泄漏的隐患呢？</h3><blockquote>说到底还是用弱引用导致的原因，Java 弱引用（WeakReference） 弱引用也是用来描述非必需对象的，当JVM进行垃圾回收时，无论内存是否充足，都会回收被弱引用关联的对象。 当GC时，仅仅会把ThreadLocalMap.Entry中的用（WeakReference）修饰的key给回收掉，然而value还是会被ThreadLocalMap.Entry对象一直引用，导致无法回收； 所以，我们在使用ThreadLocal时要养成好的习惯，使用完之后一定要记得显示调用remove()方法去清除这个对象。</blockquote><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">使用案例</span> </h2><h3>案例一：全局用户Session设置</h3><h4>场景描述</h4><blockquote>用户登录后，会给客户端下发身份令牌Token，客户端每次请求服务端接口都会携带此Token来标识用户身份， 在此请求贯穿的整个线程生命周期中，我们在任何业务相关逻辑中都可以知道这个用户信息，从而可以记录操作日志等。</blockquote><h4>代码实现</h4><ul><li>1 创建用于存储用户信息的ThreadLocal对象的上下文类</li></ul><pre><code class=\"language-java\">public class ApiUserContext {\n\n    // 创建存储用户信息的ThreadLocal对象\n    public static ThreadLocal&lt;ApiUser&gt; curUser = new ThreadLocal&lt;&gt;();\n\n    // 返回当前用户ID\n    public static String getCurUserId() {\n        return getCurUser().getId();\n    }\n\n    // 返回当前用户\n    public static ApiUser getCurUser() {\n        return curUser.get();\n    }\n}</code></pre><ul><li>2 通过实现HandlerInterceptor的preHandle方法拦截请求解析用户信息</li></ul><pre><code class=\"language-java\">public class JwtAuthCheckInterceptor implements HandlerInterceptor {\n\n    @Override\n    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) throws Exception {\n        // 读取请求头的token\n        String token = request.getHeader(ApiAuthConstant.TOKEN);\n        // 解析校验JWT Token\n        Claims claims = jwtClientKit.getTokenClaim(token);\n        ApiUser authedUser = JacksonUtils.toJavaBean(claims.getSubject(), ApiUser.class);\n        // 将用户信息存储在ThreadLocal中\n        ApiUserContext.curUser.set(authedUser);\n        return true;\n    }\n\n    @Override\n    public void afterCompletion(HttpServletRequest request, HttpServletResponse response, Object handler, Exception ex) throws Exception {\n        // 从ThreadLocal中删除变量\n        ApiSecurityContext.curUser.remove();\n    }\n}</code></pre><ul><li>3 业务方法中使用</li></ul><pre><code class=\"language-java\">public class DemoBiz {\n    public void accessApi() {\n        ApiUser curUser = ApiUserContext.getCurUser();\n        log.info(\"userId = {}, username = {}, 访问接口\", curUser.getId(), curUser.getUsername());\n    }\n}</code></pre><ul><li>Github详细代码</li></ul><pre><code class=\"language-hljs\">https://gitee.com/yeeevip/yeee-memo/blob/master/memo-parent/memo-common/common-auth/common-app-auth-client/src/main/java/vip/yeee/memo/common/appauth/client/interceptor/JwtAuthCheckInterceptor.java</code></pre><h3>案例二：统一支付之上下文切换</h3><h4>场景描述</h4><blockquote>对于ToB的支付系统中，需要根据用户所属的租户来获取商户支付配置去调用三方支付接口进行下单，这时可以通过ThreadLocal 设置当前用户请求的支付配置上下文，在调用三方支付接口时可以随时获取达到跨方法的透传</blockquote><h4>代码实现</h4><ul><li>1 创建用于存储当前租户支付配置的ThreadLocal对象的上下文类</li></ul><pre><code class=\"language-java\">@Slf4j\npublic class PayContext {\n    \n    private final String lesseeId;\n    private final PayProperties payProperties;\n    private final WxPayConfigBO wxPayConfig;\n    private final AliPayConfigBO aliPayConfig;\n    private final static ThreadLocal&lt;PayContext&gt; PAY_CONTEXT_THREAD_LOCAL = new ThreadLocal&lt;&gt;();\n    \n    public PayContext(String lesseeId, PayProperties payProperties, WxPayConfigBO wxPayConfig, AliPayConfigBO aliPayConfig) {\n        this.lesseeId = lesseeId;\n        this.payProperties = payProperties;\n        this.wxPayConfig = wxPayConfig;\n        this.aliPayConfig = aliPayConfig;\n    }\n}</code></pre><ul><li>2 编写初始化支付上下文方法</li></ul><pre><code class=\"language-java\">public class PayContext {\n    public static void initContext(String lesseeId) {\n        try {\n            PayContext payContext = null;\n            // 部分代码省略，判断是否为空，不为空才新建PayContext对象\n            if (payContext == null) {\n                PayChannelConfigService channelConfigService = (PayChannelConfigService) SpringContextUtils.getBean(PayChannelConfigService.class);\n                PayProperties payProperties = (PayProperties) SpringContextUtils.getBean(PayProperties.class);\n                WxPayConfigBO wxPayConfigBO = channelConfigService.getWxPayChannelConfig(lesseeId);\n                AliPayConfigBO aliPayConfigBO = channelConfigService.getAliPayChannelConfig(lesseeId);\n                payContext = new PayContext(lesseeId, payProperties, wxPayConfigBO, aliPayConfigBO);\n            }\n            // 将支付上下文对象PayContext放置到ThreadLocal中\n            PAY_CONTEXT_THREAD_LOCAL.set(payContext);\n        } catch (Exception e) {\n            log.error(\"初始化支付上下文失败\", e);\n            throw new BizException(\"初始化支付上下文失败\");\n        }\n    }\n}</code></pre><ul><li>3 业务方法中使用</li></ul><pre><code class=\"language-java\">public class UnifiedPayOrderService {\n\n    public UnifiedOrderRespBO unifiedOrder(UnifiedOrderReqVO reqVO) throws Exception {\n        try {\n            // 初始化设置当前用户线程支付上下文\n            PayContext.initContext(reqVO.getLesseeId());\n            UnifiedOrderRespBO respBO = wxAppPayKit.unifiedOrder(reqBO);\n            return respBO;\n        } finally {\n            // 清除ThreadLocal对象\n            PayContext.clearContext();\n        }\n    }\n}\n\npublic class WxAppPayKit extends BaseWxPayKit {\n\n    @Override\n    public UnifiedOrderRespBO unifiedOrder(UnifiedOrderReqBO reqBO) {\n        try {\n            // 通过PayContext从ThreadLocal中获取当前租户支付配置\n            PayContext payContext = PayContext.getContext();\n            Config config = new Config(payContext);\n            wxPayService.setConfig(config);\n            UnifiedOrderRespBO respBO = wxPayService.createOrder(reqBO);\n            ... \n            ...\n            return respBO;\n        } catch (Exception e) {\n            log.info(\"【统一下单-微信APP支付】- 下单失败 reqBO = {}\", reqBO, e);\n            throw new BizException(e.getMessage());\n        }\n    }\n}</code></pre><ul><li>Github详细代码</li></ul><pre><code class=\"language-hljs\">https://gitee.com/yeeevip/yeee-memo/blob/master/third-sdk/third-pay/src/main/java/vip/yeee/memo/demo/thirdsdk/pay/paykit/PayContext.java</code></pre><p><br></p>', '一页', 1, 0, 1, '2023-07-05 10:10:10', 0, NULL, 1291, 266, NULL, 0, 'admin', '2023-07-05 18:06:55', 'admin', '2023-07-07 17:04:58');
INSERT INTO `t_blog_article` VALUES (19, 1, '架构师必备：如何基于springboot的自定义starter', NULL, '<p><br></p><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">基本介绍</span> </h2><p>在我们平时的<span style=\"color: black;\"><strong>Springboot</strong></span>应用程序开发中，我们经常把我们需要的starter引入，这样程序启动时就会把这个starter的相关功能自动配置到spring的应用程序容器中<br>，可以极大地简化我们的Spring应用程序开发和配置过程。</p><p>比如spring-boot-starter-web这个starter我们应该都很熟悉，通过引入这个starter我们程序就已经有了web服务器、springmvc等基本能力；<br>相较于传统的非springboot的web开发免去了引入相关依赖并编写众多配置文件的令人头疼的过程。</p><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">原理分析</span> </h2><h3>SPI机制</h3><p>SPI（Service Provider Interface），springboot的一种服务发现机制规范。具体实现形式是通过在项目resources里添加的spring.factories文件来指定<br>需要扫描的配置类去初始化到容器里。</p><h3>扫描流程</h3><ul><li>1、使用SpringApplication启动springboot程序</li></ul><pre><code class=\"language-java\">    SpringApplication.run(YeeeAppBootstrapApplication.class, args);</code></pre><ul><li>2、程序启动过程中，会调用到spring的AbstractApplicationContext刷新上下文，这个过程中会涉及到BeanDefinitions的定义及初始化</li></ul><pre><code class=\"language-java\">    refreshContext(ConfigurableApplicationContext context)</code></pre><ul><li>3、在refresh过程中，会有专门的ConfigPostProcessors来读取classes/META-INF/spring.factories文件中以EnableAutoConfiguration类标识的所有需要扫码的配置类 ，将其注册到BeanDefinitions中</li></ul><pre><code class=\"language-java\">    ...\r\n    invokeBeanFactoryPostProcessors(beanFactory);\r\n    ...\r\n    // 读取spring.factories文件中以EnableAutoConfiguration类标识的所有需要扫码的配置类\r\n    List&lt;String&gt; configurations = SpringFactoriesLoader.loadFactoryNames(EnableAutoConfiguration.class);\r\n    ...\r\n    // 注册到BeanFactory的beanDefinitionNames中\r\n    processConfigBeanDefinitions(BeanDefinitionRegistry registry)\r\n    ...</code></pre><ul><li>4、refresh最后就是BeanDefinitions的初始化了。</li></ul><pre><code class=\"language-java\">  finishBeanFactoryInitialization(beanFactory);</code></pre><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">怎么构建自定义的starter？</span> </h2><h3>案例：swagger2的公共starter</h3><h4>场景描述</h4><blockquote>在我们项目开发中swagger显然已经必不可少，在没有构建公共的starter后，我们每次使用swagger都需要引入许多依赖并且 还得写一些额外的配置类来初始化它；在封装成starter后我们只需要在pom中引入这个starter并且不需要额外配置就可以拥有这个功能。</blockquote><h4>具体构建过程</h4><ul><li>1、新建maven项目base-swagger，并且在/src/main/resources中新增文件夹METAINF，然后在METAINF中增加spring.factories文件</li><li><img src=\"./images/base-swagger-01.png\" alt=\"项目结构\" data-href=\"\" style=\"\"/></li><li>项目结构</li><li>2、编写swagger相关的配置类</li><li><img src=\"./images/base-swagger-02.png\" alt=\"配置类\" data-href=\"\" style=\"\"/></li><li>配置类</li><li>3、编写主配置类，并把全路径名写到spring.factories中</li></ul><pre><code class=\"language-java\">@ComponentScan({\"vip.yeee.memo.base.swagger.config\", \"springfox.documentation.schema\"})\r\npublic class SwaggerAutoConfigure {\r\n    \r\n    public SwaggerAutoConfigure() {\r\n        log.info(\"自动配置-swagger\");\r\n    }\r\n}\r\n\r\norg.springframework.boot.autoconfigure.EnableAutoConfiguration=\\\r\n        vip.yeee.memo.base.swagger.SwaggerAutoConfigure</code></pre><ul><li>4、在需要使用swagger的项目pom中引入该starter</li></ul><pre><code class=\"language-xml\">&lt;dependency&gt;\r\n    &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\r\n    &lt;artifactId&gt;base-swagger&lt;/artifactId&gt;\r\n&lt;/dependency&gt;</code></pre><ul><li>Github详细代码</li></ul><pre><code class=\"language-html\">// 1.自定义starter项目https://gitee.com/yeeevip/yeee-memo/tree/master/memo-parent/memo-base/base-swagger</code></pre><p><br></p>', '一页', 1, 0, 1, '2023-07-19 18:37:43', 0, NULL, 3473, 114, NULL, 0, 'admin', '2023-07-19 18:37:46', 'admin', '2023-07-19 18:41:17');
INSERT INTO `t_blog_article` VALUES (20, 1, '推荐：轻量级博客系统的设计与实现（YEEE.VIP）', '', '<p><a href=\"https://gitee.com/quhailong/java-integrate\" target=\"_blank\">JAVA脚手架</a><br> <a href=\"https://gitee.com/yeeevip/yeee-memo\" target=\"_blank\">https://gitee.com/yeeevip/yeee-memo</a> </p><h2 style=\"text-align: start;\">框架说明</h2><ul><li style=\"text-align: start;\">经过多年实战经验中积累的一套基于<strong>SpringBoot</strong>的<strong>JavaWeb通用脚手架</strong></li><li style=\"text-align: start;\">核心设计思想是将web应用开发中的通用功能<strong>抽象组件化</strong>，从而达到<strong>轻量级</strong>、<strong>可拓展</strong></li></ul><h2 style=\"text-align: start;\">模块说明</h2><ul><li style=\"text-align: start;\">通用模块<strong>memo-parent</strong>，按功能抽取出来封装为<strong>starter</strong></li></ul><pre style=\"text-align: start;\"><code class=\"language-lua\">├memo-parent\n├\n├── memo-dependencies --------------------------- Maven依赖版本统一管理\n├\n├── memo-base ----------------------------------- 基础抽象模块\n    ├── base-config\n    ├── base-jdbc\n        ├── base-mybatis  \n        ├── base-mybatis-plus ------------------- 包含Mp基础依赖、分页插件、字段填充\n        └── base-tk-mapper\n    ├── base-model ------------------------------ 基础模型，包含公共的VO、异常类、注解类\n    ├── base-redis -- \n    ├── base-security-oauth2 -------------------- 认证授权基础，公共配置、依赖、常亮等\n    ├── base-swagger ---------------------------- 基于knife4j的swagger文档框架，只需要引入依赖添加配置即可使用\n    ├── base-util ------------------------------- 工具类，如hutool、json工具、guava等\n    ├── base-web -------------------------------- 基础web模块，引入web项目必须的springboot-web-starter、校验、监控等\n├    \n└── memo-common --------------------------------- 在memo-base的基础上封装的*通用模块*\n    ├── common-auth \n        ├── common-app-auth-client -------------- C端应用鉴权客户端\n        ├── common-app-auth-server -------------- C端应用鉴权服务端\n        ├── common-platform-auth-client --------- 管理端应用鉴权客户端\n        └── common-platform-auth-server --------- 管理端应用鉴权客户端\n    ├── common-dingtalk ------------------------- 钉钉开发接口通用功能，如聊天机器人通知等 \n    ├── common-domain\n    ├── common-httpclient\n        └── common-httpclient-okhttp ------------ okhttp3通用封装\n    ├── common-oss ------------------------------ 基于策略模式的通用oss工具组件封装，如ali、七牛云等\n    ├── common-springcloud \n        ├── common-springcloud-dependencies ----- Springcloud项目公共依赖，如服务配置、服务注册、负载均衡、限流熔断等\n        ├── common-springcloud-gray ------------- springcloud服务灰度发布组件\n            ├── common-springcloud-gray-common \n            ├── common-springcloud-gray-gateway - springcloud-gateway灰度发布依赖\n            └── common-springcloud-gray-inner --- springcloud内部服务灰度发布依赖\n        └── common-springcloud-openfeign\n    ├── common-sso ------------------------------ 单点登录\n        ├── common-sso-inner-app \n        └── common-sso-third-app\n    ├── common-web ------------------------------ 通用web模块，在base-web基础上加入jdbc、swagger等，较完整的web-starter\n    ├── common-websocket ------------------------ websocket \n    ├── common-websse --------------------------- websse\n    ├── common-wxsdk\n        ├── common-wx-ma ------------------------ 通用微信小程序组件\n        └── common-wx-mp ------------------------ 通用微信公众号组件\n    └── mybatis-encrypt-plugin ------------------ 借鉴其他开源封装的基于mybatis的数据库字段脱敏组件\n</code></pre><ul><li style=\"text-align: start;\">基于memo-parent的一些<strong>demo</strong></li></ul><pre style=\"text-align: start;\"><code class=\"language-lua\">├ \n├learn-example ---------------------------------- 临时学习测试\n├\n├solution-problem ------------------------------- 解决方案\n    ├── distribute-lock ------------------------- 分布式锁的不同实现方案\n    ├── jetcache -------------------------------- 分布式二级缓存\n    ├── netty\n    ├── sub-database-table ---------------------- 分表分表\n    ├── tokenizing ------------------------------ 分词\n    ├── webservice-example \n    └── websocket-example\n├ \n├middle-ware ------------------------------------ 中间件使用\n    ├── canal\n    ├── elasticsearch --------------------------- 搜索\n    ├── flink ----------------------------------- 大数据实时计算\n    ├── mongodb --------------------------------- 高性能、海量分布式存储\n    └── MQ -------------------------------------- 消息队列\n├ \n├spring-cloud ----------------------------------- springcloud的一些demo\n    ├── auth-sso -------------------------------- 身份认证、资源授权\n    ├── config ---------------------------------- 配置中心\n    ├── gateway --------------------------------- springcloud-gateway网关\n    ├── protect --------------------------------- 服务限流、降级熔断保护\n    ├── register -------------------------------- 注册中心\n    ├── rpc ------------------------------------- RPC远程服务调用\n    └── transaction ----------------------------- 分布式事务\n├ \n├third-sdk -------------------------------------- 三方SDK\n    ├── aliyun-sdk\n    ├── blockchain ------------------------------ 区块链\n    ├── third-pay ------------------------------- 基于策略模式封装统一支付DEMo，包含微信、支付宝各种支付方式的统一处理\n    └── weixin-sdk\n</code></pre><h2 style=\"text-align: start;\">快速开始</h2><blockquote style=\"text-align: start;\">基于memo-parent框架，如何快速搭建一个基于spring-security+oauth2的认证服/资源务器？</blockquote><ol><li style=\"text-align: start;\">下载yeee-memo工程，打包构建JavaWeb通用脚手架<strong>memo-parent</strong></li></ol><pre style=\"text-align: start;\"><code>git clone https://github.com/yeeevip/yeee-memo.git\n\ncd memo-parent &amp;&amp; mvn clean install\n</code></pre><ol><li style=\"text-align: start;\">使用IDEA新建maven工程web-auth-server，pom文件引入<strong>common-auth</strong>通用依赖</li></ol><pre style=\"text-align: start;\"><code class=\"language-xml\">&lt;?xml version=\"1.0\" encoding=\"UTF-8\"?&gt;\n&lt;project xmlns=\"http://maven.apache.org/POM/4.0.0\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xsi:schemaLocation=\"http://maven.apache.org/POM/4.0.0 http://maven.apache.org/xsd/maven-4.0.0.xsd\"&gt;\n    &lt;modelVersion&gt;4.0.0&lt;/modelVersion&gt;\n\n    &lt;parent&gt;\n        &lt;artifactId&gt;memo-parent&lt;/artifactId&gt;\n        &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\n        &lt;version&gt;3.2.2-SNAPSHOT&lt;/version&gt;\n        &lt;relativePath/&gt;\n    &lt;/parent&gt;\n\n    &lt;artifactId&gt;api-auth-server&lt;/artifactId&gt;\n\n    &lt;dependencies&gt;\n        &lt;dependency&gt;\n            &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\n            &lt;artifactId&gt;common-web&lt;/artifactId&gt;\n        &lt;/dependency&gt;\n        &lt;dependency&gt;\n            &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\n            &lt;artifactId&gt;common-springcloud-dependencies&lt;/artifactId&gt;\n        &lt;/dependency&gt;\n        &lt;dependency&gt;\n            &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\n            &lt;artifactId&gt;common-app-auth-server&lt;/artifactId&gt;\n        &lt;/dependency&gt;\n        &lt;dependency&gt;\n            &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\n            &lt;artifactId&gt;common-app-auth-client&lt;/artifactId&gt;\n        &lt;/dependency&gt;\n    &lt;/dependencies&gt;\n\n&lt;/project&gt;\n</code></pre><ol><li style=\"text-align: start;\">继承AbstractCustomUserDetailsService重写getSystemUserByUsername方法和自己系统用户关联起来</li></ol><pre style=\"text-align: start;\"><code class=\"language-java\">public class UserAuthService extends AbstractCustomUserDetailsService {\n    \n    @Override\n    public AuthUser getSystemUserByUsername(String username) {\n        SysUser sysUser = sysUserMapper.selectOne(username);\n        if (sysUser == null) {\n            throw new BizException(MessageConstant.USER_NOT_EXIST);\n        }\n        ...\n        SystemUserBo userBo = new SystemUserBo();\n        ...\n        return userBo;\n    }\n\n    @Override\n    public AuthUser getFrontUserByUsername(String username) {\n        return null;\n    }\n}\n</code></pre><ol><li style=\"text-align: start;\">在application.yml中添加以下配置</li></ol><pre style=\"text-align: start;\"><code>security:\n  oauth2:\n    resource:\n      token-info-uri: http://cloud-web-auth-server/auth-server/oauth/check_token\n    client:\n      client-id: ${spring.application.name}\n      client-secret: 123456\n      #      grant-type: password\n      access-token-uri: http://cloud-web-auth-server/auth-server/oauth/token\nyeee:\n  auth:\n    resource:\n      # 设置排除鉴权的URL\n      exclude:\n        - \"/system/register\"\n        - \"/system/login\"\n        - \"/anonymous/limit/api\"\n</code></pre><ol><li style=\"text-align: start;\">最后一个web认证服务器就搭建好了</li></ol><ul><li style=\"text-align: start;\">完整代码请参考：<a href=\"https://gitee.com/yeeevip/yeee-memo/tree/master/spring-cloud/auth-sso/web-auth-server\" target=\"\">web-auth-server</a></li></ul><h2 style=\"text-align: start;\">应用案例</h2><table style=\"width: auto; text-align: start;\"><tbody><tr><th colspan=\"1\" rowspan=\"1\" width=\"auto\">项目名称</th><th colspan=\"1\" rowspan=\"1\" width=\"auto\">描述</th><th colspan=\"1\" rowspan=\"1\" width=\"auto\">仓库地址</th></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\">yeee-blog</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\">轻量级博客系统</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\"><a href=\"https://gitee.com/yeeevip/yeee-blog.git\" target=\"\">仓库</a></td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\">yeee-chatgpt</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\">GPT微信小程序</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\"><a href=\"https://gitee.com/yeeevip/yeee-chatgpt.git\" target=\"\">仓库</a></td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\">yeee-crowdfunding</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\">毕业设计-众筹平台</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\"><a href=\"https://gitee.com/yeeevip/yeee-crowdfunding.git\" target=\"\">仓库</a></td></tr></tbody></table><h2 style=\"text-align: start;\">其他说明</h2><ol><li style=\"text-align: start;\">欢迎提交 PR，注意对应提交对应 dev 分支</li><li style=\"text-align: start;\">欢迎提交 [issue](https://github.com/yeeevip/yeee-memo/issues)，请写清楚遇到问题的原因、开发环境、复显步骤。</li></ol><h2 style=\"text-align: start;\">技术交流群</h2><ul><li style=\"text-align: start;\">QQ技术交流裙：96305921</li><li style=\"text-align: start;\">作者QQ：1324459373</li></ul><table style=\"width: auto; text-align: start;\"><tbody><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\"></td></tr></tbody></table><ul><li style=\"text-align: start;\"></li></ul><p><br></p>', '一页', 1, 0, 1, '2023-07-18 16:00:22', 1, 'https://gitee.com/yeeevip/yeee-blog', 969, 0, '基于springboot+vue开发的轻量级博客系统', 0, 'admin', '2022-11-25 09:08:07', 'admin', '2023-07-21 16:09:18');
INSERT INTO `t_blog_article` VALUES (21, 1, '推荐：众筹平台系统的设计与实现', '', '<p><a href=\"https://gitee.com/quhailong/java-integrate\" target=\"_blank\">JAVA脚手架</a><br> <a href=\"https://gitee.com/yeeevip/yeee-memo\" target=\"_blank\">https://gitee.com/yeeevip/yeee-memo</a> </p><h2 style=\"text-align: start;\">框架说明</h2><ul><li style=\"text-align: start;\">经过多年实战经验中积累的一套基于<strong>SpringBoot</strong>的<strong>JavaWeb通用脚手架</strong></li><li style=\"text-align: start;\">核心设计思想是将web应用开发中的通用功能<strong>抽象组件化</strong>，从而达到<strong>轻量级</strong>、<strong>可拓展</strong></li></ul><h2 style=\"text-align: start;\">模块说明</h2><ul><li style=\"text-align: start;\">通用模块<strong>memo-parent</strong>，按功能抽取出来封装为<strong>starter</strong></li></ul><pre style=\"text-align: start;\"><code class=\"language-lua\">├memo-parent\n├\n├── memo-dependencies --------------------------- Maven依赖版本统一管理\n├\n├── memo-base ----------------------------------- 基础抽象模块\n    ├── base-config\n    ├── base-jdbc\n        ├── base-mybatis  \n        ├── base-mybatis-plus ------------------- 包含Mp基础依赖、分页插件、字段填充\n        └── base-tk-mapper\n    ├── base-model ------------------------------ 基础模型，包含公共的VO、异常类、注解类\n    ├── base-redis -- \n    ├── base-security-oauth2 -------------------- 认证授权基础，公共配置、依赖、常亮等\n    ├── base-swagger ---------------------------- 基于knife4j的swagger文档框架，只需要引入依赖添加配置即可使用\n    ├── base-util ------------------------------- 工具类，如hutool、json工具、guava等\n    ├── base-web -------------------------------- 基础web模块，引入web项目必须的springboot-web-starter、校验、监控等\n├    \n└── memo-common --------------------------------- 在memo-base的基础上封装的*通用模块*\n    ├── common-auth \n        ├── common-app-auth-client -------------- C端应用鉴权客户端\n        ├── common-app-auth-server -------------- C端应用鉴权服务端\n        ├── common-platform-auth-client --------- 管理端应用鉴权客户端\n        └── common-platform-auth-server --------- 管理端应用鉴权客户端\n    ├── common-dingtalk ------------------------- 钉钉开发接口通用功能，如聊天机器人通知等 \n    ├── common-domain\n    ├── common-httpclient\n        └── common-httpclient-okhttp ------------ okhttp3通用封装\n    ├── common-oss ------------------------------ 基于策略模式的通用oss工具组件封装，如ali、七牛云等\n    ├── common-springcloud \n        ├── common-springcloud-dependencies ----- Springcloud项目公共依赖，如服务配置、服务注册、负载均衡、限流熔断等\n        ├── common-springcloud-gray ------------- springcloud服务灰度发布组件\n            ├── common-springcloud-gray-common \n            ├── common-springcloud-gray-gateway - springcloud-gateway灰度发布依赖\n            └── common-springcloud-gray-inner --- springcloud内部服务灰度发布依赖\n        └── common-springcloud-openfeign\n    ├── common-sso ------------------------------ 单点登录\n        ├── common-sso-inner-app \n        └── common-sso-third-app\n    ├── common-web ------------------------------ 通用web模块，在base-web基础上加入jdbc、swagger等，较完整的web-starter\n    ├── common-websocket ------------------------ websocket \n    ├── common-websse --------------------------- websse\n    ├── common-wxsdk\n        ├── common-wx-ma ------------------------ 通用微信小程序组件\n        └── common-wx-mp ------------------------ 通用微信公众号组件\n    └── mybatis-encrypt-plugin ------------------ 借鉴其他开源封装的基于mybatis的数据库字段脱敏组件\n</code></pre><ul><li style=\"text-align: start;\">基于memo-parent的一些<strong>demo</strong></li></ul><pre style=\"text-align: start;\"><code class=\"language-lua\">├ \n├learn-example ---------------------------------- 临时学习测试\n├\n├solution-problem ------------------------------- 解决方案\n    ├── distribute-lock ------------------------- 分布式锁的不同实现方案\n    ├── jetcache -------------------------------- 分布式二级缓存\n    ├── netty\n    ├── sub-database-table ---------------------- 分表分表\n    ├── tokenizing ------------------------------ 分词\n    ├── webservice-example \n    └── websocket-example\n├ \n├middle-ware ------------------------------------ 中间件使用\n    ├── canal\n    ├── elasticsearch --------------------------- 搜索\n    ├── flink ----------------------------------- 大数据实时计算\n    ├── mongodb --------------------------------- 高性能、海量分布式存储\n    └── MQ -------------------------------------- 消息队列\n├ \n├spring-cloud ----------------------------------- springcloud的一些demo\n    ├── auth-sso -------------------------------- 身份认证、资源授权\n    ├── config ---------------------------------- 配置中心\n    ├── gateway --------------------------------- springcloud-gateway网关\n    ├── protect --------------------------------- 服务限流、降级熔断保护\n    ├── register -------------------------------- 注册中心\n    ├── rpc ------------------------------------- RPC远程服务调用\n    └── transaction ----------------------------- 分布式事务\n├ \n├third-sdk -------------------------------------- 三方SDK\n    ├── aliyun-sdk\n    ├── blockchain ------------------------------ 区块链\n    ├── third-pay ------------------------------- 基于策略模式封装统一支付DEMo，包含微信、支付宝各种支付方式的统一处理\n    └── weixin-sdk\n</code></pre><h2 style=\"text-align: start;\">快速开始</h2><blockquote style=\"text-align: start;\">基于memo-parent框架，如何快速搭建一个基于spring-security+oauth2的认证服/资源务器？</blockquote><ol><li style=\"text-align: start;\">下载yeee-memo工程，打包构建JavaWeb通用脚手架<strong>memo-parent</strong></li></ol><pre style=\"text-align: start;\"><code>git clone https://github.com/yeeevip/yeee-memo.git\n\ncd memo-parent &amp;&amp; mvn clean install\n</code></pre><ol><li style=\"text-align: start;\">使用IDEA新建maven工程web-auth-server，pom文件引入<strong>common-auth</strong>通用依赖</li></ol><pre style=\"text-align: start;\"><code class=\"language-xml\">&lt;?xml version=\"1.0\" encoding=\"UTF-8\"?&gt;\n&lt;project xmlns=\"http://maven.apache.org/POM/4.0.0\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xsi:schemaLocation=\"http://maven.apache.org/POM/4.0.0 http://maven.apache.org/xsd/maven-4.0.0.xsd\"&gt;\n    &lt;modelVersion&gt;4.0.0&lt;/modelVersion&gt;\n\n    &lt;parent&gt;\n        &lt;artifactId&gt;memo-parent&lt;/artifactId&gt;\n        &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\n        &lt;version&gt;3.2.2-SNAPSHOT&lt;/version&gt;\n        &lt;relativePath/&gt;\n    &lt;/parent&gt;\n\n    &lt;artifactId&gt;api-auth-server&lt;/artifactId&gt;\n\n    &lt;dependencies&gt;\n        &lt;dependency&gt;\n            &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\n            &lt;artifactId&gt;common-web&lt;/artifactId&gt;\n        &lt;/dependency&gt;\n        &lt;dependency&gt;\n            &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\n            &lt;artifactId&gt;common-springcloud-dependencies&lt;/artifactId&gt;\n        &lt;/dependency&gt;\n        &lt;dependency&gt;\n            &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\n            &lt;artifactId&gt;common-app-auth-server&lt;/artifactId&gt;\n        &lt;/dependency&gt;\n        &lt;dependency&gt;\n            &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\n            &lt;artifactId&gt;common-app-auth-client&lt;/artifactId&gt;\n        &lt;/dependency&gt;\n    &lt;/dependencies&gt;\n\n&lt;/project&gt;\n</code></pre><ol><li style=\"text-align: start;\">继承AbstractCustomUserDetailsService重写getSystemUserByUsername方法和自己系统用户关联起来</li></ol><pre style=\"text-align: start;\"><code class=\"language-java\">public class UserAuthService extends AbstractCustomUserDetailsService {\n    \n    @Override\n    public AuthUser getSystemUserByUsername(String username) {\n        SysUser sysUser = sysUserMapper.selectOne(username);\n        if (sysUser == null) {\n            throw new BizException(MessageConstant.USER_NOT_EXIST);\n        }\n        ...\n        SystemUserBo userBo = new SystemUserBo();\n        ...\n        return userBo;\n    }\n\n    @Override\n    public AuthUser getFrontUserByUsername(String username) {\n        return null;\n    }\n}\n</code></pre><ol><li style=\"text-align: start;\">在application.yml中添加以下配置</li></ol><pre style=\"text-align: start;\"><code>security:\n  oauth2:\n    resource:\n      token-info-uri: http://cloud-web-auth-server/auth-server/oauth/check_token\n    client:\n      client-id: ${spring.application.name}\n      client-secret: 123456\n      #      grant-type: password\n      access-token-uri: http://cloud-web-auth-server/auth-server/oauth/token\nyeee:\n  auth:\n    resource:\n      # 设置排除鉴权的URL\n      exclude:\n        - \"/system/register\"\n        - \"/system/login\"\n        - \"/anonymous/limit/api\"\n</code></pre><ol><li style=\"text-align: start;\">最后一个web认证服务器就搭建好了</li></ol><ul><li style=\"text-align: start;\">完整代码请参考：<a href=\"https://gitee.com/yeeevip/yeee-memo/tree/master/spring-cloud/auth-sso/web-auth-server\" target=\"\">web-auth-server</a></li></ul><h2 style=\"text-align: start;\">应用案例</h2><table style=\"width: auto; text-align: start;\"><tbody><tr><th colspan=\"1\" rowspan=\"1\" width=\"auto\">项目名称</th><th colspan=\"1\" rowspan=\"1\" width=\"auto\">描述</th><th colspan=\"1\" rowspan=\"1\" width=\"auto\">仓库地址</th></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\">yeee-blog</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\">轻量级博客系统</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\"><a href=\"https://gitee.com/yeeevip/yeee-blog.git\" target=\"\">仓库</a></td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\">yeee-chatgpt</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\">GPT微信小程序</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\"><a href=\"https://gitee.com/yeeevip/yeee-chatgpt.git\" target=\"\">仓库</a></td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\">yeee-crowdfunding</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\">毕业设计-众筹平台</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\"><a href=\"https://gitee.com/yeeevip/yeee-crowdfunding.git\" target=\"\">仓库</a></td></tr></tbody></table><h2 style=\"text-align: start;\">其他说明</h2><ol><li style=\"text-align: start;\">欢迎提交 PR，注意对应提交对应 dev 分支</li><li style=\"text-align: start;\">欢迎提交 [issue](https://github.com/yeeevip/yeee-memo/issues)，请写清楚遇到问题的原因、开发环境、复显步骤。</li></ol><h2 style=\"text-align: start;\">技术交流群</h2><ul><li style=\"text-align: start;\">QQ技术交流裙：96305921</li><li style=\"text-align: start;\">作者QQ：1324459373</li></ul><table style=\"width: auto; text-align: start;\"><tbody><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\"></td></tr></tbody></table><ul><li style=\"text-align: start;\"></li></ul><p><br></p>', '一页', 1, 0, 1, '2023-07-18 00:00:00', 1, 'https://gitee.com/yeeevip/yeee-crowdfunding', 53, 0, '基于springboot+mybatis-plus+oauth2+vue开发众筹平台项目系统', 0, 'admin', '2022-11-25 09:08:07', 'admin', '2023-07-21 16:09:26');
INSERT INTO `t_blog_article` VALUES (22, 1, '推荐：chatgpt开源免费使用，基于api搭建自己的gpt服务', NULL, '<p><a href=\"https://gitee.com/quhailong/java-integrate\" target=\"_blank\">JAVA脚手架</a><br> <a href=\"https://gitee.com/yeeevip/yeee-memo\" target=\"_blank\">https://gitee.com/yeeevip/yeee-memo</a> </p><h2 style=\"text-align: start;\">框架说明</h2><ul><li style=\"text-align: start;\">经过多年实战经验中积累的一套基于<strong>SpringBoot</strong>的<strong>JavaWeb通用脚手架</strong></li><li style=\"text-align: start;\">核心设计思想是将web应用开发中的通用功能<strong>抽象组件化</strong>，从而达到<strong>轻量级</strong>、<strong>可拓展</strong></li></ul><h2 style=\"text-align: start;\">模块说明</h2><ul><li style=\"text-align: start;\">通用模块<strong>memo-parent</strong>，按功能抽取出来封装为<strong>starter</strong></li></ul><pre style=\"text-align: start;\"><code class=\"language-lua\">├memo-parent\n├\n├── memo-dependencies --------------------------- Maven依赖版本统一管理\n├\n├── memo-base ----------------------------------- 基础抽象模块\n    ├── base-config\n    ├── base-jdbc\n        ├── base-mybatis  \n        ├── base-mybatis-plus ------------------- 包含Mp基础依赖、分页插件、字段填充\n        └── base-tk-mapper\n    ├── base-model ------------------------------ 基础模型，包含公共的VO、异常类、注解类\n    ├── base-redis -- \n    ├── base-security-oauth2 -------------------- 认证授权基础，公共配置、依赖、常亮等\n    ├── base-swagger ---------------------------- 基于knife4j的swagger文档框架，只需要引入依赖添加配置即可使用\n    ├── base-util ------------------------------- 工具类，如hutool、json工具、guava等\n    ├── base-web -------------------------------- 基础web模块，引入web项目必须的springboot-web-starter、校验、监控等\n├    \n└── memo-common --------------------------------- 在memo-base的基础上封装的*通用模块*\n    ├── common-auth \n        ├── common-app-auth-client -------------- C端应用鉴权客户端\n        ├── common-app-auth-server -------------- C端应用鉴权服务端\n        ├── common-platform-auth-client --------- 管理端应用鉴权客户端\n        └── common-platform-auth-server --------- 管理端应用鉴权客户端\n    ├── common-dingtalk ------------------------- 钉钉开发接口通用功能，如聊天机器人通知等 \n    ├── common-domain\n    ├── common-httpclient\n        └── common-httpclient-okhttp ------------ okhttp3通用封装\n    ├── common-oss ------------------------------ 基于策略模式的通用oss工具组件封装，如ali、七牛云等\n    ├── common-springcloud \n        ├── common-springcloud-dependencies ----- Springcloud项目公共依赖，如服务配置、服务注册、负载均衡、限流熔断等\n        ├── common-springcloud-gray ------------- springcloud服务灰度发布组件\n            ├── common-springcloud-gray-common \n            ├── common-springcloud-gray-gateway - springcloud-gateway灰度发布依赖\n            └── common-springcloud-gray-inner --- springcloud内部服务灰度发布依赖\n        └── common-springcloud-openfeign\n    ├── common-sso ------------------------------ 单点登录\n        ├── common-sso-inner-app \n        └── common-sso-third-app\n    ├── common-web ------------------------------ 通用web模块，在base-web基础上加入jdbc、swagger等，较完整的web-starter\n    ├── common-websocket ------------------------ websocket \n    ├── common-websse --------------------------- websse\n    ├── common-wxsdk\n        ├── common-wx-ma ------------------------ 通用微信小程序组件\n        └── common-wx-mp ------------------------ 通用微信公众号组件\n    └── mybatis-encrypt-plugin ------------------ 借鉴其他开源封装的基于mybatis的数据库字段脱敏组件\n</code></pre><ul><li style=\"text-align: start;\">基于memo-parent的一些<strong>demo</strong></li></ul><pre style=\"text-align: start;\"><code class=\"language-lua\">├ \n├learn-example ---------------------------------- 临时学习测试\n├\n├solution-problem ------------------------------- 解决方案\n    ├── distribute-lock ------------------------- 分布式锁的不同实现方案\n    ├── jetcache -------------------------------- 分布式二级缓存\n    ├── netty\n    ├── sub-database-table ---------------------- 分表分表\n    ├── tokenizing ------------------------------ 分词\n    ├── webservice-example \n    └── websocket-example\n├ \n├middle-ware ------------------------------------ 中间件使用\n    ├── canal\n    ├── elasticsearch --------------------------- 搜索\n    ├── flink ----------------------------------- 大数据实时计算\n    ├── mongodb --------------------------------- 高性能、海量分布式存储\n    └── MQ -------------------------------------- 消息队列\n├ \n├spring-cloud ----------------------------------- springcloud的一些demo\n    ├── auth-sso -------------------------------- 身份认证、资源授权\n    ├── config ---------------------------------- 配置中心\n    ├── gateway --------------------------------- springcloud-gateway网关\n    ├── protect --------------------------------- 服务限流、降级熔断保护\n    ├── register -------------------------------- 注册中心\n    ├── rpc ------------------------------------- RPC远程服务调用\n    └── transaction ----------------------------- 分布式事务\n├ \n├third-sdk -------------------------------------- 三方SDK\n    ├── aliyun-sdk\n    ├── blockchain ------------------------------ 区块链\n    ├── third-pay ------------------------------- 基于策略模式封装统一支付DEMo，包含微信、支付宝各种支付方式的统一处理\n    └── weixin-sdk\n</code></pre><h2 style=\"text-align: start;\">快速开始</h2><blockquote style=\"text-align: start;\">基于memo-parent框架，如何快速搭建一个基于spring-security+oauth2的认证服/资源务器？</blockquote><ol><li style=\"text-align: start;\">下载yeee-memo工程，打包构建JavaWeb通用脚手架<strong>memo-parent</strong></li></ol><pre style=\"text-align: start;\"><code>git clone https://github.com/yeeevip/yeee-memo.git\n\ncd memo-parent &amp;&amp; mvn clean install\n</code></pre><ol><li style=\"text-align: start;\">使用IDEA新建maven工程web-auth-server，pom文件引入<strong>common-auth</strong>通用依赖</li></ol><pre style=\"text-align: start;\"><code class=\"language-xml\">&lt;?xml version=\"1.0\" encoding=\"UTF-8\"?&gt;\n&lt;project xmlns=\"http://maven.apache.org/POM/4.0.0\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xsi:schemaLocation=\"http://maven.apache.org/POM/4.0.0 http://maven.apache.org/xsd/maven-4.0.0.xsd\"&gt;\n    &lt;modelVersion&gt;4.0.0&lt;/modelVersion&gt;\n\n    &lt;parent&gt;\n        &lt;artifactId&gt;memo-parent&lt;/artifactId&gt;\n        &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\n        &lt;version&gt;3.2.2-SNAPSHOT&lt;/version&gt;\n        &lt;relativePath/&gt;\n    &lt;/parent&gt;\n\n    &lt;artifactId&gt;api-auth-server&lt;/artifactId&gt;\n\n    &lt;dependencies&gt;\n        &lt;dependency&gt;\n            &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\n            &lt;artifactId&gt;common-web&lt;/artifactId&gt;\n        &lt;/dependency&gt;\n        &lt;dependency&gt;\n            &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\n            &lt;artifactId&gt;common-springcloud-dependencies&lt;/artifactId&gt;\n        &lt;/dependency&gt;\n        &lt;dependency&gt;\n            &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\n            &lt;artifactId&gt;common-app-auth-server&lt;/artifactId&gt;\n        &lt;/dependency&gt;\n        &lt;dependency&gt;\n            &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\n            &lt;artifactId&gt;common-app-auth-client&lt;/artifactId&gt;\n        &lt;/dependency&gt;\n    &lt;/dependencies&gt;\n\n&lt;/project&gt;\n</code></pre><ol><li style=\"text-align: start;\">继承AbstractCustomUserDetailsService重写getSystemUserByUsername方法和自己系统用户关联起来</li></ol><pre style=\"text-align: start;\"><code class=\"language-java\">public class UserAuthService extends AbstractCustomUserDetailsService {\n    \n    @Override\n    public AuthUser getSystemUserByUsername(String username) {\n        SysUser sysUser = sysUserMapper.selectOne(username);\n        if (sysUser == null) {\n            throw new BizException(MessageConstant.USER_NOT_EXIST);\n        }\n        ...\n        SystemUserBo userBo = new SystemUserBo();\n        ...\n        return userBo;\n    }\n\n    @Override\n    public AuthUser getFrontUserByUsername(String username) {\n        return null;\n    }\n}\n</code></pre><ol><li style=\"text-align: start;\">在application.yml中添加以下配置</li></ol><pre style=\"text-align: start;\"><code>security:\n  oauth2:\n    resource:\n      token-info-uri: http://cloud-web-auth-server/auth-server/oauth/check_token\n    client:\n      client-id: ${spring.application.name}\n      client-secret: 123456\n      #      grant-type: password\n      access-token-uri: http://cloud-web-auth-server/auth-server/oauth/token\nyeee:\n  auth:\n    resource:\n      # 设置排除鉴权的URL\n      exclude:\n        - \"/system/register\"\n        - \"/system/login\"\n        - \"/anonymous/limit/api\"\n</code></pre><ol><li style=\"text-align: start;\">最后一个web认证服务器就搭建好了</li></ol><ul><li style=\"text-align: start;\">完整代码请参考：<a href=\"https://gitee.com/yeeevip/yeee-memo/tree/master/spring-cloud/auth-sso/web-auth-server\" target=\"\">web-auth-server</a></li></ul><h2 style=\"text-align: start;\">应用案例</h2><table style=\"width: auto; text-align: start;\"><tbody><tr><th colspan=\"1\" rowspan=\"1\" width=\"auto\">项目名称</th><th colspan=\"1\" rowspan=\"1\" width=\"auto\">描述</th><th colspan=\"1\" rowspan=\"1\" width=\"auto\">仓库地址</th></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\">yeee-blog</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\">轻量级博客系统</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\"><a href=\"https://gitee.com/yeeevip/yeee-blog.git\" target=\"\">仓库</a></td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\">yeee-chatgpt</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\">GPT微信小程序</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\"><a href=\"https://gitee.com/yeeevip/yeee-chatgpt.git\" target=\"\">仓库</a></td></tr><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\">yeee-crowdfunding</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\">毕业设计-众筹平台</td><td colspan=\"1\" rowspan=\"1\" width=\"auto\"><a href=\"https://gitee.com/yeeevip/yeee-crowdfunding.git\" target=\"\">仓库</a></td></tr></tbody></table><h2 style=\"text-align: start;\">其他说明</h2><ol><li style=\"text-align: start;\">欢迎提交 PR，注意对应提交对应 dev 分支</li><li style=\"text-align: start;\">欢迎提交 [issue](https://github.com/yeeevip/yeee-memo/issues)，请写清楚遇到问题的原因、开发环境、复显步骤。</li></ol><h2 style=\"text-align: start;\">技术交流群</h2><ul><li style=\"text-align: start;\">QQ技术交流裙：96305921</li><li style=\"text-align: start;\">作者QQ：1324459373</li></ul><table style=\"width: auto; text-align: start;\"><tbody><tr><td colspan=\"1\" rowspan=\"1\" width=\"auto\"></td></tr></tbody></table><ul><li style=\"text-align: start;\"></li></ul><p><br></p>', '一页', 1, 0, 1, '2023-07-18 16:07:12', 1, 'https://gitee.com/yeeevip/yeee-chatgpt', 41, 0, '基于springboot+websocket+分词+uniapp开发的高性能可扩展的chatgpt小程序H5', 0, 'admin', '2022-11-25 09:08:07', 'admin', '2023-07-21 16:09:08');
INSERT INTO `t_blog_article` VALUES (23, 1, '良心分享：基于Java+SpringBoot+Netty+WebSocket+Uniapp轻松搭建ChatGpt程序', NULL, '<h1>一步一步教你搭建ChatGPT程序（微信小程序/H5网页）</h1><p>本文将详细介绍如何基于你自己的开源项目搭建一个ChatGPT程序，包括微信小程序和H5网页版。<br>该项目服务端主要使用了Java + Spring Boot + Netty + WebSocket等技术栈，聊天客户端使用的是UniApp来轻松搭建微信小程序和H5网页端。</p><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">1. 项目准备</span> </h2><p>在开始之前，请确保已经准备好以下环境和工具：</p><ul><li>IDE（推荐使用IntelliJ IDEA）</li><li>HBuilder X</li><li>微信小程序开发工具</li></ul><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">2. 架构设计</span> </h2><p>ChatGPT程序的架构设计如下：</p><ul><li>服务端使用Java和Spring Boot框架搭建，其中使用Netty框架实现WebSocket服务器。</li><li>客户端提供了微信小程序和H5两种平台，可以通过WebSocket与服务端进行通信。</li></ul><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">3. 服务端搭建</span> </h2><ul><li>Github完整代码DEMO</li></ul><pre><code class=\"language-hljs\">https://gitee.com/yeeevip/yeee-chatgpt\r\n        \r\nhttps://github.com/yeeevip/yeee-chatgpt</code></pre><h3>3.1 创建Spring Boot项目</h3><p>使用IDE创建一个新的Spring Boot项目，并添加相关依赖：</p><pre><code class=\"language-xml\">&lt;dependencies&gt;\r\n    ...\r\n    &lt;!-- 该依赖封装了Netty + websocket，并集成到springboot-starter中 --&gt;\r\n    &lt;dependency&gt;\r\n        &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\r\n        &lt;artifactId&gt;common-netty-websocket&lt;/artifactId&gt;\r\n    &lt;/dependency&gt;\r\n    &lt;!-- 引入此依赖为了使用openai的stream模式来快速获取内容 --&gt;\r\n    &lt;dependency&gt;\r\n        &lt;groupId&gt;com.squareup.okhttp3&lt;/groupId&gt;\r\n        &lt;artifactId&gt;okhttp-sse&lt;/artifactId&gt;\r\n    &lt;/dependency&gt;\r\n    &lt;!-- 以下两个依赖为服务鉴权依赖 --&gt;\r\n    &lt;dependency&gt;\r\n        &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\r\n        &lt;artifactId&gt;common-app-auth-server&lt;/artifactId&gt;\r\n    &lt;/dependency&gt;\r\n    &lt;dependency&gt;\r\n        &lt;groupId&gt;vip.yeee.memo&lt;/groupId&gt;\r\n        &lt;artifactId&gt;common-app-auth-client&lt;/artifactId&gt;\r\n    &lt;/dependency&gt;\r\n    ...\r\n&lt;/dependencies&gt;</code></pre><h3>3.2 编写WebSocket端点Endpoint</h3><p>添加WebSocket的支持后，我们需要编写具体的端点事件方法，如OnOpen、OnMessage等事件，用于实现消息的接收和发送逻辑。</p><pre><code class=\"language-java\">@Component\r\n@ServerEndpoint(path = \"/ws/airobot/{chatId}\", port = \"8802\", readerIdleTimeSeconds = \"15\")\r\npublic class ChatAppWebSocket {\r\n\r\n    @Autowired\r\n    private ApiChatGptBiz apiChatGptBiz;\r\n\r\n    // ws打开时触发\r\n    @OnOpen\r\n    public void onOpen(Session session, HttpHeaders headers, @PathParam(\"chatId\") String chatId) {\r\n        apiChatGptBiz.handleWsOnOpen(session, headers, chatId);\r\n    }\r\n\r\n    // 收到客户端ws消息时触发\r\n    @OnMessage\r\n    public void onMessage(Session session, String msg) {\r\n        apiChatGptBiz.handleWsOnMessage(session, msg);\r\n    }\r\n\r\n    // 客户端ws连接关闭时触发\r\n    @OnClose\r\n    public void onClose(Session session) throws IOException {\r\n        apiChatGptBiz.handleWsOnClose(session);\r\n    }\r\n\r\n    // 这里主要处理netty的一些事件，如读超时、写超时，可以方便实现心跳检测\r\n    @OnEvent\r\n    public void onEvent(Session session, Object evt) {\r\n        apiChatGptBiz.handleWsOnEvent(session, evt);\r\n    }\r\n\r\n}</code></pre><h3>3.3 集成ChatGPT模型</h3><p>根据你的ChatGPT模型实现，添加相关代码将模型集成到服务端中。你可以使用开源的ChatGPT模型，或自行训练一个模型。<br>具体实现将模型集成到服务端的步骤和代码，根据你使用的具体ChatGPT模型会有所不同，请参考相应的文档和示例。<br>这里主要调用的是openai的api接口，代码如下：</p><pre><code class=\"language-java\">@Component\r\npublic class OpenaiApiService {\r\n\r\n    @Autowired\r\n    private OkHttpClient okHttpClient;\r\n    @Autowired\r\n    private OkHttp3Kit okHttp3Kit;\r\n\r\n    // 使用okhttp的sse请求模式来调用会话接口，流式调用的话阻塞影响小性能比较好\r\n    public EventSource chatCompletions(Map&lt;String, String&gt; headers, ChatParams params, EventSourceListener eventSourceListener) {\r\n        try {\r\n            EventSource.Factory factory = EventSources.createFactory(okHttpClient);\r\n            ObjectMapper mapper = new ObjectMapper();\r\n            String requestBody = mapper.writeValueAsString(params);\r\n            Request request = new Request.Builder()\r\n                    .url(getApiHost() + \"/v1/chat/completions\")\r\n                    .post(RequestBody.create(MediaType.parse(ContentType.JSON.getValue()), requestBody))\r\n                    .headers(Headers.of(headers))\r\n                    .build();\r\n            return factory.newEventSource(request, eventSourceListener);\r\n        } catch (Exception e) {\r\n            throw new BizException(\"chatCompletions error\");\r\n        }\r\n    }\r\n}</code></pre><h3>3.4 实现业务逻辑</h3><p>根据你的需求，实现业务逻辑。此处的业务逻辑是处理用户输入的消息，在服务端调用ChatGPT模型生成回复，并将回复发送给客户端。</p><pre><code class=\"language-java\">@Service\r\npublic class ChatService {\r\n\r\n    ...\r\n\r\n    public void doWsChat(String msg, String chatId, String uid) {\r\n        WsEventSourceListener listener = new WsEventSourceListener(chatId, uid, msg);\r\n\r\n        String limitUserKey = StrUtil.isNotBlank(chatRedisRepository.getUserOpenIdCache(uid)) ? chatRedisRepository.getUserOpenIdCache(uid) : uid;\r\n\r\n        if (!this.checkLimit(uid, msg, limitUserKey, listener)) {\r\n            return;\r\n        }\r\n        \r\n        ...\r\n        \r\n        ChatParams params = new ChatParams();\r\n        List&lt;ChatMessage2&gt; messages = ChatLocalRepository.getChatContext(chatId, chatRedisRepository.getPreRecordCount());\r\n        ChatMessage2 chatMessage2 = this.buildUserMessage(msg);\r\n        messages.add(chatMessage2);\r\n        params.setMessages(messages);\r\n        params.setUser(authService.getUserId());\r\n        params.setStream(true);\r\n        listener.setStartTime(new Date());\r\n        EventSource eventSource = openaiApiService.chatCompletions(headers(), params, listener);\r\n        listener.setEventSource(eventSource);\r\n        ChatAppWsContext.setUserRecentESL(chatId, uid, listener);\r\n    }\r\n    \r\n    ...\r\n    \r\n}</code></pre><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">4. 客户端开发</span> </h2><h3>4.1 使用UniApp微信小程序/H5</h3><pre><code class=\"language-javascript\">    ...\r\n    // 与服务器建立连接\r\n    vm.ws = uni.connectSocket({\r\n        url: vm.baseWsAddr + \'/ws/airobot/\' + vm.chatId,\r\n        header: {\r\n            \'Utoken\': \'Bearer \' + t\r\n        },\r\n        complete: () =&gt; {\r\n        }\r\n    })\r\n    // 处理服务器返回的消息\r\n    vm.ws.onMessage(function (e) {\r\n        ...\r\n    })\r\n    vm.ws.onOpen(function (e) {\r\n        console.log(\'ws open\')\r\n        setInterval(function() {\r\n            if (vm.ws) {\r\n                vm.ws.send({\r\n                    data: \'ping\'\r\n                })\r\n            }\r\n        }, 5000);\r\n    })\r\n...</code></pre><h3>4.2 客户端效果预览</h3><ul><li>微信小程序 微信小程序</li><li>H5网页版 H5网页版</li></ul><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">5. 总结</span> </h2><p>本文详细介绍了如何基于Java + Spring Boot + Netty + WebSocket技术栈搭建一个ChatGPT程序，并使用Uniapp开发微信小程序和H5作为客户端。通过完成这个项目，你可以搭建一个功能强大的聊天机器人系统，满足用户的各种需求。希望这篇文章能够帮助你顺利完成ChatGPT程序的搭建与开发！</p><ul><li>Github完整代码DEMO</li></ul><pre><code >https://gitee.com/yeeevip/yeee-chatgpt\nhttps://github.com/yeeevip/yeee-chatgpt</code></pre><p><br></p>', '一页', 1, 0, 1, '2023-08-11 16:34:54', 0, NULL, 130, 1, '本文将详细介绍如何基于你自己的开源项目搭建一个ChatGPT程序，包括微信小程序和H5网页版。 该项目服务端主要使用了Java + Spring Boot + Netty + WebSocket等技术栈，聊天客户端使用的是UniApp来轻松搭建微信小程序和H5网页端。', 0, 'admin', '2023-08-11 16:34:57', 'admin', '2023-08-11 16:38:21');
INSERT INTO `t_blog_article` VALUES (24, 1, 'SpringBoot（一）：springboot应用程序启动过程核心分析', 'https://static001.geekbang.org/infoq/0c/0c422e63f61599cc7be9da745d211dfa.jpeg', '<h1>SpringBoot：springboot应用程序启动过程核心分析（一）</h1><p>说起<span style=\"color: black;\"><strong>springboot</strong></span>大家很容易想到的就是<span style=\"color: black;\"><strong>自动装配</strong></span>、<span style=\"color: black;\"><strong>约定大于配置</strong></span>这个特点，的确这是springboot相比较于普通的<span style=\"color: black;\"><strong>spring</strong></span> web项目最大的亮点。</p><p>从根本上来说，springboot的核心还是基于spring<span style=\"color: black;\"><strong>上下文ApplicationContext</strong></span>继承延伸自己的个性化能力，<br>以及依靠spring的开放<span style=\"color: black;\"><strong>扩展点</strong></span>（如ApplicationContextInitializer、BeanFactoryPostProcessor等）来实现自己的自动装配等功能，<br>从而我们可以轻松的构建spring web项目，让我们把更多的时间精力花费到实际业务开发上。</p><blockquote>具体spring的扩展点大概有13个，以下是我通过代码demo演示，需要了解的可以去Git自己获取，这里不再细说 </blockquote><pre><code class=\"language-javascript\">// Git代码\nhttps://gitee.com/yeeevip/yeee-memo/tree/master/learn-example/spring-boot-example/src/main/java/vip/yeee/memo/demo/springboot/extpoint\nhttps://github.com/yeeevip/yeee-memo/tree/master/learn-example/spring-boot-example/src/main/java/vip/yeee/memo/demo/springboot/extpoint</code></pre><p>接下来我们要开始肝本文干货内容了：通过springboot程序启动过程核心分析，了解<span style=\"color: black;\"><strong>怎么自动装配</strong></span>Bean？怎么<span style=\"color: black;\"><strong>自动启动</strong></span>的web服务器？</p><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">1 核心类</span> </h2><h3>1.1 SpringApplication</h3><p>我们平时一般从Java的main方法中使用SpringApplication去<span style=\"color: black;\"><strong>引导和启动</strong></span>Spring应用程序。</p><pre style=\"text-align: left;\"><code class=\"language-java\">@SpringBootApplication\npublic class SpringbootExampleApplication {\n\n    public static void main(String[] args) {\n        SpringApplication.run(SpringbootExampleApplication.class, args);\n    }\n}</code></pre><p>默认情况下，该类将执行以下步骤来引导你的应用程序：</p><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>1.</code></span> 创建适当的ApplicationContext上下文实例（取决于你的类路径下依赖的web容器类型）</p><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>2.</code></span> 初始化程序上下文，加载classpath下所有定义的<span style=\"color: black;\"><strong>Bean</strong></span>、注册一些内部的Bean(如用注解配置类后置处理器)等</p><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>3.</code></span> 刷新应用程序上下文，执行注解配置类后置处理器、启动web服务器(如tomcat，取决于具体依赖)、完成所有单例Bean的实例化、属性注入、初始化等</p><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>4.</code></span> 上下文刷新完成程序启动后，可以执行afterRefresh()逻辑以及触发任何XXXRunner bean，如CommandLineRunner、ApplicationRunner</p><blockquote>@SpringBootApplication.@EnableAutoConfiguration.@Import(AutoConfigurationImportSelector.class) <br><br>这个是springboot自身SPI机制可以按需导入starter配置Bean，其实现时通过spring.factories中指定自动配置的全限定配置类 </blockquote><p>以下是一些自定义starter的demo，有兴趣的同学可以看看怎么实现的：</p><pre><code class=\"language-javascript\">// Git代码\nhttps://gitee.com/yeeevip/yeee-memo/tree/master/memo-parent/memo-common\nhttps://github.com/yeeevip/yeee-memo/tree/master/memo-parent/memo-common</code></pre><h3>1.2 AnnotationConfigServletWebServerApplicationContext</h3><p>这个继承自<span style=\"color: black;\"><strong>ServletWebServerApplicationContext</strong></span>，拥有了创建/初始化/运行<span style=\"color: black;\"><strong>Web服务器</strong></span>的能力；同时其SuperClass本身也是实现了BeanDefinitionRegistry，<br>可以提前注册一些内置的PostProcessor用来辅助加载注解定义从而自动装配</p><blockquote>ServletWebServerApplicationContext <br><br>该类主要实现了通过ServletWebServerFactory创建、启动WebServer的逻辑，ServletWebServerFactory具体实例取决于你引入的是tomcat-starter还是其他的 看源码可以发现这个类重写了AbstractApplicationContext的onRefresh()方法进行了WebServer的启动，也就是说WebServer的启动时机在进行单例bean初始化之前</blockquote><h3>1.3 注册处理注解的XXXPostProcessor类</h3><p>为了达到自动装配的目标，springboot上下文ApplicationContext创建后，在初始化上下文时会<span style=\"color: black;\"><strong>注册</strong></span>多个用于<span style=\"color: black;\"><strong>注解</strong></span>处理的后置处理器，读取注解标记的Bean注册到spring容器</p><blockquote>ConfigurationClassPostProcessor <br><br>BeanFactory级别的后置处理器，继承至BeanFactoryPostProcessor，专门用于处理@Configuration标识的配置类， 具体实现由ConfigurationClassParser加载由@PropertySource、@ComponentScan、@Import、@Bean标识的方法、类将这些Bean注册到spring容器</blockquote><p><br></p><blockquote>AutowiredAnnotationBeanPostProcessor <br><br>继承至BeanPostProcessor，Bean级别的后置处理器，用于将@Autowired、@Inject、@Value标识的字段、方法进行属性注入</blockquote><p><br></p><blockquote>CommonAnnotationBeanPostProcessor <br><br>继承至BeanPostProcessor，处理非spring的注解，@Resource、@PostConstruct、@PreDestroy，用于属性注入、实例化后/销毁前执行回调方法等</blockquote><p><br></p><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">2. 总结</span> </h2><p>今天通过分析springboot的这几个核心类、注解可以发现：</p><p>首先，springboot有自己的独有注解，如@EnableAutoConfiguration、@Import来实现SPI机制，从而达到按需引入/自动配置、可扩展性的特点，<br>其次springboot的自身创建的应用上下文AnnotationConfigServletWebServerApplicationContext是在spring基础上下文的功能上扩展了自身的能力，如注解配置的扫描、WebServer的启动等。</p><p>由于篇幅的原因本次的分享就到这里了，接下来的文章我会继续深入的进行分析。</p>', '一页、yeee', 1, 0, 1, '2023-08-18 15:53:51', 0, NULL, 80, 6, 'SpringBoot：springboot应用程序启动过程核心分析', 0, 'admin', '2023-08-18 15:53:56', 'admin', '2023-08-23 11:47:04');
INSERT INTO `t_blog_article` VALUES (25, 1, 'SpringBoot（二）：springboot自动装配之SPI机制', 'https://static001.geekbang.org/infoq/0c/0c422e63f61599cc7be9da745d211dfa.jpeg', '<p><br></p><h1>SpringBoot（二）：springboot自动装配之SPI机制</h1><p>上篇文章我们介绍了springboot启动过程中涉及的核心类及其功能，我们知道springboot相较于spring的一大特性就是<span style=\"color: black;\"><strong>自动装配</strong></span>，那么自动装配是怎么具体实现的呢？<br>其实在实现自动装配上springboot采用了多种方案结合的，比如基于spring的扩展点的自动属性注入等，还有提供了一套SPI机制让程序自动可插拔的装配。<br>本文我带大家重点 了解一下<span style=\"color: black;\"><strong>SPI机制</strong></span>的实现原理。</p><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">1 什么是SPI？</span> </h2><p>SPI（Service Provider Interface）机制是一种服务发现和加载机制。它允许开发者编写一个服务接口，然后通过在项目中使用服务提供者实现该接口的方式，实现对应的服务功能。</p><h3>1.1 JDK中的SPI</h3><p>JDK的SPI机制通过在Classpath中的META-INF/services目录下，创建以服务接口全限定名命名的文件，<br>文件的内容为实现该接口的具体实现类。当应用程序需要使用该服务时，JDK会自动加载并实例化配置文件中列出的实现类，并提供给应用程序使用。</p><h3>1.2 Springboot中的SPI</h3><p>在Spring Boot中，SPI机制允许开发者通过定义接口和实现类的方式，实现对应的功能扩展。通过在<span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>META-INF/spring.factories</code></span>配置文件中列出实现类，<br>Spring Boot能够自动加载并使用这些扩展点，提供了灵活的定制和扩展能力。</p><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>Tip</code></span>：我本人在多年的开发经验中也积累了很多通用的<span style=\"color: black;\"><strong>starter</strong></span>，比如说通过引入我的starter修改配置文件就可以快速搭建一个web资源认证授权服务器/客户端，<br>当然这个也是在spring-security+oauth2上进一步的封装，需要了解的可以去Git自己获取</p><pre style=\"text-align: left;\"><code class=\"language-javascript\">// Git代码\nhttps://gitee.com/yeeevip/yeee-memo/tree/master/memo-parent/memo-common/common-auth/common-platform-auth-server\nhttps://github.com/yeeevip/yeee-memo/tree/master/memo-parent/memo-common/common-auth/common-platform-auth-server</code></pre><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">2 Springboot的SPI机制是怎么实现的？</span> </h2><h3>2.1 简短概括</h3><ol><li>程序启动，注册配置类处理器</li><li>spring刷新上下文，执行配置类处理器</li><li>扫描spring.factories将得到的BeanDefinition注册到容器</li><li>spring实例化/初始化这些BeanDefinition</li></ol><h3>2.2 源码跟踪</h3><ol><li>启动SpringBoot程序，创建应用上下文ApplicationContext</li></ol><blockquote>我们会调用SpringApplication.run启动程序，通常情况下我们会在程序的主启动类上加一个 @SpringBootApplication 注解，追踪这个注解会发现它是一个复杂的聚合注解， 其中内部包含了@Configuration、 @EnableAutoConfiguration ，而 @EnableAutoConfiguration 有集成了 @Import 注解，这个注解对于springboot非常重要！</blockquote><pre style=\"text-align: left;\"><code class=\"language-java\">// 用户定义的程序主启动类，启动程序\n@SpringBootApplication\npublic class SpringbootExampleApplication {\n    public static void main(String[] args) {\n        SpringApplication.run(SpringbootExampleApplication.class, args);\n    }\n}\n// Springboot的主启动类，创建spring上下文\npublic class SpringApplication {\n    public ConfigurableApplicationContext run(String... args) {\n        ConfigurableApplicationContext context = null;\n        try {\n            ...\n            context = createApplicationContext();\n            ...\n        } catch (Throwable ex) {\n            ...\n        }\n    }\n}</code></pre><p>2. 注册BeanFactory后置处理器用于处理配置类上的注解</p><blockquote>springboot启动创建应用上下文后，会注册一系列的内置的后置处理器，如ConfigurationClassPostProcessor、AutowiredAnnotationBeanPostProcessor、 CommonAnnotationBeanPostProcessor，其中 ConfigurationClassPostProcessor 实现了BeanFactoryPostProcessor是一个BeanFactory级别的处理器用于处理配置类</blockquote><p>注册PostProcessor代码如下：</p><pre style=\"text-align: left;\"><code class=\"language-java\">public class AnnotatedBeanDefinitionReader {\n    public AnnotatedBeanDefinitionReader(BeanDefinitionRegistry registry, Environment environment) {\n        ...\n        // 注册各种后置处理器\n        AnnotationConfigUtils.registerAnnotationConfigProcessors(this.registry);\n    } \n}\n// 注册各种后置处理器\npublic abstract class AnnotationConfigUtils {\n    public static Set&lt;BeanDefinitionHolder&gt; registerAnnotationConfigProcessors(BeanDefinitionRegistry registry, @Nullable Object source) {\n        ...\n        if (!registry.containsBeanDefinition(CONFIGURATION_ANNOTATION_PROCESSOR_BEAN_NAME)) {\n            // 注册&lt;配置类&gt;处理器\n            RootBeanDefinition def = new RootBeanDefinition(ConfigurationClassPostProcessor.class);\n            def.setSource(source);\n            beanDefs.add(registerPostProcessor(registry, def, CONFIGURATION_ANNOTATION_PROCESSOR_BEAN_NAME));\n        }\n        ...\n        return beanDefs;\n    }\n}</code></pre><p>3. 刷新应用上下文，执行注册的后置处理器</p><blockquote>springboot执行refreshContext刷新上下文，本质还是spring上下文的refresh方法，这个方法是spring生命周期的关键核心代码， spring生命周期的大部分扩展点都是在这里执行的。其中在执行容器中未实例化初始化的bean定义之前会执行内置的、用户自定义的所有注册的beanFactory后置处理器 ，这里会执行到ConfigurationClassPostProcessor这个配置类处理器</blockquote><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>Tip</code></span>：关于Spring的扩展点大概有13个，其中包括一些后置处理器，具体怎么使用需要了解的可以去Git自己获取，这里不再细说</p><pre style=\"text-align: left;\"><code class=\"language-javascript\">// Git代码\nhttps://gitee.com/yeeevip/yeee-memo/tree/master/learn-example/spring-boot-example/src/main/java/vip/yeee/memo/demo/springboot/extpoint\nhttps://github.com/yeeevip/yeee-memo/tree/master/learn-example/spring-boot-example/src/main/java/vip/yeee/memo/demo/springboot/extpoint</code></pre><p>刷新上下文代码如下：</p><pre style=\"text-align: left;\"><code class=\"language-java\">// Springboot调用refreshContext来执行父类的refresh方法\npublic class SpringApplication {\n    public ConfigurableApplicationContext run(String... args) {\n        ...\n        try {\n            ...\n            // 刷新上下文\n            refreshContext(context);\n            ...\n        } catch (Throwable ex) {\n            throw new IllegalStateException(ex);\n        }\n        ...\n        return context;\n    }\n}\n// 调用spring的AbstractApplicationContext的refresh()方法刷新\npublic abstract class AbstractApplicationContext extends DefaultResourceLoader implements ConfigurableApplicationContext {\n    public void refresh() throws BeansException, IllegalStateException {\n        ...\n        try {\n            ...\n            // 执行所有注册的BeanFactory后置处理器\n            invokeBeanFactoryPostProcessors(beanFactory);\n            ...\n            // 实例化、初始化所有的单例Bean\n            finishBeanFactoryInitialization(beanFactory);\n        } catch (BeansException ex) {\n            ...\n        }\n    }\n}</code></pre><p>4. 执行配置类后置处理器后置处理器（SPI核心逻辑）</p><blockquote>spring在执行到BeanFactory处理器的生命周期时会执行到ConfigurationClassPostProcessor这个处理器， 执行具体处理逻辑，如配置类上的@PropertySource、@ComponentScan、@Import、@ImportResource、@Bean等注解都会有相应的处理，目的就是将定义的BeanDefinition注册到BeanFactory容器中以便于最终的初始化。 由于用@SpringBootApplication这个注解标记的类即SpringbootExampleApplication.class本身也是个配置类， 这里的话就会处理这个主启动类。</blockquote><p>处理配置类的代码:</p><pre style=\"text-align: left;\"><code class=\"language-java\">public class ConfigurationClassPostProcessor implements BeanDefinitionRegistryPostProcessor {\n    public void processConfigBeanDefinitions(BeanDefinitionRegistry registry) {\n        // 这里会有我们程序的主启动配置类，也就是SpringbootExampleApplication.class\n        List&lt;BeanDefinitionHolder&gt; configCandidates = new ArrayList&lt;&gt;();\n        ...\n        // 转换每个配置类\n        ConfigurationClassParser parser = new ConfigurationClassParser();\n        ...\n        do {\n            ...\n            // 处理配置类\n            parser.parse(candidates);\n            ...\n        } while (!candidates.isEmpty());\n    }\n}\n// 调用parse方法后会执行到doProcessConfigurationClass\nclass ConfigurationClassParser {\n    protected final SourceClass doProcessConfigurationClass(ConfigurationClass configClass, SourceClass sourceClass, Predicate&lt;String&gt; filter) {\n        // 处理配置类的@PropertySource注解\n        ...\n        processPropertySource(propertySource);\n        ...\n        // 处理配置类的@ComponentScan注解\n        ...\n        Set&lt;BeanDefinitionHolder&gt; scannedBeanDefinitions = this.componentScanParser.parse(componentScan, sourceClass.getMetadata().getClassName());\n        ...\n        // 处理配置类的@Import注解，这里就是SPI机制核心实现逻辑了\n        processImports(configClass, sourceClass, getImports(sourceClass), filter, true);\n        // 处理配置类的@ImportResource注解\n        ...\n        String resolvedResource = this.environment.resolveRequiredPlaceholders(resource);\n        configClass.addImportedResource(resolvedResource, readerClass);\n        ...\n        // 处理配置类的@Bean注解\n        ...\n        Set&lt;MethodMetadata&gt; beanMethods = retrieveBeanMethodMetadata(sourceClass);\n        ...\n    }\n}</code></pre><blockquote>processImports这个方法会专门处理 @Import 这个注解， 进入方法发现会执行getImports方法获得@Import导入的类AutoConfigurationImportSelector.class，由于它实现了DeferredImportSelector，所以程序会执行 deferredImportSelectorHandler.handle去处理这个Selector；其实这里也还没有真正开始处理，最终的处理是在调用deferredImportSelectorHandler.process()发起的。</blockquote><p>看代码：</p><pre style=\"text-align: left;\"><code class=\"language-java\">class ConfigurationClassParser {\n    private void processImports(ConfigurationClass configClass, SourceClass currentSourceClass, Collection&lt;SourceClass&gt; importCandidates，...) {\n        ...\n        for (SourceClass candidate : importCandidates) {\n            if (candidate.isAssignable(ImportSelector.class)) {\n                ...\n                // 判断当前的导入的类是不是DeferredImportSelector的子类\n                if (selector instanceof DeferredImportSelector) {\n                    // 是DeferredImportSelector的子类的话由deferredImportSelectorHandler去处理\n                    this.deferredImportSelectorHandler.handle(configClass, (DeferredImportSelector) selector);\n                } \n                ...\n            }\n            ...\n        }\n    }\n    public void parse(Set&lt;BeanDefinitionHolder&gt; configCandidates) {\n        ...\n        // 这里发起真正处理Selector的逻辑\n        this.deferredImportSelectorHandler.process();\n    }\n}</code></pre><ul><li>处理AutoConfigurationImportSelector的具体实现步骤如下：</li></ul><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>4.1</code></span> 读取项目路径下所有依赖中的spring.factories文件，加载需要自动配置的类</p><blockquote>跟踪代码发现，执行process()后会执行handler.processGroupImports()，进而会执行grouping.getImports()，这个方法会用类加载器扫码程序classpath下所有jar中的spring.factories 文件，然后会得到所有用EnableAutoConfiguration属性标记的自动配置类</blockquote><pre style=\"text-align: left;\"><code class=\"language-java\">class ConfigurationClassParser {\n    public Iterable&lt;Group.Entry&gt; getImports() {\n        for (DeferredImportSelectorHolder deferredImport : this.deferredImports) {\n            // 会扫描jar下的spring.factories中的自动配置类\n            this.group.process(deferredImport.getConfigurationClass().getMetadata(),\n                    deferredImport.getImportSelector());\n        }\n        return this.group.selectImports();\n    }\n}\n// 具体扫描spring.factories的实现在AutoConfigurationImportSelector.process\npublic class AutoConfigurationImportSelector implements DeferredImportSelector，... {\n    @Override\n    public void process(AnnotationMetadata annotationMetadata, DeferredImportSelector deferredImportSelector) {\n        // getAutoConfigurationEntry这个方法执行\n        AutoConfigurationEntry autoConfigurationEntry = (deferredImportSelector).getAutoConfigurationEntry(annotationMetadata);\n        ...\n    }\n    protected AutoConfigurationEntry getAutoConfigurationEntry(AnnotationMetadata annotationMetadata) {\n        ...\n        // 这里会调用SpringFactoriesLoader.loadFactoryNames读取spring.factories文件\n        List&lt;String&gt; configurations = getCandidateConfigurations(annotationMetadata, attributes);\n        ...\n    }\n    protected List&lt;String&gt; getCandidateConfigurations(AnnotationMetadata metadata, AnnotationAttributes attributes) {\n        // 读取key为EnableAutoConfiguration.class的所有自动配置类\n        List&lt;String&gt; configurations = SpringFactoriesLoader.loadFactoryNames(getSpringFactoriesLoaderFactoryClass(),getBeanClassLoader());\n    }\n    protected Class&lt;?&gt; getSpringFactoriesLoaderFactoryClass() {\n        return EnableAutoConfiguration.class;\n    }\n}</code></pre><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>4.2</code></span> 针对所有扫描到的自动配置类<span style=\"color: black;\"><strong>再次</strong></span>执行配置类处理逻辑</p><blockquote>上面已经从spring.factories中扫描到了所有配置类，紧接着程序同样会执行配置类处理逻辑，具体处理逻辑同第4节开始，同样也是处理这个配置类中的各种注解/方法， 目的就是为了将这些BeanDefinition加入到spring容器中以便于最终初始化。</blockquote><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>4.3</code></span> 将所有通过配置类处理过符合条件的BeanDefinition注册到spring容器中</p><blockquote>执行完针对配置类的处理转换后，也就是执行完parse方法后，会再调用reader.loadBeanDefinitions用来把配置类处理后符合条件的BeanDefinition注册到spring容器</blockquote><p>看代码：</p><pre style=\"text-align: left;\"><code class=\"language-java\">public class ConfigurationClassPostProcessor implements BeanDefinitionRegistryPostProcessor {\n    public void processConfigBeanDefinitions(BeanDefinitionRegistry registry) {\n        ...\n        do {\n            ...\n            // 处理配置类\n            parser.parse(candidates);\n            ...\n            // parse转换处理完配置类后，然后会把所有处理过符合条件的注册到spring容器\n            this.reader.loadBeanDefinitions(configClasses);\n            ...\n        } while (!candidates.isEmpty());\n    }\n}</code></pre><p>5. 最后就是spring将所有单例BeanDefinition进行实例化、初始化了</p><blockquote>这里spring会把通过各种方式注册的单例BeanDefinition，如通过注解@Component、@Service标记的Bean，以及我们本文探讨的重点通过SPI机制的导入的Bean进行最终的实例化/初始化。 具体的处理过程也是spring的核心之一，有兴趣的小伙伴可以看一下源码，这里不详细介绍了。</blockquote><pre style=\"text-align: left;\"><code class=\"language-java\">public abstract class AbstractApplicationContext extends DefaultResourceLoader implements ConfigurableApplicationContext {\n    public void refresh() throws BeansException, IllegalStateException {\n        ...\n        try {\n            ...\n            // 执行所有注册的BeanFactory后置处理器\n            invokeBeanFactoryPostProcessors(beanFactory);\n            ...\n            // 实例化、初始化所有的单例Bean\n            finishBeanFactoryInitialization(beanFactory);\n        } catch (BeansException ex) {\n            ...\n        }\n    }\n}</code></pre><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">2. 总结</span> </h2><p>好啦，今天的内容就到这里了，通过以上代码分析，带大家了解了springboot的SPI机制实现的原理，<br>当然本文分析的可能还是比较片面，毕竟springboot在实现自动装配上还不止是SPI一个方案，它还涉及了很多复杂的处理。</p><p>文章中如果有问题疑问欢迎小伙伴们提问或者给我指点一下哦，大家一起探讨一下！</p><p>下面这个是我多年经验积累的一套脚手架， 里面集成了各种通用的自定义starter，同时也提供了互联网项目中各种中间件/框架的使用demo，<br>有兴趣的小伙伴可以git看看哦，并且欢迎大佬们指点！！！</p><pre style=\"text-align: left;\"><code class=\"language-javascript\">//&nbsp;Git代码\nhttps://gitee.com/yeeevip/yeee-memo\nhttps://github.com/yeeevip/yeee-memo</code></pre><p><br></p>', '一页、yeee', 1, 0, 1, '2023-08-23 11:47:50', 0, NULL, 101, 3, '我们知道springboot相较于spring的一大特性就是**自动装配**，那么自动装配是怎么具体实现的呢？ 其实在实现自动装配上springboot采用了多种方案结合的，比如基于spring的扩展点的自动属性注入等，还有提供了一套SPI机制让程序自动可插拔的装配。 本文我带大家重点 了解一下**SPI机制**的实现原理。', 0, 'admin', '2023-08-18 15:53:56', 'admin', '2023-08-23 11:55:24');
INSERT INTO `t_blog_article` VALUES (26, 8, 'Node/Npm处理笔记', '', '<h1>一、chromedriver依赖安装失败</h1><h4 style=\"text-align: left;\">1.问题描述</h4><p style=\"text-align: left;\">在使用npm下载chromedriver依赖时报错：</p><pre style=\"text-align: left;\"><code>chromedriver@2.27.2 install: `node install.js`</code></pre><h4 style=\"text-align: left;\">2.解决办法</h4><p style=\"text-align: left;\">第一步：根据报错信息中的地址，手动下载 <strong>chromedriver</strong> 依赖。</p><p style=\"text-align: left;\"><img src=\"https://img-blog.csdnimg.cn/251249f2ff05436da2b29a211a719f05.png\" alt=\"在这里插入图片描述\" data-href=\"\" style=\"height: auto;\">https://cdn.npmmirror.com/binaries/chromedriver/2.27/chromedriver_win32.zip<br>可以点击这个链接直接下载。</p><p style=\"text-align: left;\">第二步：首先将所有下载的依赖都删掉，即删掉项目中的 <strong>node_modules</strong> 文件夹。</p><p style=\"text-align: left;\">第三步：根据自己的下载地址，安装依赖。</p><pre style=\"text-align: left;\"><code class=\"language-prism language-java\">npm install chromedriver --chromedriver_filepath=文件地址</code></pre><p style=\"text-align: left;\">例如说我的 <strong>chromedriver_win32.zip</strong> 文件在 <strong>C盘的download目录下边</strong>，那就是输入如下命令：</p><pre style=\"text-align: left;\"><code class=\"language-prism language-java\">npm install chromedriver --chromedriver_filepath=C:\\download\\chromedriver_win32.zip</code></pre><pre style=\"text-align: left;\"><code>注意：不需要解压缩。</code></pre><p style=\"text-align: left;\">第四步：执行npm依赖</p><p style=\"text-align: left;\">等第三步中 <strong>chromedriver_win32.zip</strong> 依赖安装完成，再对项目执行 <strong>npm install</strong> ，安装其他依赖。</p><h4 style=\"text-align: left;\">3.题外话</h4><p style=\"text-align: left;\">网上给的办法都是先删除 node_moudles 文件夹，然后执行</p><pre style=\"text-align: left;\"><code class=\"language-prism language-java\">npm install chromedriver --chromedriver_cdnurl=http://cdn.npm.taobao.org/dist/chromedriver</code></pre><p style=\"text-align: left;\">也就是从淘宝下载镜像，但同样会有上边的报错。错误信息中有上边给的下载地址，多了淘宝镜像的下载地址：<br>http://cdn.npm.taobao.org/dist/chromedriver/2.27/chromedriver_win32.zip</p><p style=\"text-align: left;\"><br></p><h1 style=\"text-align: left;\">2、binding.node is not a valid Win32 application</h1><h4 style=\"text-align: left;\">1.问题描述</h4><pre style=\"text-align: left;\"><code>\\node_modules\\node-sass\\vendor\\win32-x64-57\\binding.node is not a valid Win32 application</code></pre><h4 style=\"text-align: left;\">2.解决办法</h4><p style=\"text-align: left;\">步骤一、执行如下命令，从新编译 node-sass 即可。</p><pre><code >npm rebuild node-sass</code></pre><p style=\"text-align: left;\">步骤二、</p><p style=\"text-align: left;\">问题原因：</p><blockquote style=\"text-align: left;\">由于node-sass\\vendor\\win32-x64-64\\binding.node文件的版本不对，导致出现报错。</blockquote><p style=\"text-align: left;\">具体步骤：</p><blockquote style=\"text-align: left;\">1.使用以下命令查看对应的版本</blockquote><blockquote style=\"text-align: left;\">node -p \"[process.platform, process.arch, process.versions.modules].join(\'-\')\"</blockquote><blockquote style=\"text-align: left;\">我的：</blockquote><blockquote style=\"text-align: left;\"> 2.去官网https://github.com/sass/node-sass/releases下载相应版本的 binding.node 文件。并放入到报错项目的 node-sass\\vendor文件夹下（注意下载的是.node文件，不要下载错）</blockquote><blockquote style=\"text-align: left;\">如：下载的 win32-x64-72_binding.node 文件（这是我的对应版本），则将该文件重命名为 binding.node 后放入到 node-sass\\vendor\\win32-x64-72目录下即可。</blockquote>', '一页', 1, 0, 1, '2023-07-01 23:11:40', 0, NULL, 36, 2, NULL, 0, 'admin', '2023-09-04 23:12:21', 'admin', '2024-03-03 14:20:39');
INSERT INTO `t_blog_article` VALUES (27, 1, 'SpringOauth2（一）：JwtTokenStore使用HMACSHA512算法令牌、与jjwt令牌互相可识别', 'https://pics1.baidu.com/feed/c8ea15ce36d3d5398353343f752c215c342ab013.jpeg', '<h3 style=\"text-align: start;\">SpringOauth2（一）：JwtTokenStore使用HMACSHA512算法令牌、与jjwt令牌互相可识别</h3><p style=\"text-indent: 2em; text-align: start;\">在我们使用SpringOauth2过程中，一般情况下会使用<span style=\"color: black;\"><strong>JwtTokenStore</strong></span>来颁发及校验令牌字符串，相比较于JdbcTokenStore这种令牌存储形式来说性能要高很多。</p><ul><li style=\"text-align: start;\">本文重点内容</li></ul><blockquote style=\"text-align: start;\">1、spring提供的JwtTokenStore的加密算法默认为HMACSHA256，为了更安全我们如何定制实现HMACSHA512算法？<br><br>2、在网关鉴权使用的是io.jsonwebtoken.jjwt，使用JwtTokenStore生成的令牌如何与jjwt互通？</blockquote><ul><li style=\"text-align: start;\">我这里不具体介绍怎么使用SpringOauth2了，以下是本人多年经验封装的可用于实战的Spring+security+Oauth2授权/认证服务器的Starter，代码自取哦</li></ul><pre style=\"text-align: start;\"><code class=\"language-javascript\">// 认证授权服务器\nhttps://gitee.com/yeeevip/yeee-memo/tree/master/memo-parent/memo-common/common-auth/common-platform-auth-server\nhttps://github.com/yeeevip/yeee-memo/tree/master/memo-parent/memo-common/common-auth/common-platform-auth-server\n// 认证授权客户端\nhttps://gitee.com/yeeevip/yeee-memo/tree/master/memo-parent/memo-common/common-auth/common-platform-auth-client\nhttps://github.com/yeeevip/yeee-memo/tree/master/memo-parent/memo-common/common-auth/common-platform-auth-client\n// 只需在项目pom中引入starter依赖配置文件加一下就可以直接用了，使用案例\nhttps://gitee.com/yeeevip/yeee-memo/tree/master/spring-cloud/auth-sso\nhttps://github.com/yeeevip/yeee-memo/tree/master/spring-cloud/auth-sso</code></pre><h3 style=\"text-align: start;\"><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">1 JwtTokenStore使用HMACSHA512算法</span></h3><h3 style=\"text-align: start;\">看代码</h3><pre style=\"text-align: start;\"><code class=\"language-java\">@Configuration\npublic class JwtTokenStoreConfig {\n\n    private final static String SIGN_ALGORITHM = \"HMACSHA512\";\n\n    @Bean\n    public AccessTokenConverter accessTokenConverter() {\n        JwtAccessTokenConverter jwtAccessTokenConverter = new JwtAccessTokenConverter();\n        //配置JWT使用的秘钥\n        jwtAccessTokenConverter.setSigningKey(authProperties.getJwtSecret());\n        // 重点！！！\n        jwtAccessTokenConverter.setSigner(new MacSigner(SIGN_ALGORITHM\n                , new SecretKeySpec(DatatypeConverter.parseBase64Binary(authProperties.getJwtSecret()), SIGN_ALGORITHM)));\n        jwtAccessTokenConverter.setVerifier(new MacSigner(SIGN_ALGORITHM\n                , new SecretKeySpec(DatatypeConverter.parseBase64Binary(authProperties.getJwtSecret()), SIGN_ALGORITHM)));\n        ...\n    }\n}</code></pre><h3 style=\"text-align: start;\">常见问题</h3><ul><li style=\"text-align: start;\">1 提示 invalid_token - Cannot convert access token to JSON</li></ul><p style=\"text-indent: 2em; text-align: start;\">这个问题大概意思是说无法识别颁发的token，检查有没有setVerifier，参考上面代码看有没有加.setVerifier(new MacSigner)</p><ul><li style=\"text-align: start;\">完整代码</li></ul><pre style=\"text-align: start;\"><code class=\"language-javascript\">https://gitee.com/yeeevip/yeee-memo/blob/master/memo-parent/memo-base/base-security-oauth2/src/main/java/vip/yeee/memo/base/websecurityoauth2/configure/JwtTokenStoreConfig.java\nhttps://github.com/yeeevip/yeee-memo/blob/master/memo-parent/memo-base/base-security-oauth2/src/main/java/vip/yeee/memo/base/websecurityoauth2/configure/JwtTokenStoreConfig.java\n</code></pre><h3 style=\"text-align: start;\"><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">2 JwtTokenStore的令牌与jjwt互相识别</span></h3><blockquote style=\"text-align: start;\">2.1 两者互相识别的前提肯定得保证双方加密算法一致，由于JwtTokenStore默认使用的是HMACSHA256，需要定制修改为jjwt默认的HMACSHA512算法，代码参考上面<br><br>2.2 研究jjwt源码发现加密密钥经过DatatypeConverter.parseBase64Binary这个方法的处理，所以JwtTokenStore的密钥同样需要这样处理，代码参考上面</blockquote><p><br></p>', '一页、yeee', 1, 0, 1, '2023-09-14 17:12:50', 0, NULL, 216, 44, '1、spring提供的JwtTokenStore的加密算法默认为HMACSHA256，为了更安全我们如何定制实现HMACSHA512算法？  2、在网关鉴权使用的是io.jsonwebtoken.jjwt，使用JwtTokenStore生成的令牌如何与jjwt互通？', 0, 'admin', '2023-09-14 17:12:53', 'admin', '2023-09-14 17:14:36');
INSERT INTO `t_blog_article` VALUES (28, 6, 'RocketMQ源码（一）RocketMQ消息生产及消费通信链路源码分析', NULL, '<h1>RocketMQ源码（一）RocketMQ消息生产及消费通信链路源码分析</h1><p><span style=\"color: black;\"><strong>RocketMQ</strong></span>的核心架构主要分为Broker、Producer、Consumer，通过阅读源码看到他们之间是通过Netty来通信的<br>，具体来说Broker端是<span style=\"color: black;\"><strong>Netty服务器</strong></span>用来负责与客户端的连接请求处理，而Producer/Consumer端是<span style=\"color: black;\"><strong>Netty客户端</strong></span>用来负责与Netty服务器的通信及请求响应处理。</p><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>Tip</code></span>：我本人在多年的开发经验中常用的MQ中间件如Kafka、RocketMQ都实战使用的，简单的使用示例可以参考我Git。</p><pre style=\"text-align: left;\"><code class=\"language-hljs\">//&nbsp;Git代码\nhttps://gitee.com/yeeevip/yeee-memo/tree/master/middle-ware/mq\nhttps://github.com/yeeevip/yeee-memo/tree/master/middle-ware/mq</code></pre><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">1 Netty客户端/服务端运行</span> </h2><p><img src=\"./images/20231020-01.png\" alt=\"Netty客户端/服务端运行\" data-href=\"\" style=\"\"/></p><p>Netty客户端/服务端运行</p><h3>1.1 Broker端Netty服务器</h3><ul><li>BrokerController引导启动Netty服务器</li></ul><blockquote>创建NettyRemotingServer对象并调用start()方法来启动Netty服务器</blockquote><pre style=\"text-align: left;\"><code class=\"language-java\">public class BrokerController {\n    protected void initializeRemotingServer() {\n        this.remotingServer = new NettyRemotingServer(this.nettyServerConfig, this.clientHousekeepingService);\n        ...\n    }\n    protected void startBasicService() throws Exception {\n        ...\n        if (this.remotingServer != null) {\n            this.remotingServer.start();\n        }\n        ...\n    }\n}</code></pre><ul><li>Netty服务端启动</li></ul><blockquote>这里就是我们熟悉的Netty的ServerBootstrap服务端引导类，通过设置EventLoopGroup然后绑定端口接着添加一系列的ChannelHandler启动服务器； 对于RocketMQ来说主要的Handler是NettyServerHandler这个处理类，它主要负责接收客户端请求并进行处理。</blockquote><pre style=\"text-align: left;\"><code class=\"language-java\">public class NettyRemotingServer extends NettyRemotingAbstract implements RemotingServer {\n    // sharable handlers\n    private NettyServerHandler serverHandler;\n    \n    @Override\n    public void start() {\n        ...\n        // 用于处理客户端请求命令\n        serverHandler = new NettyServerHandler();\n        ...\n        serverBootstrap.group(this.eventLoopGroupBoss, this.eventLoopGroupSelector)\n                ...\n                .childHandler(new ChannelInitializer&lt;SocketChannel&gt;() {\n                    @Override\n                    public void initChannel(SocketChannel ch) {\n                        ch.pipeline()\n                                ...\n                                .addLast(defaultEventExecutorGroup, ..., serverHandler);\n                    }\n                });\n        try {\n            ChannelFuture sync = serverBootstrap.bind().sync();\n            ...\n        } catch (Exception e) {\n            ...\n        }\n        ...\n    }\n}</code></pre><h3>1.2 Producer/Consumer端Netty客户端</h3><blockquote>Producer和Consumer的启动最终都会调用mQClientFactory.start()来创建Netty客户端</blockquote><pre style=\"text-align: left;\"><code class=\"language-java\">// Producer\npublic class DefaultMQProducerImpl implements MQProducerInner {\n    \n    private MQClientInstance mQClientFactory;\n    \n    public void start(final boolean startFactory) throws MQClientException {\n        switch (this.serviceState) {\n            case CREATE_JUST:\n                this.mQClientFactory = MQClientManager.getInstance().getOrCreateMQClientInstance(this.defaultMQProducer, rpcHook);\n                ...\n                // 这里创建Netty客户端\n                mQClientFactory.start();\n                ...\n            case RUNNING:\n            ...\n            default:\n                break;\n        }\n        ...\n    }\n}\n// Consumer\npublic class DefaultMQPushConsumerImpl implements MQConsumerInner {\n\n    private MQClientInstance mQClientFactory;\n\n    public synchronized void start() throws MQClientException {\n        switch (this.serviceState) {\n            case CREATE_JUST:\n                ...\n                this.mQClientFactory = MQClientManager.getInstance().getOrCreateMQClientInstance(this.defaultMQPushConsumer, this.rpcHook);\n                ...\n                // 这里创建Netty客户端\n                mQClientFactory.start();\n                ...\n            case RUNNING:\n            ...\n            default:\n                break;\n        }\n        ...\n    }\n}</code></pre><ul><li>创建Netty客户端对象</li></ul><blockquote>执行mQClientFactory.start() --&gt; this.mQClientAPIImpl.start() --&gt; this.remotingClient.start()，最终NettyRemotingClient对象调用start()方法来创建Netty客户端； Netty客户端由Bootstrap引导程序创建，之后请求/响应通过Netty客户端处理。</blockquote><pre style=\"text-align: left;\"><code class=\"language-java\">public class NettyRemotingClient extends NettyRemotingAbstract implements RemotingClient {\n    @Override\n    public void start() {\n        this.bootstrap.group(this.eventLoopGroupWorker).channel(NioSocketChannel.class)\n                ...\n                .handler(new ChannelInitializer&lt;SocketChannel&gt;() {\n                    @Override\n                    public void initChannel(SocketChannel ch) throws Exception {\n                        ...\n                        ch.pipeline().addLast(..., new NettyClientHandler());\n                    }\n                });\n        ...\n    }\n}</code></pre><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">2 消息的生产及保存</span> </h2><p><img src=\"./images/20231020-02.png\" alt=\"消息的生产及保存\" data-href=\"\" style=\"\"/></p><p>消息的生产及保存</p><h3>2.1 Producer生产消息到Broker</h3><blockquote>我们调用producer.send发送消息时，程序会使用RemotingCommand.createRequestCommand(RequestCode.SEND_MESSAGE)把消息封装为自定义的通信协议RemotingCommand， 之后NettyRemotingClient会找到Broker地址并建立连接生成Channel对象调用writeAndFlush方法将请求（RemotingCommand）发送到Netty服务器</blockquote><ul><li>使用producer.send发送同步消息</li></ul><pre style=\"text-align: left;\"><code class=\"language-java\">public class Producer {\n    public static void main(String[] args) throws MQClientException, InterruptedException {\n        DefaultMQProducer producer = new DefaultMQProducer(PRODUCER_GROUP);\n        producer.start();\n        Message msg = new Message(TOPIC /* Topic */,\n                TAG /* Tag */,\n                (\"Hello RocketMQ \").getBytes(RemotingHelper.DEFAULT_CHARSET) /* Message body */\n        );\n        SendResult sendResult = producer.send(msg);\n    }\n}</code></pre><ul><li>封装为RemotingCommand消息协议进一步执行发送逻辑</li></ul><pre style=\"text-align: left;\"><code class=\"language-java\">public class MQClientAPIImpl implements NameServerUpdateCallback {\n    public SendResult sendMessage(final Message msg, final SendMessageRequestHeader requestHeader, ...) {\n        // 构建请求命令 RequestCode.SEND_MESSAGE\n        RemotingCommand request = RemotingCommand.createRequestCommand(RequestCode.SEND_MESSAGE, requestHeader);\n        request.setBody(msg.getBody());\n        switch (communicationMode) {\n            ...\n            case SYNC:\n                return this.sendMessageSync(addr, brokerName, msg, timeoutMillis - costTimeSync, request);\n            ...\n        }\n        return null;\n    }\n}</code></pre><ul><li>调用与服务端建立的Channel的writeAndFlush方法将请求RemotingCommand发送到Broker</li></ul><pre style=\"text-align: left;\"><code class=\"language-java\">public abstract class NettyRemotingAbstract {\n    public RemotingCommand invokeSyncImpl(Channel channel, RemotingCommand request) {\n        ...\n        try {\n            ...\n            // 向服务端Broker通道发送消息\n            channel.writeAndFlush(request).addListener((ChannelFutureListener) f -&gt; {\n                ...\n            });\n            RemotingCommand responseCommand = responseFuture.waitResponse(timeoutMillis);\n            ...\n            return responseCommand;\n        } \n        ...\n    }\n}</code></pre><h3>2.2 Broker接收消息并保存</h3><blockquote>在开始介绍说Broker中NettyServer的启动时会添加NettyServerHandler一个处理器，这个handler负责处理client发过来的请求指令。</blockquote><blockquote>上面当客户端Producer发送RemotingCommand(RequestCode.SEND_MESSAGE)这个指令的请求时，Broker收到请求后通过RequestCode 找到对应的SendMessageProcessor处理器执行processRequest方法去处理消息接收后的逻辑。</blockquote><ul><li>SendMessageProcessor处理器来接收消息调用MessageStore保存消息</li></ul><pre style=\"text-align: left;\"><code class=\"language-java\">public class SendMessageProcessor extends AbstractSendMessageProcessor implements NettyRequestProcessor {\n    \n    @Override\n    public RemotingCommand processRequest(ChannelHandlerContext ctx, RemotingCommand request) throws RemotingCommandException {\n        ...\n        response = this.sendMessage(ctx, request, sendMessageContext, requestHeader, mappingContext,\n                (ctx12, response12) -&gt; executeSendMessageHookAfter(response12, ctx12));\n        ...\n    }\n\n    public RemotingCommand sendMessage(...， final RemotingCommand request, ...) throws RemotingCommandException {\n        ...\n        MessageExtBrokerInner msgInner = new MessageExtBrokerInner();\n        ...\n        putMessageResult = this.brokerController.getMessageStore().putMessage(msgInner);\n        ...\n    }\n}</code></pre><ul><li>MessageStore保存消息到CommitLog中</li></ul><pre style=\"text-align: left;\"><code class=\"language-java\">public class DefaultMessageStore implements MessageStore {\n    \n    @Override\n    public PutMessageResult putMessages(MessageExtBatch messageExtBatch) {\n        return waitForPutResult(asyncPutMessages(messageExtBatch));\n    }\n\n    @Override\n    public CompletableFuture&lt;PutMessageResult&gt; asyncPutMessages(MessageExtBatch messageExtBatch) {\n        ...\n        CompletableFuture&lt;PutMessageResult&gt; putResultFuture = this.commitLog.asyncPutMessages(messageExtBatch);\n        ...\n    }\n}\npublic class CommitLog implements Swappable {\n    public CompletableFuture&lt;PutMessageResult&gt; asyncPutMessages(final MessageExtBatch messageExtBatch) {\n        ...\n        result = mappedFile.appendMessages(messageExtBatch, this.appendMessageCallback, putMessageContext);\n        ...\n    }\n}</code></pre><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">3 消息的拉取及消费</span> </h2><p><img src=\"./images/20231020-03.png\" alt=\"消息的拉取及消费\" data-href=\"\" style=\"\"/></p><p>消息的拉取及消费</p><h3>3.1 Consumer向Broker发送拉取请求</h3><blockquote>创建Consumer实例，订阅Topic并注册MessageListener后调用start方法启动程序； 接着开启一个PullMessageService任务去向Broker发送消息拉取请求，通过DefaultMQPushConsumerImpl.pullMessage方法设置请求回调逻辑(如：获取到消息则使用MessageListener去消费)， 接着继续执行MQClientAPIImpl().pullMessage将请求信息封装为RemotingCommand.createRequestCommand(RequestCode.PULL_MESSAGE)，最终由NettyRemotingClient发送请求到Broker。</blockquote><ul><li>创建DefaultMQPushConsumer调用start()启动消费者程序，PullMessageService任务开启</li></ul><pre style=\"text-align: left;\"><code class=\"language-java\">public class Consumer {\n    \n    public static void main(String[] args) throws MQClientException {\n        DefaultMQPushConsumer consumer = new DefaultMQPushConsumer(CONSUMER_GROUP);\n        consumer.subscribe(TOPIC, \"*\");\n        consumer.registerMessageListener((MessageListenerConcurrently) (msg, context) -&gt; {\n            System.out.printf(\"%s Receive New Messages: %s %n\", Thread.currentThread().getName(), msg);\n            return ConsumeConcurrentlyStatus.CONSUME_SUCCESS;\n        });\n        consumer.start();\n    }\n}\n\npublic class MQClientInstance {\n\n    public void start() throws MQClientException {\n        ...\n        // Start pull service\n        this.pullMessageService.start();\n        ...\n    }\n}</code></pre><ul><li>这里会设置回调逻辑等并继续调用底层实现发起请求，开始注册的MessageListener会在这里调用的</li></ul><pre style=\"text-align: left;\"><code class=\"language-java\">public class DefaultMQPushConsumerImpl implements MQConsumerInner {\n    \n    public void pullMessage(final PullRequest pullRequest) {\n        ...\n        PullCallback pullCallback = new PullCallback() {\n            @Override\n            public void onSuccess(PullResult pullResult) {\n                if (pullResult != null) {\n                    switch (pullResult.getPullStatus()) {\n                        // 获取到消息\n                        case FOUND:\n                            ...\n                            // 这个里面会执行注册的MessageListener\n                            DefaultMQPushConsumerImpl.this.consumeMessageService.submitConsumeRequest(pullResult.getMsgFoundList(), ...);\n                            ...\n                            // 继续拉取消息\n                            DefaultMQPushConsumerImpl.this.executePullRequestImmediately(pullRequest);\n                            ...\n                        ...\n                    }\n                }\n            }\n            ...\n        };\n        ...\n        try {\n            this.pullAPIWrapper.pullKernelImpl(pullRequest.getMessageQueue(), ..., pullRequest.getNextOffset(), ..., pullCallback);\n        } catch (Exception e) {\n            ...\n        }\n    }\n}</code></pre><blockquote>上面执行到pullAPIWrapper.pullKernelImpl会调用MQClientAPIImpl().pullMessage来封装请求报文最终交由NettyRemotingClient.invokeSyncImpl真正发出请求。</blockquote><ul><li>封装请求报文RemotingCommand.createRequestCommand(RequestCode.PULL_MESSAGE)</li></ul><pre style=\"text-align: left;\"><code class=\"language-java\">public class MQClientAPIImpl implements NameServerUpdateCallback {\n    public PullResult pullMessage(final String addr, final PullMessageRequestHeader requestHeader, ..., final PullCallback pullCallback) {\n        ...\n        RemotingCommand request = RemotingCommand.createRequestCommand(RequestCode.PULL_MESSAGE, requestHeader);\n        ...\n        RemotingCommand response = this.remotingClient.invokeSync(addr, request, timeoutMillis);\n        ...\n    }\n}</code></pre><ul><li>RemotingClient调用channel.writeAndFlush(request)发出拉取请求</li></ul><pre style=\"text-align: left;\"><code class=\"language-java\">public abstract class NettyRemotingAbstract {\n    public RemotingCommand invokeSyncImpl(final Channel channel, final RemotingCommand request, final long timeoutMillis) {\n        ...\n        try {\n            ...\n            channel.writeAndFlush(request).addListener((ChannelFutureListener) f -&gt; {\n                ...\n            });\n            ...\n        } \n        ...\n    }\n}</code></pre><h3>3.2 Broker接收拉取请求匹配返回消息</h3><blockquote>同样Broker中NettyServerHandler收到RemotingCommand(RequestCode.PULL_MESSAGE)这个指令找到PullMessageProcessor调用processRequest方法去处理。</blockquote><ul><li>PullMessageProcessor.processRequest处理时，调用messageStore.getMessageAsync去队列里查找消息，之后写回客户端</li></ul><pre style=\"text-align: left;\"><code class=\"language-java\">public class PullMessageProcessor implements NettyRequestProcessor {\n    private RemotingCommand processRequest(final Channel channel, RemotingCommand request, ...) {\n        ...\n        messageStore.getMessageAsync(group, topic, queueId, requestHeader.getQueueOffset(), requestHeader.getMaxMsgNums(), messageFilter)\n                .thenApply(result -&gt; {\n                    ...\n                })\n                // 写回客户端\n                .thenAccept(result -&gt; NettyRemotingAbstract.writeResponse(channel, request, result));\n        ...\n    }\n}</code></pre><ul><li>PullMessageProcessor.processRequest处理时，调用messageStore.getMessageAsync去队列里查找消息，之后写回客户端</li></ul><pre style=\"text-align: left;\"><code class=\"language-java\">public class DefaultMessageStore implements MessageStore {\n    @Override\n    public GetMessageResult getMessage(final String group, final String topic, final int queueId, final long offset, ...) {\n        ...\n        GetMessageResult getResult = new GetMessageResult();\n        ...\n        SelectMappedBufferResult selectResult = this.commitLog.getMessage(offsetPy, sizePy);\n        ...\n        getResult.addMessage(selectResult, cqUnit.getQueueOffset(), cqUnit.getBatchNum());\n        ...\n        return getResult;\n    }\n}</code></pre><ul><li>从commitLog中获取消息</li></ul><pre style=\"text-align: left;\"><code class=\"language-java\">public class CommitLog implements Swappable {\n    public SelectMappedBufferResult getMessage(final long offset, final int size) {\n        int mappedFileSize = this.defaultMessageStore.getMessageStoreConfig().getMappedFileSizeCommitLog();\n        MappedFile mappedFile = this.mappedFileQueue.findMappedFileByOffset(offset, offset == 0);\n        if (mappedFile != null) {\n            int pos = (int) (offset % mappedFileSize);\n            SelectMappedBufferResult selectMappedBufferResult = mappedFile.selectMappedBuffer(pos, size);\n            if (null != selectMappedBufferResult) {\n                selectMappedBufferResult.setInCache(coldDataCheckService.isDataInPageCache(offset));\n                return selectMappedBufferResult;\n            }\n        }\n        return null;\n    }\n}</code></pre><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">最后</span> </h2><p>至此我们把RocketMQ中Broker与生产者/消费者基于Netty简单的通信调用链路讲完了，大家有什么问题可以下面留言哦，一起学习进步啊。</p><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>Tip</code></span>：我本人在多年的开发经验中常用的MQ中间件如Kafka、RocketMQ都实战使用的，简单的使用示例可以参考我Git。</p><pre style=\"text-align: left;\"><code class=\"language-hljs\">//&nbsp;Git代码\nhttps://gitee.com/yeeevip/yeee-memo/tree/master/middle-ware/mq\nhttps://github.com/yeeevip/yeee-memo/tree/master/middle-ware/mq</code></pre><p><br></p>', '一页', 1, 0, 1, '2023-10-21 07:45:45', 0, NULL, 75, 0, NULL, 0, 'admin', '2023-10-21 07:45:49', 'admin', '2023-10-21 07:53:33');
INSERT INTO `t_blog_article` VALUES (29, 6, 'RocketMQ源码（二）消息消费的模式到底是Push还是Pull？', NULL, '<h1>RocketMQ源码（二）消息消费的模式到底是Push还是Pull？</h1><p><span style=\"color: black;\"><strong>RocketMQ</strong></span>为开发者提供了两种消息的消费模式，分别是<span style=\"color: black;\"><strong>Pull</strong></span>和<span style=\"color: black;\"><strong>Push</strong></span>，对应的实现是DefaultMQPullConsumer和DefaultMQPushConsumer；<br>接下来我将带大家通过以下几个方面了解这两种模式：</p><ul><li>Pull和Push的使用示例</li><li>跟踪源码分析两种模式的实现原理</li><li>RocketMQ到底是Push还是Pull呢？</li></ul><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>Tip</code></span>：我本人在多年的开发经验中常用的MQ中间件如Kafka、RocketMQ都实战使用的，简单的使用示例可以参考我Git。</p><pre style=\"text-align: left;\"><code class=\"language-hljs\">https://gitee.com/yeeevip/yeee-memo/tree/master/middle-ware/mq\nhttps://github.com/yeeevip/yeee-memo/tree/master/middle-ware/mq</code></pre><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">1 Pull模式</span> </h2><blockquote>这种模式很容易理解，就是消费者主动请求Broker去拉取一批消息，然后消费； 这种模式的好处是可以根据客户端消费能力来主动获取消息量；但是弊端也比较明显，就是获取消息的时机不太好把握 ，获取时间间隔小容易造成CPU浪费，时间间隔太大又会造成消费不及时。</blockquote><h3>1.1 使用示例</h3><p>使用提供的DefaultMQPullConsumer这个实现，调用fetchMessageQueuesInBalance拿到该Topic下的Queue，然后调用pull()方法从Queue中指定offset获取消息</p><pre style=\"text-align: left;\"><code class=\"language-java\">public class PullConsumer {\n    public static void main(String[] args) throws MQClientException {\n        // 创建Pull模式消费实例\n        DefaultMQPullConsumer consumer = new DefaultMQPullConsumer(\"test_consumer_group\");\n        consumer.setNamesrvAddr(\"127.0.0.1:9876\");\n        consumer.start();\n        // 获取该Topic下的所有Queue\n        Set&lt;MessageQueue&gt; messageQueues = consumer.fetchMessageQueuesInBalance(\"TopicTest\");\n        PullResult pullResult = null;\n        // 从Queue中获取消息\n        for (MessageQueue messageQueue : messageQueues) {\n            long offset = this.consumeFromOffset(messageQueue);\n            pullResult = consumer.pull(messageQueue, \"*\", offset, 32);\n            switch (pullResult.getPullStatus()) {\n                case FOUND:\n                    List&lt;MessageExt&gt; msgs = pullResult.getMsgFoundList();\n                    // 执行自定义的消费逻辑\n                    this.doSomething(msgs);\n                    //update offset to broker\n                    consumer.updateConsumeOffset(messageQueue, pullResult.getNextBeginOffset());\n                    break;\n                case OFFSET_ILLEGAL:\n                    consumer.updateConsumeOffset(messageQueue, pullResult.getNextBeginOffset());\n                    break;\n                case NO_NEW_MSG:\n                    Thread.sleep(1);\n                    consumer.updateConsumeOffset(messageQueue, pullResult.getNextBeginOffset());\n                    break;\n                case NO_MATCHED_MSG:\n                    consumer.updateConsumeOffset(messageQueue, pullResult.getNextBeginOffset());\n                    break;\n                default:\n            }\n        }\n    }\n}</code></pre><h3>1.2 拉取源码分析</h3><ul><li>注意一下DefaultMQPullConsumer.pull()方法；</li><li>这个方法会执行MQClientAPIImpl().pullMessage把请求封装为RequestCode.PULL_MESSAGE的RemotingCommand命令；</li><li>然后由NettyRemotingClient发送RemotingCommand命令到Broker；</li><li>最后就是Broker收到拉取请求根据请求信息把匹配的消息响应到客户端。</li></ul><h4>1.2.1 核心代码</h4><pre style=\"text-align: left;\"><code class=\"language-java\">/*\n   封装请求报文RemotingCommand.createRequestCommand(RequestCode.**PULL_MESSAGE**)\n */\npublic class MQClientAPIImpl implements NameServerUpdateCallback {\n    public PullResult pullMessage(final String addr, final PullMessageRequestHeader requestHeader, ..., final PullCallback pullCallback) {\n        ...\n        RemotingCommand request = RemotingCommand.createRequestCommand(RequestCode.PULL_MESSAGE, requestHeader);\n        ...\n        RemotingCommand response = this.remotingClient.invokeSync(addr, request, timeoutMillis);\n        ...\n    }\n}\n/*\n   RemotingClient调用channel.writeAndFlush(request)发出拉取请求\n */\npublic abstract class NettyRemotingAbstract {\n    public RemotingCommand invokeSyncImpl(final Channel channel, final RemotingCommand request, final long timeoutMillis) {\n        ...\n        try {\n            ...\n            channel.writeAndFlush(request).addListener((ChannelFutureListener) f -&gt; {\n                ...\n            });\n            ...\n        } \n        ...\n    }\n}</code></pre><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">2 Push模式</span> </h2><blockquote>这个模式解决了Pull模式请求时间间隔的痛点，从直观上看来就是Broker主动推送消息，这样消息消费也比较及时。</blockquote><h3>2.1 使用示例</h3><p>用api提供的DefaultMQPushConsumer这个实现，首先订阅Topic及注册监听方法，然后调用start方法就可以接收消息了。</p><pre style=\"text-align: left;\"><code class=\"language-java\">public class Consumer {\n    \n    public static void main(String[] args) throws MQClientException {\n        // 创建Push模式消费实例\n        DefaultMQPushConsumer consumer = new DefaultMQPushConsumer(CONSUMER_GROUP);\n        consumer.subscribe(TOPIC, \"*\");\n        // 注册监听方法处理消息逻辑\n        consumer.registerMessageListener((MessageListenerConcurrently) (msg, context) -&gt; {\n            System.out.printf(\"%s Receive New Messages: %s %n\", Thread.currentThread().getName(), msg);\n            return ConsumeConcurrentlyStatus.CONSUME_SUCCESS;\n        });\n        // 开启\n        consumer.start();\n    }\n}</code></pre><h3>2.2 推送源码分析</h3><ul><li>在执行DefaultMQPushConsumer.start()方法后</li><li>实际上会开启一个PullMessageService任务</li><li>在PullMessageService这个任务中会轮询执行DefaultMQPushConsumerImpl.pullMessage</li><li>跟踪pullMessage源码发现其实是在Pull模式拉取逻辑上增加一系列延迟请求，一定程度上避免短时间内无效请求</li></ul><pre style=\"text-align: left;\"><code class=\"language-java\">/*\n   开启拉取消息任务\n */\npublic class MQClientInstance {\n\n    public void start() throws MQClientException {\n        ...\n        // Start pull service\n        this.pullMessageService.start();\n        ...\n    }\n}\n/*\n   轮询执行拉取消息请求\n */\npublic class PullMessageService extends ServiceThread {\n    @Override\n    public void run() {\n        while (!this.isStopped()) {\n            try {\n                MessageRequest messageRequest = this.messageRequestQueue.take();\n                // 执行DefaultMQPushConsumerImpl.pullMessage拉取\n                this.pullMessage((PullRequest) messageRequest);\n            } catch (Exception e) {\n                logger.error(\"Pull Message Service Run Method exception\", e);\n            }\n        }\n    }\n}\n/*\n   同Pull模式QClientAPIImpl().pullMessage基础上进一步封装了Pull逻辑；\n   在命中某些条件下执行executePullRequestLater方法延迟请求拉取，避免短时间内大量无效请求\n */\npublic class DefaultMQPushConsumerImpl implements MQConsumerInner {\n    \n    public void pullMessage(final PullRequest pullRequest) {\n\n        // 通过判断各种条件下是否执行延迟处理，避免短时间内大量无效请求\n        if (...) {\n            this.executePullRequestLater(pullRequest, pullTimeDelayMillsWhenException);\n        }\n\n        ...\n\n        // 拉取回调逻辑，执行之前注册的registerMessageListener监听\n        PullCallback pullCallback = new PullCallback() {\n            @Override\n            public void onSuccess(PullResult pullResult) {\n                ...\n            }\n            @Override\n            public void onException(Throwable e) {\n                ...\n            }\n        };\n        \n        ...\n        \n        try {\n            this.pullAPIWrapper.pullKernelImpl(\n                    pullRequest.getMessageQueue(),\n                    subExpression,\n                    ...\n                    ...\n                    pullCallback\n            );\n        } catch (Exception e) {\n            // 延迟请求\n            this.executePullRequestLater(pullRequest, pullTimeDelayMillsWhenException);\n        }\n    }\n}</code></pre><ul><li>在Broker端，收到Consumer拉取请求后如果没有新消息时会将请求挂起一定时间，也可以避免Consumer重复无效请求</li><li>此外如果CommitLog有消息产生，Broker也会主动将消息返回给之前挂起的Consumer，已达到消息消费的及时性</li></ul><pre style=\"text-align: left;\"><code class=\"language-java\">/*\n   没有消息则挂起此次请求\n */\npublic class DefaultPullMessageResultHandler implements PullMessageResultHandler {\n    @Override\n    public RemotingCommand handle(final GetMessageResult getMessageResult,\n                                  final RemotingCommand request,\n                                  ...\n                                  final Channel channel,\n                                  ...\n                                  RemotingCommand response) {\n\n        switch (response.getCode()) {\n            switch (response.getCode()) {\n                case ResponseCode.SUCCESS:\n                    ...\n                    // 有消息则写回Channel\n                case ResponseCode.PULL_NOT_FOUND: // 没有消息\n                    ...\n                    // 挂起请求\n                    this.brokerController.getPullRequestHoldService().suspendPullRequest(topic, queueId, pullRequest);\n                    return null;\n                ...\n            }\n        }\n    }\n}\n/*\n   CommitLog有新消息主动通知Consumer来拉取消息\n */\npublic class NotifyMessageArrivingListener implements MessageArrivingListener {\n    @Override\n    public void arriving(String topic, int queueId, long logicOffset, long tagsCode,\n                         long msgStoreTime, byte[] filterBitMap, Map&lt;String, String&gt; properties) {\n        // 通知挂起的客户端请求消息到达，实际上是重新执行PullMessageProcessor.this.processRequest(channel, request, false, brokerAllowFlowCtrSuspend)这个方法，\n        // 重新执行客户端的拉取请求查找消息并响应。\n        this.pullRequestHoldService.notifyMessageArriving(topic, queueId, logicOffset, tagsCode,\n                msgStoreTime, filterBitMap, properties);\n        ...\n    }\n}</code></pre><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">最后</span> </h2><p>目前为止通过源码跟踪我们可以发现，RocketMq的Push模式的实现和我们通常了解的实现上有一定的差异，它是由由Consumer主要来发起拉取请求去Broker拉取，<br>但是Rocketmq通过对拉取逻辑的一系列封装，以及采用<span style=\"color: black;\"><strong>长轮询</strong></span>机制让Consumer请求挂起避免短轮询无效请求，同时Broker在消息产生时也会及时通知挂起的Consumer来拉取消息，最终达到了Push的效果。</p><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>Tip</code></span>：我本人在多年的开发经验中常用的MQ中间件如Kafka、RocketMQ都实战使用的，简单的使用示例可以参考我Git。</p><pre style=\"text-align: left;\"><code class=\"language-hljs\">https://gitee.com/yeeevip/yeee-memo/tree/master/middle-ware/mq\nhttps://github.com/yeeevip/yeee-memo/tree/master/middle-ware/mq</code></pre><p><br></p>', '一页、Yeeee', 1, 0, 1, '2023-12-08 16:50:19', 0, NULL, 120, 17, NULL, 0, 'admin', '2023-12-08 16:50:25', 'admin', '2023-12-08 17:45:22');
INSERT INTO `t_blog_article` VALUES (30, 6, 'RocketMQ源码（三）简单探索Producer和Consumer与Queue之间的负载均衡策略', NULL, '<p style=\"text-align: start;\">在<strong>RocketMQ</strong>架构中，我们都知道一个topic下可以创建多个queue，生产者通过负载均衡策略可以将消息均匀的分发在各个queue中，而这些queue<br>可以通过负载均衡给多个消费者订阅从而提升消费效率，本文将从以下两个方面从源码角度分析producer和consumer的负载均衡原理：</p><ul><li style=\"text-align: start;\">Producer如何将消息负载均衡发送给queue？</li><li style=\"text-align: start;\">Consumer如何通过负载均衡并发消费queue的消息？</li></ul><p style=\"text-align: start;\"><span style=\"background-color: rgba(27, 31, 35, 0.05); font-size: 12px;\"><code>Tip</code></span>：<span style=\"background-color: rgba(27, 31, 35, 0.05); font-size: 12px;\"><code>以下是本人经过多年的工作经验集成的JavaWeb脚手架，封装了各种通用的starter可开箱即用，同时列举了互联网各种高性能场景的使用示例。</code></span></p><pre style=\"text-align: start;\"><code class=\"language-lang-javascript hljs\">// Git代码\nhttps://gitee.com/yeeevip/yeee-memo\nhttps://github.com/yeeevip/yeee-memo\n</code></pre><h2 style=\"text-align: start;\">1 Producer下的负载均衡</h2><blockquote style=\"text-align: start;\">在Producer下主要指的是通过负载均衡算法去选择一个queue去发送消息，这里默认使用的策略是轮询的方式按顺序选择Queue。</blockquote><p style=\"text-align: start;\"><img src=\"https://ucc.alicdn.com/pic/developer-ecology/xqgum2ntjxgkq_158e8d5d430c4a4faa6dc2f47ae47e4a.png\" alt=\"20231226-01.png\" data-href=\"\" style=\"height: auto;\"></p><h3 style=\"text-align: start;\">1.1 源码分析</h3><ul><li style=\"text-align: start;\"><span style=\"background-color: rgba(27, 31, 35, 0.05); font-size: 12px;\"><code>1</code></span> <span style=\"background-color: rgba(27, 31, 35, 0.05); font-size: 12px;\"><code>在没有指定Queue发送消息时，会调用到MQFaultStrategy.selectOneMessageQueue方法</code></span></li><li style=\"text-align: start;\"><span style=\"background-color: rgba(27, 31, 35, 0.05); font-size: 12px;\"><code>2</code></span> <span style=\"background-color: rgba(27, 31, 35, 0.05); font-size: 12px;\"><code>selectOneMessageQueue中调用tpInfo.selectOneMessageQueue()</code></span></li><li style=\"text-align: start;\"><span style=\"background-color: rgba(27, 31, 35, 0.05); font-size: 12px;\"><code>3</code></span> <span style=\"background-color: rgba(27, 31, 35, 0.05); font-size: 12px;\"><code>进而使用轮询算法从该Topic下的所有Queue里选择一个queue去发送消息</code></span></li></ul><h4 style=\"text-align: start;\">1.1.1 核心代码</h4><pre style=\"text-align: start;\"><code class=\"language-lang-java hljs\">public class MQFaultStrategy {\n   \n   \n    public MessageQueue selectOneMessageQueue(final TopicPublishInfo tpInfo, final String lastBrokerName, final boolean resetIndex) {\n   \n   \n        ...\n        ...\n        return tpInfo.selectOneMessageQueue();\n    }\n}\n/*\n    轮询算法：维护一个全局的index，每次都+1再与Queue的size求余\n */\npublic class TopicPublishInfo {\n   \n   \n    public MessageQueue selectOneMessageQueue() {\n   \n   \n        int index = this.sendWhichQueue.incrementAndGet();\n        int pos = index % this.messageQueueList.size();\n        return this.messageQueueList.get(pos);\n    }\n}\n</code></pre><h2 style=\"text-align: start;\">2 Consumer下的负载均衡</h2><blockquote style=\"text-align: start;\">由于Consumer在广播模式下会把消息发给所有消费者，所以这里我们讨论的是集群模式下queue与消费者的负载均衡；Rocketmq中规定一个Queue只能被一个消费者订阅，而一个消费者可以订阅多个Queue，这样自然会涉及到消费者与Queue分配协调策略。当Broker扩容或缩容、Queue扩容等场景都可能导致消费者所订阅Topic的队列数量发生变化，也会再次重新分配。</blockquote><h3 style=\"text-align: start;\">2.1 分配策略算法</h3><p style=\"text-align: start;\">Rocketmq提供了多种Queue分配策略算法，如下</p><ul><li style=\"text-align: start;\">AllocateMessageQueueAveragely</li></ul><p style=\"text-align: start;\"><img src=\"https://ucc.alicdn.com/pic/developer-ecology/xqgum2ntjxgkq_c831d46ff79f46059a04fe76e815e104.png\" alt=\"20231226-02.png\" data-href=\"\" style=\"height: auto;\"></p><ul><li style=\"text-align: start;\">AllocateMessageQueueAveragelyByCircle</li></ul><p style=\"text-align: start;\"><img src=\"https://ucc.alicdn.com/pic/developer-ecology/xqgum2ntjxgkq_2fe730be827348d5886be1ff213a1b2e.png\" alt=\"20231226-03.png\" data-href=\"\" style=\"height: auto;\"></p><ul><li style=\"text-align: start;\">AllocateMessageQueueConsistentHash</li></ul><p style=\"text-align: start;\"><img src=\"https://ucc.alicdn.com/pic/developer-ecology/xqgum2ntjxgkq_212e86c269164ba6bb1292fb32f27291.png\" alt=\"20231226-04.png\" data-href=\"\" style=\"height: auto;\"></p><h3 style=\"text-align: start;\">2.2 源码分析</h3><ul><li style=\"text-align: start;\"><span style=\"background-color: rgba(27, 31, 35, 0.05); font-size: 12px;\"><code>1</code></span> <span style=\"background-color: rgba(27, 31, 35, 0.05); font-size: 12px;\"><code>创建DefaultMQPushConsumer时默认使用AllocateMessageQueueAveragely分配策略，即平均分配算法</code></span></li><li style=\"text-align: start;\"><span style=\"background-color: rgba(27, 31, 35, 0.05); font-size: 12px;\"><code>2</code></span> <span style=\"background-color: rgba(27, 31, 35, 0.05); font-size: 12px;\"><code>consumer调用start启动时会调用到RebalanceService.start()开启一个任务</code></span></li><li style=\"text-align: start;\"><span style=\"background-color: rgba(27, 31, 35, 0.05); font-size: 12px;\"><code>3</code></span> <span style=\"background-color: rgba(27, 31, 35, 0.05); font-size: 12px;\"><code>RebalanceService会调用到RebalanceImpl.rebalanceByTopic执行具体的平衡策略</code></span></li><li style=\"text-align: start;\"><span style=\"background-color: rgba(27, 31, 35, 0.05); font-size: 12px;\"><code>4</code></span> <span style=\"background-color: rgba(27, 31, 35, 0.05); font-size: 12px;\"><code>进而拿到所有的Consumer和Queue使用设置的AllocateMessageQueueStrategy算法去分配订阅关系</code></span></li></ul><h4 style=\"text-align: start;\">2.2.1 核心代码</h4><pre style=\"text-align: start;\"><code class=\"language-lang-java hljs\">/*\n   1.初始化：默认使用AllocateMessageQueueAveragely算法分配Queue\n */\npublic class DefaultMQPushConsumer extends ClientConfig implements MQPushConsumer {\n   \n   \n    public DefaultMQPushConsumer(final String consumerGroup) {\n   \n   \n        this(null, consumerGroup, null, new AllocateMessageQueueAveragely());\n    }\n}\n/*\n   2.开启一个RebalanceService任务执行分配策略\n */\npublic class MQClientInstance {\n   \n   \n    public void start() throws MQClientException {\n   \n   \n        synchronized (this) {\n   \n   \n            switch (this.serviceState) {\n   \n   \n                case CREATE_JUST:\n                    ...\n                    // Start rebalance service\n                    this.rebalanceService.start();\n                    ...\n                default:\n                    break;\n            }\n        }\n    }\n}\n/*\n   3.RebalanceImpl.rebalanceByTopic执行具体的分配逻辑\n */\npublic abstract class RebalanceImpl {\n   \n   \n    private boolean rebalanceByTopic(final String topic, final boolean isOrder) {\n   \n   \n        boolean balanced = true;\n        switch (messageModel) {\n   \n   \n            ...\n            case CLUSTERING: {\n   \n   \n                // 拿到所有的Queue\n                Set&lt;MessageQueue&gt; mqSet = this.topicSubscribeInfoTable.get(topic);\n                // 拿到所有的消费者ID\n                List&lt;String&gt; cidAll = this.mQClientFactory.findConsumerIdList(topic, consumerGroup);\n                ...\n                if (mqSet != null &amp;&amp; cidAll != null) {\n   \n   \n                    List&lt;MessageQueue&gt; mqAll = new ArrayList&lt;&gt;();\n                    mqAll.addAll(mqSet);\n\n                    Collections.sort(mqAll);\n                    Collections.sort(cidAll);\n\n                    // 初始化设置的分配算法：即AllocateMessageQueueAveragely平均分配算法\n                    AllocateMessageQueueStrategy strategy = this.allocateMessageQueueStrategy;\n\n                    List&lt;MessageQueue&gt; allocateResult = null;\n                    try {\n   \n   \n                        // 调用分配算法的具体实现\n                        allocateResult = strategy.allocate(...mqAll, cidAll);\n                    } catch (Throwable e) {\n   \n   \n                        log.error(\"allocate message queue exception. strategy name: {}, ex: {}\", strategy.getName(), e);\n                        return false;\n                    }\n                    ...\n                }\n                break;\n            }\n            default:\n                break;\n        }\n        return balanced;\n    }\n}\n/*\n   4.执行AllocateMessageQueueAveragely平均分配算法的具体实现\n */\npublic class AllocateMessageQueueAveragely extends AbstractAllocateMessageQueueStrategy {\n   \n   \n    @Override\n    public List&lt;MessageQueue&gt; allocate(String consumerGroup, String currentCID, List&lt;MessageQueue&gt; mqAll, List&lt;String&gt; cidAll) {\n   \n   \n\n        List&lt;MessageQueue&gt; result = new ArrayList&lt;&gt;();\n        if (!check(consumerGroup, currentCID, mqAll, cidAll)) {\n   \n   \n            return result;\n        }\n\n        int index = cidAll.indexOf(currentCID);\n        int mod = mqAll.size() % cidAll.size();\n        int averageSize =\n                mqAll.size() &lt;= cidAll.size() ? 1 : (mod &gt; 0 &amp;&amp; index &lt; mod ? mqAll.size() / cidAll.size()\n                        + 1 : mqAll.size() / cidAll.size());\n        int startIndex = (mod &gt; 0 &amp;&amp; index &lt; mod) ? index * averageSize : index * averageSize + mod;\n        int range = Math.min(averageSize, mqAll.size() - startIndex);\n        for (int i = 0; i &lt; range; i++) {\n   \n   \n            result.add(mqAll.get((startIndex + i) % mqAll.size()));\n        }\n        return result;\n    }\n}\n</code></pre><h2 style=\"text-align: start;\">最后</h2><p style=\"text-align: start;\">至此，通过源码探索我们就大致了解了Producer及Consumer的负载均衡策略，其中Producer主要是通过轮询方式依次把消息发送到Queue，而Consumer默认使用的<br>平均分配算法去解决消费者节点与Queue之间的分配订阅关系。</p><p style=\"text-align: start;\"><span style=\"background-color: rgba(27, 31, 35, 0.05); font-size: 12px;\"><code>Tip</code></span>：<span style=\"background-color: rgba(27, 31, 35, 0.05); font-size: 12px;\"><code>以下是本人经过多年的工作经验集成的JavaWeb脚手架，封装了各种通用的starter可开箱即用，同时列举了互联网各种高性能场景的使用示例。</code></span></p><pre style=\"text-align: start;\"><code class=\"language-lang-javascript hljs\">// Git代码\nhttps://gitee.com/yeeevip/yeee-memo\nhttps://github.com/yeeevip/yeee-memo</code></pre><p><br></p>', '一页', 1, 0, 1, '2024-02-04 19:06:15', 0, NULL, 136, 3, NULL, 0, 'admin', '2023-12-08 16:50:25', 'admin', '2024-02-05 10:09:44');
INSERT INTO `t_blog_article` VALUES (31, 1, '基于springboot+vue快速搭建一个轻量级实用的博客系统', NULL, NULL, '一页', 1, 0, 1, '2023-08-11 10:16:28', 1, 'https://mp.weixin.qq.com/s/Dt9rPyUn-o-u1DOMLMCRmg', 142, 0, '基于springboot+vue快速搭建一个轻量级实用的博客系统', 0, 'admin', '2024-02-05 10:16:40', 'admin', '2024-07-11 09:27:24');
INSERT INTO `t_blog_article` VALUES (32, 8, '程序运行报错分享 java: Internal error in the mapping processor: java.lang.NullPointerException', NULL, '<p style=\"text-align: start;\">问题</p><p style=\"text-align: start;\">java: Internal error in the mapping processor: java.lang.NullPointerException at org.mapstruct.ap.internal.processor.DefaultVersionInformation.createManifestUrl(DefaultVersionInformation.java:182) at org.mapstruct.ap.internal.processor.DefaultVersionInformation.openManifest(DefaultVersionInformation.java:153) at org.mapstruct.ap.internal.processor.DefaultVersionInformation.getLibraryName(DefaultVersionInformation.java:129) at org.mapstruct.ap.internal.processor.DefaultVersionInformation.getCompiler(DefaultVersionInformation.java:122) at</p><p style=\"text-align: start;\">————————————————</p><p style=\"text-align: start;\">原因</p><p style=\"text-align: start;\">项目中使用了mapstruct框架，在使用Idea新版本后，启动会报错！</p><p style=\"text-align: start;\"><br></p><p style=\"text-align: start;\">解决办法</p><p style=\"text-align: start;\">idea加启动参数</p><p style=\"text-align: start;\">修改Setting --&gt;Build,Execution,Deployment --&gt;Compiler --&gt;User-local build process VM options (overrides Shared options):</p><p style=\"text-align: start;\">加入参数</p><p style=\"text-align: start;\">-Djps.track.ap.dependencies=false</p>', '一页', 0, 0, 1, '2024-03-02 17:25:11', 0, NULL, 114, 141, NULL, 0, 'admin', '2024-03-02 17:25:15', 'admin', '2024-03-03 14:20:29');
INSERT INTO `t_blog_article` VALUES (33, 6, 'Redisson源码（一）RedissonLock加锁与解锁过程原理分析', NULL, '<p>在当今分布式微服务架构流行的情况下，显然在传统单体项目中使用的JDK自带的锁已经不能解决资源竞争的问题了，<br>进而出现的解决方案有1)利用数据库 2)redis 3)zookeeper，经过验证的是利用redis做分布式锁无论在可用性、可靠性上比较有优势。<br>而使用<span style=\"color: black;\"><strong>Redisson</strong></span>来做分布式锁很多人在熟悉不过了，它提供的Lock就是基于redis来做的。</p><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>Tip</code></span>：<span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>以下是本人经过多年的工作经验集成的JavaWeb脚手架，封装了各种通用的starter可开箱即用，同时列举了互联网各种高性能场景的使用示例。</code></span></p><pre style=\"text-align: left;\"><code class=\"language-hljs\">// Git代码\nhttps://gitee.com/yeeevip/yeee-memo\nhttps://github.com/yeeevip/yeee-memo</code></pre><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">1 Redisson锁的基本使用</span> </h2><p>JDK提供的Lock、CountDownLatch、Semaphore等解决资源竞争/协调的并发辅助工具API在Redisson框架同样也提供了，区别就是它是支持分布式的，<br>并且使用的方式也和JDK中大同小异。</p><h3>1.1 执行流程</h3><p><img src=\"./images/20240223-01.png\" alt=\"\" data-href=\"\" style=\"\"/></p><h3>1.2 Lock的使用示例</h3><p>我们来看一下最基本的使用示例代码：</p><pre style=\"text-align: left;\"><code class=\"language-java\">public class LockExample {\n    \n    public void testLock() {\n        RLock lock = redissonClient.getLock(\"testLockKey\");\n        // 1.最常用的使用方法\n        lock.lock();\n        try {\n            // 2.执行业务\n            doSomeThing();\n        } finally {\n            // 3.解锁\n            lock.unlock();\n        }\n    }\n}</code></pre><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>Tip</code></span>：<span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>我工作中Redisson各种锁的具一些体使用示例Demo，有兴趣的可以参考一下</code></span></p><pre style=\"text-align: left;\"><code class=\"language-hljs\">// Git代码\nhttps://gitee.com/yeeevip/yeee-memo/tree/master/solution-problem/distribute-lock/distribute-lock-redisson/src/main/java/vip/yeee/memo/demo/distribute/lock/redisson/example</code></pre><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">2 加锁过程分析</span> </h2><h3>2.1 代码执行分析</h3><ul><li>1.通过redissonClient调用getLock()方法获取到锁对象</li></ul><blockquote>getLock获取到的是非公平锁，非公平锁不严格要求先到先得，后面申请加锁的线程有可能会比之前等待的提前拿到锁。</blockquote><ul><li>2.然后通过锁对象调用lock()方法进行加锁</li><li>3.使用当前线程ID执行tryAcquire()尝试获取锁，若获取到锁直接返回</li></ul><blockquote>这里tryAcquire()方法会调用redis服务器执行Lua脚本命令获取锁； 还有一点就是加锁成功后会有watchdog机制给锁续期防止业务执行时锁释放了。</blockquote><ul><li>4.若没有获取到锁时，会给该线程向channel订阅锁通知，同时继续自旋尝试获取锁</li></ul><blockquote>向channel订阅后，锁释放后可以收到通知立即去尝试获取锁； 自旋获取并不是说直接无限调用tryAcquire，而是根据上次tryAcquire返回的ttl阻塞等待后才再次tryAcquire</blockquote><h4>2.1.1 Java核心代码</h4><pre style=\"text-align: left;\"><code class=\"language-java\">public class RedissonLock {\n    \n    private void lock(long leaseTime, TimeUnit unit, boolean interruptibly) {\n        // 获取当前线程ID\n        long threadId = Thread.currentThread().getId();\n        \n        // 尝试加锁，返回值为需要等待的时间，若为空则表示当前线程加锁成功\n        Long ttl = tryAcquire(-1, leaseTime, unit, threadId);\n        if (ttl == null) {\n            return;\n        }\n        \n        // 尝试加锁若没有成功\n        \n        // 1.该线程向channel订阅锁通知\n        RFuture&lt;RedissonLockEntry&gt; future = subscribe(threadId);\n        ...\n\n        try {\n            while (true) {\n                ttl = tryAcquire(-1, leaseTime, unit, threadId);\n                \n                // ttl为null，说明获取成功，返回\n                if (ttl == null) {\n                    break;\n                }\n                // 若锁有效期ttl大于0，则阻塞ttl后继续获取，防止空自旋\n                if (ttl &gt;= 0) {\n                    try {\n                        future.getNow().getLatch().tryAcquire(ttl, TimeUnit.MILLISECONDS);\n                    } catch (InterruptedException e) {\n                        if (interruptibly) {\n                            throw e;\n                        }\n                        future.getNow().getLatch().tryAcquire(ttl, TimeUnit.MILLISECONDS);\n                    }\n                } else {\n                    ...\n                }\n            }\n        } finally {\n            unsubscribe(future, threadId);\n        }\n    }\n}</code></pre><h4>2.1.2 Lua脚本代码</h4><pre style=\"text-align: left;\"><code class=\"language-lua\">-- KEYS[1] = 锁对象唯一键\n-- ARGV[1] = 锁过期时间\n-- ARGV[2] = 加锁线程ID\n\n-- 还没有线程加锁\nif (redis.call(\'exists\', KEYS[1]) == 0) then\n-- 当前线程占有锁\nredis.call(\'hincrby\', KEYS[1], ARGV[2], 1);\n-- 并设置过期时间\nredis.call(\'pexpire\', KEYS[1], ARGV[1]);\nreturn nil;\nend;\n\n-- 若该线程已经持有锁\nif (redis.call(\'hexists\', KEYS[1], ARGV[2]) == 1) then\n-- 重入次数+1\nredis.call(\'hincrby\', KEYS[1], ARGV[2], 1);\n-- 设置过期时间\nredis.call(\'pexpire\', KEYS[1], ARGV[1]);\nreturn nil;\nend;\n\n-- 锁被其他线程占有，则返回剩余有效期\nreturn redis.call(\'pttl\', KEYS[1]);</code></pre><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">3 解锁过程分析</span> </h2><h3>3.1 代码执行分析</h3><p>解锁逻辑相对比较简单</p><ul><li>1.使用unlock()方法进行解锁</li><li>2.根据当前线程再调用unlockInnerAsync()方法执行lua命令解锁</li></ul><h4>3.1.1 Java核心代码</h4><pre style=\"text-align: left;\"><code class=\"language-java\">public class RedissonLock {\n    public void unlock() {\n        ...\n        unlockAsync(Thread.currentThread().getId());\n        ...\n    }\n    public RFuture&lt;Void&gt; unlockAsync(long threadId) {\n        ...\n        // 这个方法去执行Lua命令\n        unlockInnerAsync(threadId);\n        ...\n    }\n}</code></pre><h4>3.1.2 Lua脚本代码</h4><pre style=\"text-align: left;\"><code class=\"language-lua\">-- KEYS[1] = 锁对象唯一键\n-- KEYS[2] = 该锁发布订阅channel\n-- ARGV[1] = UNLOCK_MESSAGE\n-- ARGV[2] = 锁过期时间\n-- ARGV[3] = 加锁线程ID\n\n-- 该线程未持有锁直接返回\nif (redis.call(\'hexists\', KEYS[1], ARGV[3]) == 0) then\nreturn nil;\nend;\n\n-- 该线程重入次数-1\nlocal counter = redis.call(\'hincrby\', KEYS[1], ARGV[3], -1);\n\n-- 如果重入次数还大于0\nif (counter &gt; 0) then\n-- 重置该线程锁过期时间\nredis.call(\'pexpire\', KEYS[1], ARGV[2]);\nreturn 0;\n-- 重入次数等于0了\nelse\n-- 释放锁\nredis.call(\'del\', KEYS[1]);\n-- 向channel发布锁释放消息\nredis.call(\'publish\', KEYS[2], ARGV[1]);\nreturn 1;\nend;\nreturn nil;</code></pre><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">最后</span> </h2><p>Redission锁的原理我大致已经介绍完了，有问题的可以私聊我或者评论区留意~ 之后我会介绍Redission的延迟队列原理，感兴趣的话持续关注哦。</p><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>Tip</code></span>：<span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>以下是本人经过多年的工作经验集成的JavaWeb脚手架，封装了各种通用的starter可开箱即用，同时列举了互联网各种高性能场景的使用示例。</code></span></p><pre style=\"text-align: left;\"><code class=\"language-hljs\">//&nbsp;Git代码\nhttps://gitee.com/yeeevip/yeee-memo\nhttps://github.com/yeeevip/yeee-memo</code></pre><p><br></p>', '一页', 1, 0, 1, '2024-03-03 13:51:39', 0, NULL, 173, 8, NULL, 0, 'admin', '2024-03-03 13:52:00', 'admin', '2024-03-03 14:09:14');
INSERT INTO `t_blog_article` VALUES (34, 1, '基于Springboot+SpringSecurity+Activiti7实现的工作流系统可方便二次开发(附完整源码)', NULL, NULL, '一页', 1, 0, 1, '2023-08-11 14:02:21', 1, 'https://mp.weixin.qq.com/s?__biz=MjM5NjU5OTA1Mg==&mid=2449736474&idx=1&sn=0cedef6a381dd5bba58316924ac35b20&chksm=b11667798661ee6f6a60db374af73b87dbfafffe6d2af61c496105a78425076e7c7e9d5e8a1a&token=912724513&lang=zh_CN#rd', 90, 0, NULL, 0, 'admin', '2024-03-03 14:02:42', 'admin', '2024-07-11 09:27:06');
INSERT INTO `t_blog_article` VALUES (35, 6, 'Redisson源码（二）延迟队列RDelayedQueue的使用及原理分析', NULL, '<p>在工作中，我们有时候会遇到这样的场景，比如下单之后超过30分钟未支付自动取消订单，还有就比如过期/生效通知等等，这些场景一般有两种方法解决：<br>第一种可以通过定时任务扫描符合条件的去执行，第二种就是提前通过消息队列发送延迟消息到期自动消费。<br>本文我要介绍的就是通过第二种方式来实现这种业务逻辑，只不过这次不是使用MQ而是直接使用的是Redission提供的RDelayedQueue延迟队列。</p><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>Tip</code></span>：<span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>以下是本人经过多年的工作经验集成的JavaWeb脚手架，封装了各种通用的starter可开箱即用，同时列举了互联网各种高性能场景的使用示例。</code></span></p><pre style=\"text-align: left;\"><code class=\"language-hljs\">// Git代码\nhttps://gitee.com/yeeevip/yeee-memo\nhttps://github.com/yeeevip/yeee-memo</code></pre><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">1 延迟队列RDelayedQueue的简单用法</span> </h2><ul><li>生产者端</li></ul><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>1</code></span> 通过redissonClient的getBlockingDeque方法指定队列名称获得RBlockingDeque对象</p><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>2</code></span> 然后再通过redissonClient的getDelayedQueue方法传入RBlockingDeque对象获得RDelayedQueue对象</p><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>3</code></span> 最后调用RDelayedQueue对象的offer方法就可以将消息指定延迟时间发送到延迟队列了</p><pre style=\"text-align: left;\"><code class=\"language-java\">@Component\npublic class DelayQueueKit {\n\n    // 注入RedissonClient实例\n    @Resource\n    private RedissonClient redissonClient;\n\n    /**\n     * 添加消息到延迟队列\n     *\n     * @param queueCode 队列唯一KEY\n     * @param msg       消息\n     * @param delay     延迟时间\n     * @param timeUnit  时间单位\n     */\n    public &lt;T&gt; void addDelayQueue(String queueCode, T msg, long delay, TimeUnit timeUnit) {\n        RBlockingDeque&lt;T&gt; blockingDeque = redissonClient.getBlockingDeque(queueCode);\n        RDelayedQueue&lt;T&gt; delayedQueue = redissonClient.getDelayedQueue(blockingDeque);\n        // 这一步通过offer插入到队列\n        delayedQueue.offer(msg, delay, timeUnit);\n    }\n}</code></pre><ul><li>消费者端</li></ul><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>1</code></span> 通过redissonClient获取RBlockingDeque对象</p><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>2</code></span> 通过RBlockingDeque对象获取RDelayedQueue</p><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>3</code></span> 之后RBlockingDeque再通过自旋调用take方法获取到期的消息，没有消息时会阻塞的。</p><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>Tip</code></span> 一般情况下我们在程序刚启动时异步开一个线程去自旋消费队列消息的</p><pre style=\"text-align: left;\"><code class=\"language-java\">@Component\npublic class DelayQueueKit {\n\n    // 注入RedissonClient实例\n    @Resource\n    private RedissonClient redissonClient;\n\n    public &lt;T&gt; void consumeQueueMsg(String queueCode) {\n        RBlockingDeque&lt;T&gt; delayQueue = redissonClient.getBlockingDeque(queueCode);\n        RDelayedQueue&lt;T&gt; delayedQueue = redissonClient.getDelayedQueue(blockingDeque);\n        log.info(\"【队列-{}】- 监听队列成功\", queueCode);\n        while (true) {\n            T message = null;\n            try {\n                message = delayQueue.take();\n                // 处理自己的业务\n                handleMessage(message);\n                log.info(\"【队列-{}】- 处理元素成功 - ele = {}\", queueCode, ele);\n            } catch (Exception e) {\n                log.error(\"【队列-{}】- 处理元素失败 - ele = {}\", queueCode, ele, e);\n            }\n        }\n    }\n}</code></pre><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>Tip</code></span>：<span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>以下是我工作中使用并封装的DelayQueueKit的完整工具类代码，有兴趣的可以参考一下</code></span></p><pre style=\"text-align: left;\"><code class=\"language-hljs\">// Git代码\nhttps://gitee.com/yeeevip/yeee-memo/blob/master/memo-parent/memo-common/common-kit/common-redisson-kit/src/main/java/vip/yeee/memo/common/redisson/kit/DelayQueueKit.java</code></pre><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">2 数据结构设计</span> </h2><p>Redission实现延迟队列消息用到了四个数据结构：</p><p><img src=\"./images/20240229-01.png\" alt=\"\" data-href=\"\" style=\"\"/></p><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>redisson_delay_queue_timeout:{queue_name}</code></span> 定期队列，ZSET结构（value为消息，score为过期时间），这样就可以知道当前过期的消息。</p><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>redisson_delay_queue:{queue_name}</code></span> 顺序队列，LIST结构，按照消息添加顺序存储，移除消息时可以按照添加顺序删除。</p><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>redisson_delay_queue_channel:{queue_name}</code></span> 发布订阅channel主题，用于通知客户端定时器从定期队列转移到期的消息到目标队列。</p><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>{queue_name}</code></span> 目标队列，LIST结构，存储实际到期可以被消费的消息供消费者拉取消费。</p><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">3 消息生产源码分析</span> </h2><ol><li>通过redissonClient.getDelayedQueue获取RDelayedQueue对象</li><li>然后delayedQueue调用offer方法去保存消息</li><li>最后真正的保存逻辑是由RedissonDelayedQueue执行offerAsync方法调用的lua脚本</li></ol><pre style=\"text-align: left;\"><code class=\"language-java\">public class RedissonDelayedQueue&lt;V&gt; extends RedissonExpirable implements RDelayedQueue&lt;V&gt; {\n    @Override\n    public RFuture&lt;Void&gt; offerAsync(V e, long delay, TimeUnit timeUnit) {\n        if (delay &lt; 0) {\n            throw new IllegalArgumentException(\"Delay can\'t be negative\");\n        }\n        long delayInMs = timeUnit.toMillis(delay);\n        // 消息过期时间 = 当前时间 + 延迟时间\n        long timeout = System.currentTimeMillis() + delayInMs;\n        // 生成随机id，应该是为了允许插入到zset重复的消息\n        long randomId = ThreadLocalRandom.current().nextLong();\n        // 执行脚本\n        return commandExecutor.evalWriteAsync(getName(), codec, RedisCommands.EVAL_VOID,\n            // 将消息打包成二进制的， 打包的消息 = 随机数 + 消息，有了随机数意味着消息就可以重复\n            \"local value = struct.pack(\'dLc0\', tonumber(ARGV[2]), string.len(ARGV[3]), ARGV[3]);\"\n            // 将 打包的消息和过期时间 插入redisson_delay_queue_timeout队列\n            + \"redis.call(\'zadd\', KEYS[2], ARGV[1], value);\"\n            // 顺序插入redisson_delay_queue队列\n            + \"redis.call(\'rpush\', KEYS[3], value);\"\n            // 如果刚插入的消息就是timeout队列的最前面，即刚插入的消息最近要到期\n            + \"local v = redis.call(\'zrange\', KEYS[2], 0, 0); \"\n            + \"if v[1] == value then \"\n            // 发布消息通知客户端消息到期时间，让它定期执行转移操作\n            + \"redis.call(\'publish\', KEYS[4], ARGV[1]); \"\n            + \"end;\",\n            Arrays.&lt;Object&gt;asList(getName(), timeoutSetName, queueName, channelName),\n            // 三个参数：1-过期时间 2-随机数 3-消息\n            timeout, randomId, encode(e));\n    }\n}</code></pre><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">4 定时器转移消息源码分析</span> </h2><p>大家如果仅仅使用而没有看过源码的可能不太容易知道redission究竟哪里执行的定时器去定时转移到期消息的，我也是最近看源码才知道，<br>其实就是在调用redissonClient.getDelayedQueue获取RDelayedQueue对象时创建的：</p><ol><li>通过redissonClient.getDelayedQueue获取RDelayedQueue对象</li><li>然后会执行RedissonDelayedQueue的构造函数方法</li><li>在这个构造方法里就会新建QueueTransferTask这个对象去执行转移操作</li></ol><pre style=\"text-align: left;\"><code class=\"language-java\">public class Redisson implements RedissonClient {\n    @Override\n    public &lt;V&gt; RDelayedQueue&lt;V&gt; getDelayedQueue(RQueue&lt;V&gt; destinationQueue) {\n        if (destinationQueue == null) {\n            throw new NullPointerException();\n        }\n        // 执行RedissonDelayedQueue构造方法\n        return new RedissonDelayedQueue&lt;V&gt;(queueTransferService, destinationQueue.getCodec(), connectionManager.getCommandExecutor(), destinationQueue.getName());\n    }\n}\npublic class RedissonDelayedQueue&lt;V&gt; extends RedissonExpirable implements RDelayedQueue&lt;V&gt; {\n    protected RedissonDelayedQueue(QueueTransferService queueTransferService, Codec codec, final CommandAsyncExecutor commandExecutor, String name) {\n        ...\n        QueueTransferTask task = new QueueTransferTask(commandExecutor.getConnectionManager()) {\n            @Override\n            protected RFuture&lt;Long&gt; pushTaskAsync() {\n                return commandExecutor.evalWriteAsync(getName(), LongCodec.INSTANCE, RedisCommands.EVAL_LONG,\n                    // 从redisson_delay_queue_timeout队列获取100个到期的消息\n                    \"local expiredValues = redis.call(\'zrangebyscore\', KEYS[2], 0, ARGV[1], \'limit\', 0, ARGV[2]); \"\n                    + \"if #expiredValues &gt; 0 then \"\n                    + \"for i, v in ipairs(expiredValues) do \"\n                    // 将包装的消息执行解包操作，随机数 + 原消息        \n                    + \"local randomId, value = struct.unpack(\'dLc0\', v);\"\n                    // 将原消息插入到{queue_name}队列，就可以被消费了        \n                    + \"redis.call(\'rpush\', KEYS[1], value);\"\n                    + \"redis.call(\'lrem\', KEYS[3], 1, v);\"\n                    + \"end; \"\n                    // 转移后redisson_delay_queue_timeout队列也移除这些消息        \n                    + \"redis.call(\'zrem\', KEYS[2], unpack(expiredValues));\"\n                    + \"end; \"\n                    // 从定时队列获取最近到期时间然后供定时器到时间再执行\n                    + \"local v = redis.call(\'zrange\', KEYS[2], 0, 0, \'WITHSCORES\'); \"\n                    + \"if v[1] ~= nil then \"\n                    + \"return v[2]; \"\n                    + \"end \"\n                    + \"return nil;\",\n                    Arrays.&lt;Object&gt;asList(getName(), timeoutSetName, queueName),\n                    System.currentTimeMillis(), 100);\n            }\n            // 主题redisson_delay_queue_channel:{queue_name}注册发布/订命令执行阅监听器\n            @Override\n            protected RTopic getTopic() {\n                return new RedissonTopic(LongCodec.INSTANCE, commandExecutor, channelName);\n            }\n        };\n        // 将定时器命令执行逻辑注册到发布/订阅主题，这样就可以在收到订阅时执行转移操作了\n        queueTransferService.schedule(queueName, task);\n        ...\n    }\n}</code></pre><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">5 消息消费源码分析</span> </h2><p>消息消费的逻辑就比较简单了，从RBlockingDeque使用take方法获取消息时，直接调用的就是redis中List的BLPOP命令。</p><blockquote>Redis Blpop 命令移出并获取列表的第一个元素， 如果列表没有元素会阻塞列表直到等待超时或发现可弹出元素为止。</blockquote><pre style=\"text-align: left;\"><code class=\"language-java\">public class RedissonBlockingQueue&lt;V&gt; extends RedissonQueue&lt;V&gt; implements RBlockingQueue&lt;V&gt; {\n    @Override\n    public RFuture&lt;V&gt; takeAsync() {\n        // 执行redis中List的BLPOP命令，从{queue_name}队列阻塞取出元素\n        return commandExecutor.writeAsync(getName(), codec, RedisCommands.BLPOP_VALUE, getName(), 0);\n    }\n}</code></pre><h2><span style=\"color: rgb(255, 255, 255); background-color: rgb(239, 112, 96);\">最后</span> </h2><p>到此为止，Redission延迟队列的使用方式及原理我基本分享到这里了，大家如果有不懂的地方可以评论区留言或者直接私信我哦，同时有细节分析不到位的欢迎大家指出来，来一起学习嘛～</p><p><span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>Tip</code></span>：<span style=\"color: rgb(239, 112, 96); background-color: rgba(27, 31, 35, 0.05); font-size: 14px;\"><code>以下是本人经过多年的工作经验集成的JavaWeb脚手架，封装了各种通用的starter可开箱即用，同时列举了互联网各种高性能场景的使用示例。</code></span></p><pre style=\"text-align: left;\"><code class=\"language-hljs\">// Git代码\nhttps://gitee.com/yeeevip/yeee-memo\nhttps://github.com/yeeevip/yeee-memo</code></pre><p><br></p>', '一页', 1, 0, 1, '2024-03-03 14:06:02', 0, NULL, 614, 81, NULL, 0, 'admin', '2024-03-03 14:02:42', 'admin', '2024-03-03 14:13:19');
