INSERT INTO `t_blog_article` VALUES (37, 8, ' VUE项目：node-sass替换sass解决各种install问题', NULL, '<h2>1. package.json删除node-sass依赖，替换为sass</h2><pre><code class=\"language-javascript\">  \"devDependencies\": {\n    \"node-sass\": \"^4.13.1\",\n    \"sass-loader\": \"^8.0.2\"\n  }\n  \n   \"devDependencies\": {\n    \"sass\": \"1.32.13\",\n    \"sass-loader\": \"^8.0.2\"\n  },</code></pre><h2>2. <span style=\"color: rgb(77, 77, 77); background-color: rgb(255, 255, 255); font-size: 16px;\">全局</span><a href=\"https://so.csdn.net/so/search?q=%E6%A0%B7%E5%BC%8F%E7%A9%BF%E9%80%8F&amp;spm=1001.2101.3001.7020\" target=\"_blank\" style=\"text-align: start;\">样式穿透</a><span style=\"color: rgb(77, 77, 77); background-color: rgb(255, 255, 255); font-size: 16px;\">，/deep/ 替换为 ::v-deep</span></h2><p><br></p><p>node下载</p><p> <a href=\"https://registry.npmmirror.com/binary.html?path=node/latest-v16.x/\" target=\"_blank\">https://registry.npmmirror.com/binary.html?path=node/latest-v16.x/</a> </p>', '一页', 1, 0, 1, '2022-03-08 22:46:34', 0, NULL, 594, 46, NULL, 0, 'admin', '2024-03-23 22:46:40', 'admin', '2024-08-15 17:48:09');

